// ================= ЕДИНЫЙ РЕНДЕРЕР СВИНОЧЕРВЯ (WORM RENDERER) =================
// Строит SVG персонажа из WormModel (см. src/core/worm-model.js) и умеет
// монтироваться в ЛЮБОЙ контейнер — главный экран, любая мини-игра.
//
// Главная идея модульности: части тела — это <g data-part="...">, а шрамы,
// эффекты и будущие аксессуары монтируются КАК ДОЧЕРНИЕ ЭЛЕМЕНТЫ этих групп,
// поэтому при масштабировании сегмента (например, живот раздувается в
// Чревоугодии) все шрамы/украшения на нём растягиваются вместе с ним
// автоматически — через SVG-иерархию, без ручного пересчёта координат.
//
// Контекстные оверрайды: любой экран может временно "подменить" часть модели
// на время своего рендера через handle.setOverride(patch) — базовая
// сохранённая модель игрока при этом не трогается (см. mergeWormOverride).
// "Живой" канал handle.setLivePose(patch) — для непрерывных покадровых
// обновлений (наклон хвоста, раздутие живота, уровень век, открытие/форма
// рта) — не вызывает пересборку SVG, просто переставляет атрибуты уже
// созданных узлов в tick(). Это ЕДИНЫЙ механизм и для главного экрана
// (мимика, "болтовня"), и для любой мини-игры — параметры рта устроены так
// же, как и остальные части тела (веко, живот, хвост): не отдельная логика
// на каждый контекст, а один и тот же setLivePose({ mouthOpenness, mouthCurve }).
//
// Публичный API (mount/update/setOverride/setLivePose/...) и все
// data-part/data-anchor имена НЕ меняются между апгрейдами отрисовки —
// мини-игры, завязанные на них (gluttony.js читает [data-part="mouth"] и
// т.п.), продолжают работать без правок.

const SVG_NS = 'http://www.w3.org/2000/svg';

// ---------- ПАЛИТРА ----------
// Единый источник цвета — src/core/palette.js. Здесь только короткие алиасы,
// чтобы не таскать PALETTE.flesh[500] через весь файл. Захардкоженных hex в
// этом файле быть не должно: правило и его причины — docs/art-direction.md.
const P_ = (typeof PALETTE !== 'undefined') ? PALETTE : window.PALETTE;
const INK = P_.ink;          // замена чёрному: тёмный холодный сливовый
const FLESH = P_.flesh;      // рампа мяса 900(тень) → 100(свет)
const VISCERA = P_.viscera;  // анатомия живой ткани: пасть, дёсны, капилляры
const BILE = P_.bile;        // грязь, налёт, зубы
const SCLERA = P_.sclera;    // белок глаза — костяной, не белый
const SPEC = P_.flesh[100];  // блик на МАТОВОЙ коже — тёплый, не белый
const ACID = P_.acid[200];   // АКЦЕНТ-ирокез: блик на слизи. Только на влажном
const ACID_DEEP = P_.acid[600]; // тёмная кислота — для БОЛЬШИХ мокрых площадей
// Лестница толщин линий. Значений вне лестницы в файле быть не должно —
// причины в docs/art-direction.md §4.4.
const SW = (typeof STROKE !== 'undefined') ? STROKE : window.STROKE;
// Внутренние черты (брови, губа) берут осветлённый контурный тон, а не сам
// INK: внешний контур обязан оставаться самой тёмной линией в кадре.
// Считается ЛЕНИВО: mixColor опирается на кэш разбора цвета, объявленный
// ниже по файлу, поэтому на верхнем уровне его вызывать нельзя (TDZ).
let _inkSoftCache = null;
function inkSoftColor() {
    if (_inkSoftCache == null) {
        const fn = (typeof inkSoft !== 'undefined') ? inkSoft : window.inkSoft;
        _inkSoftCache = fn(mixColor);
    }
    return _inkSoftCache;
}
// Доп. отступ всей телесной цепочки от центра головы, чтобы сегмент-1
// не прятался почти целиком под головой, а минимум наполовину торчал из-под неё.
// Было 24, затем увеличено до 34 — оказалось уже СЛИШКОМ много; 29 —
// середина между "прячется" (24) и "слишком далеко" (34).
const WORM_CHAIN_HEAD_GAP = 29;
// Параметры анимации моргания — см. использование в tick(). Окно короткое
// (быстро), но внутри него уровень век непрерывно меняется по синусоиде
// (плавно), а не щёлкает между двумя состояниями.
const WORM_BLINK_CYCLE = 2600;
const WORM_BLINK_START = 2200;
const WORM_BLINK_DURATION = 220;
// Форма рта (см. updateMouthGeometry): "магическая" константа приближения
// четверти окружности/эллипса кубической кривой Безье — даёт гладкую дугу
// без видимых заломов. EGG_TOP/BOTTOM — лёгкая асимметрия "как яйцо" (верх
// чуть уже, низ чуть шире), а не идеально круглая форма.
const MOUTH_ARC_K = 0.5522847498;
// ---------- ВЫСОТЫ ЧЕРТ ЛИЦА ----------
// В долях полувысоты головы (ry). Держатся ВМЕСТЕ и только здесь: пятачок,
// рот и «морда» (светлый выступающий объём вокруг них) — одна связка, и
// подвинуть что-то одно, не подвинув остальное, нельзя.
//
// Именно это уже случилось. Числа стояли вразброс по коду, рот с пятачком
// подняли, а морда осталась на прежнем месте — и её нижняя треть повисла
// пустым светлым пятном под ртом. Хуже того, Y рта был зашит ВТОРОЙ РАЗ в
// живом пересчёте поворота головы, поэтому при повороте рот прыгал обратно
// на старое место.
const SNOUT_Y = 0.36;
const MOUTH_Y = 0.68;
// Границы «морды» выводятся из них же, а не задаются отдельно: сверху она
// начинается заметно выше пятачка (переход к переносице), снизу закрывает
// рот с небольшим запасом на подбородок.
const MUZZLE_TOP = SNOUT_Y - 0.32;
const MUZZLE_BOTTOM = MOUTH_Y + 0.14;
const MOUTH_EGG_TOP = 0.85;
const MOUTH_EGG_BOTTOM = 1.12;

// ---------- ПОЗА ТЕЛА И АНИМАЦИЯ ДВИЖЕНИЯ ----------
// Раскладка цепочки при opts.pose === 'standing' (по умолчанию, главный
// экран): сегменты между головой и животом (fixedSegments) + сам живот
// стоят "вертикальным столбиком" — условная спина/шея, животом упирающаяся
// в пол. От живота дальше (growing-сегменты + хвост) цепочка лежит на полу
// и идёт горизонтально — как раньше, но теперь это только ЧАСТЬ цепочки.
// opts.pose === 'lying' — старая раскладка "одна прямая линия целиком",
// оставлена БЕЗ ИЗМЕНЕНИЙ в логике — нужна Чревоугодию, где персонаж лежит
// плашмя на боку во время кормления.
// Используется только легаси-раскладкой opts.pose==='lying' (см. ниже) —
// действующая напольная цепь ('standing') считает длину звена от РЕАЛЬНЫХ
// радиусов соседних частей, см. WORM_FLOOR_LINK_OVERLAP_RATIO.
const WORM_SEGMENT_SPACING = 18; // базовое расстояние между сегментами (px)

// Сколько "единиц" animTime проходит в РЕАЛЬНУЮ секунду — раньше animTime
// прирастал фиксированным шагом ЗА КАДР (`+= 0.05` в tick()), из-за чего
// скорость всех синусоидальных анимаций (виляние, дыхание, моргание)
// зависела от частоты кадров устройства. Теперь animTime считается от
// РЕАЛЬНОГО прошедшего времени (dt в tick()), не от количества кадров.
const WORM_ANIM_TIME_PER_SEC = 3;
// Та же проблема была у сглаживания движения к цели (было `*0.02` за
// кадр) — заменено на framerate-независимую формулу 1 - base^dtSec.
const WORM_WANDER_MOVE_BASE = 0.3;

// Порог (px): ниже него считаем, что цель движения достигнута — targetX/Y
// приближаются к wormX/Y экспоненциально и математически никогда не
// долетают ТОЧНО до цели.
const WORM_MOVE_EPS = 1.5;

// ---------- ПОВОРОТ НА ХОДУ: ДУГА, А НЕ ИЗЛОМ ----------
// Раньше червь двигался прямо к цели: позиция подтягивалась к targetX/Y
// экспонентой. Пока цель не менялась, это выглядело нормально, но стоило
// задать новую (а тап по полу задаёт её постоянно) — направление менялось
// МГНОВЕННО. Тело при этом продолжало ехать, и в кадре получался излом: червь
// как будто отражался от невидимой стены.
//
// Теперь у него есть КУРС. Он доворачивается к нужному направлению с
// ограниченной угловой скоростью, а тело едет туда, куда смотрит курс, —
// поэтому смена цели даёт дугу.
//
// Радиан в секунду. Ниже примерно 1.3 (скорость подтягивания к цели) червь
// перестаёт успевать доворачивать и начинает наматывать круги вокруг точки
// вместо того, чтобы в неё прийти. 2.4 — заметная дуга с запасом от этого.
const WORM_TURN_RATE = 2.4;
// На крутом довороте червь притормаживает: разворот «на пятке» с полной
// скоростью читается заносом. 0 = стоп на развороте, 1 = скорость не зависит
// от угла.
const WORM_TURN_SLOWDOWN = 0.45;
// Скорость доводки обесцвечивания (формула 1 - base^dt): МЕНЬШЕ = БЫСТРЕЕ.
// Медленная нарочно: истощение — процесс на часы, и заметный переход нужен
// только при смерти и воскрешении.
const WORM_WITHER_BASE = 0.25;

// ---------- КАМЕРА ----------
// Свайп короче этого (в единицах холста) — это тап «иди сюда», а не панорама.
// Палец никогда не стоит на месте идеально, поэтому без порога любой тап
// сдвигал бы камеру на пару единиц и заодно отменял сам себя.
const CAM_DRAG_THRESHOLD = 8;
// Мёртвая зона слежения: доля ширины окна от края, внутри которой камера
// НЕ едет. Без неё камера подрагивает вслед за каждым шагом червя, и
// комната мелко трясётся всё время.
const CAM_DEAD_ZONE = 0.28;
// Скорость доводки камеры (формула 1 - base^dt): МЕНЬШЕ = БЫСТРЕЕ.
const CAM_FOLLOW_BASE = 0.02;
// Сколько камера не лезет обратно после ручного свайпа. Игрок отвёл взгляд
// на угол комнаты — пусть смотрит, а не борется со слежением. По истечении
// срока камера снова подхватывает червя, иначе он потеряется за краем окна.
const CAM_MANUAL_HOLD_MS = 4000;
// Насколько быстро "интенсивность движения" (0..1) сходится к цели —
// подставляется в framerate-независимую формулу 1 - base^dtSec: МЕНЬШЕ
// значение = БЫСТРЕЕ сходимость. Задаёт амплитуду/скорость покачивания
// (виляния) — см. блок "НОВАЯ СТОЯЩАЯ ПОЗА" в tick(). Длина звена
// напольной цепочки с этим полем больше не связана — см.
// WORM_SPEED_REF_PX_PER_SEC ниже.
const WORM_MOVE_INTENSITY_SMOOTH_BASE = 0.0025;
// Пауза "стоит на месте" между прогулками к новой случайной точке.
const WORM_IDLE_PAUSE_MIN = 3500;
const WORM_IDLE_PAUSE_MAX = 8000;

// ---------- РАСТЯЖЕНИЕ ХВОСТОВОЙ ЧАСТИ ОТ РЕАЛЬНОЙ СКОРОСТИ ----------
// Длина звена считается от ФАКТИЧЕСКОЙ мгновенной скорости перемещения
// (px/сек), а не от сглаженного бинарного флага "движется/стоит" — иначе
// хвостовая часть оставалась растянутой ещё около секунды ПОСЛЕ того, как
// персонаж уже визуально остановился.
const WORM_SPEED_REF_PX_PER_SEC = 60; // скорость, при которой достигается полное растяжение
const WORM_SPEED_INTENSITY_SMOOTH_BASE = 0.02; // быстрое сглаживание (~0.2с)

// ---------- НАПОЛЬНАЯ ЦЕПОЧКА КАК ПРОСТАЯ КИНЕМАТИЧЕСКАЯ ЦЕПЬ ----------
// growing-сегменты и хвост НЕ позиционируются каждый независимой формулой
// (это давало видимые разрывы между соседями). Вместо этого каждое звено
// вычисляется строго ОТ ПРЕДЫДУЩЕГО: позиция = позиция_предыдущего + длина
// звена в направлении текущего угла звена. Раз каждое звено жёстко
// привязано к предыдущему по построению — разъединиться им ГЕОМЕТРИЧЕСКИ
// невозможно, при любой амплитуде покачивания.
const WORM_MOVE_SPACING_EXTRA = 4; // доп. px к длине звена при ходьбе

// ---------- БАЗОВАЯ ДЛИНА ЗВЕНА НАПОЛЬНОЙ ЦЕПИ: ОТ РЕАЛЬНЫХ РАДИУСОВ ----------
// Одно плоское число не может подойти сразу всем парам сужающейся цепи,
// поэтому длина звена МЕЖДУ КОНКРЕТНОЙ ПАРОЙ считается от их РЕАЛЬНЫХ
// радиусов: сумма радиусов минус доля от МЕНЬШЕГО из двух — одинаковое
// ОТНОСИТЕЛЬНОЕ (не абсолютное) перекрытие для любой пары.
const WORM_FLOOR_LINK_OVERLAP_RATIO = 0.6;
function floorLinkBaseLength(radiusA, radiusB) {
    return radiusA + radiusB - WORM_FLOOR_LINK_OVERLAP_RATIO * Math.min(radiusA, radiusB);
}
// Покачивание угла КАЖДОГО звена напольной цепочки (включая точку
// крепления хвоста) — держит цепочку согласованной единой волной.
const WORM_CHAIN_WIGGLE_IDLE_DEG = 1.2;
const WORM_CHAIN_WIGGLE_MOVE_DEG = 3.5;
const WORM_CHAIN_WIGGLE_IDLE_SPEED = 0.5;
const WORM_CHAIN_WIGGLE_MOVE_SPEED = 1.1;
// Разница фазы (рад) между соседними звеньями — маленькая, чтобы сосед
// двигался почти вслед за соседом (мягкая бегущая волна), не вразнобой.
const WORM_CHAIN_PHASE_STEP = 0.3;
// Хвост дополнительно "вихляет" СВЕРХ базового угла звена — косметический
// поворот ЕГО СОБСТВЕННОЙ формы (bendGroup) вокруг уже вычисленной точки
// крепления, на само крепление не влияет.
const WORM_TAIL_EXTRA_WAG_IDLE_DEG = 2;
const WORM_TAIL_EXTRA_WAG_MOVE_DEG = 5;

// ---------- ФОРМА ХВОСТА ----------
// Основание хвоста = доля от реального радиуса ПОСЛЕДНЕГО growing-сегмента
// (см. buildTailNode) — продолжает естественное сужение цепочки. Кончик —
// доля УЖЕ от основания хвоста, закруглённый овал, а не точка.
const WORM_TAIL_BASE_RATIO = 0.7;
const WORM_TAIL_TIP_RATIO = 0.35;

// ---------- ВЕРТИКАЛЬНАЯ ЧАСТЬ ЦЕПОЧКИ (голова → сегмент-1 → сегмент-2 → живот) ----------
// У вертикальной части СВОЁ расстояние, независимое от напольной цепи
// (плоская константа здесь корректна: у всех трёх сегментов один радиус).
const WORM_VERTICAL_SPACING = 26;
// Боковой снос позвоночника в стоящей позе. Все сегменты колонны стояли
// строго по x=0, а напольная часть уходила строго влево — фигура складывалась
// в букву «Г». Прямой угол читается мебелью, у животного должна быть одна
// сквозная дуга (art-direction.md §4.2). Живот уводится влево относительно
// головы, поэтому дуга с пола продолжается вверх, а голова оказывается
// вынесенной вправо — тело противовесит хвосту, и поза становится живой.
// ============================================================================
//                       КОМНАТА: ПОЛ В ПЕРСПЕКТИВЕ (2.5D)
// ============================================================================
// Главный экран был плоским: персонаж ползал по однородному тёмному фону, и
// его размер не менялся, куда бы он ни шёл. Комната даёт сцене третье
// измерение, не превращая проект в 3D.
//
// Вся геометрия выводится из ЧЕТЫРЁХ чисел, и это не случайность: пол,
// границы блуждания и масштаб персонажа обязаны считаться из одного
// источника, иначе персонаж рано или поздно окажется по колено в полу или
// вырастет не в том месте.
//
// Модель — честное перспективное деление, а не линейная интерполяция:
//   scale(d) = 1 / (1 + d*k),  где k подобрано так, что scale(1) = minScale.
// Отсюда сразу всё остальное: экранная высота точки пола, ширина пола на
// этой глубине и размер персонажа — это одно и то же число scale(d).
// Линейная интерполяция дала бы «складной» пол: у камеры шаг вглубь съедал
// бы столько же пикселей, сколько у дальней стены, и глубина бы не читалась.
const ROOM = {
    // ---------- КОМНАТА — КОРОБКА ВНУТРИ КАДРА ----------
    // Раньше пол уходил за нижнюю кромку экрана и за боковые края: комната
    // была не помещением, а «полом до горизонта». Персонаж от этого регулярно
    // оказывался наполовину за экраном.
    //
    // Теперь у комнаты видны все четыре края: передний край пола, две боковые
    // стены и задняя. Червю физически некуда выйти из кадра — он ходит по
    // ограниченному полу, и границы выгула считаются из той же геометрии, что
    // и сам пол.
    // ---------- ВЗГЛЯД СВЕРХУ, А НЕ В УПОР ----------
    // Раньше камера смотрела почти горизонтально: пол занимал по вертикали
    // 355 единиц, стены — 269, и комната читалась колодцем. Экран при этом
    // не заполнялся: сверху и снизу оставались широкие пустые поля, а сама
    // коробка не доставала до боковых краёв.
    //
    // Теперь камера поднята и наклонена вниз. Пол занимает по вертикали 506
    // единиц против 158 у задней стены — то есть видно в основном ПОЛ, как и
    // должно быть при взгляде сверху. Точка схода при таких числах уезжает
    // выше экрана, и это признак того, что наклон реальный, а не
    // нарисованный.
    //
    // Сверху остаётся полоса пустоты, и убрать её нельзя: чтобы стены дотянули
    // до верхней кромки, они должны стать вдвое выше пола, а это уже не
    // комната, а колодец. Полоса не мешает — под ней стоит HUD.
    // Пол доходит до самого низа кадра. Передний край при этом совпадает с
    // кромкой экрана и перестаёт быть видимой линией — раньше он был четвёртой
    // видимой гранью коробки, но оставлял под собой полосу пустоты. Выгул
    // червя считается из той же геометрии, поэтому уйти за кадр он всё равно
    // не может: граница есть, просто она не нарисована.
    floorFrontRatio: 1.0,
    // Глубина пола выбрана не «побольше», а по ФОРМЕ ПЯТНА пола на экране.
    // При 0.27 пол выходил 390×574 — вытянутый прямоугольник, и комната
    // читалась коридором, ровно как предупреждает абзац выше. Ширина упёрта
    // в экран и расти не может, значит ограничивать надо глубину: 390×506
    // (примерно 1:1.3) уже помещение, а не проход. Недостающий верх добирают
    // стены — их высота дешевле, она не превращает комнату в тоннель.
    floorBackRatio: 0.40,   // стык пола с задней стеной
    // ---------- КОМНАТА ШИРЕ ЭКРАНА ----------
    // Ширина комнаты в долях ширины ЭКРАНА. Экран — окно в неё, вбок оно
    // ездит свайпом.
    //
    // Зачем: ширина упиралась в 390 единиц экрана, а размах тела червя — 258.
    // Из этого не выкрутиться отступами: он физически занимал две трети
    // комнаты, и «не касаться стен» означало «стоять в середине». Плюс пол
    // 390×506 читался коридором. При 1.9 пол становится 741×506 — уже
    // помещение, у червя втрое больше места вбок, и остаётся куда ставить
    // мебель.
    widthRatio: 1.9,
    // Ровно половина ширины КОМНАТЫ: передние углы пола ложатся на её края,
    // и зазора между стеной и краем мира не остаётся.
    frontHalfRatio: 0.5,
    // Высота стен считается от ширины ЭКРАНА, а не комнаты. Иначе расширение
    // мира задирало бы стены вместе с ним, и вся вертикальная композиция,
    // подобранная выше, поехала бы.
    wallHeightRatio: 0.78,
    // Сила перспективы: scale(d) = 1 / (1 + d*depthK).
    //
    // Была 0.42 — при закрытой коробке это превращало комнату в длинный
    // тоннель: дальняя стена втрое уже передней. Комната у тамагочи — не
    // коридор, она должна читаться помещением почти сразу, поэтому схождение
    // умеренное: дальняя грань уже передней примерно вдвое.
    //
    // Убавлять его вслед за наклоном камеры (ближе к изометрии — слабее
    // схождение) пробовали: при 0.12 стены становятся почти параллельными, и
    // на узком вертикальном экране пол превращается в плоскую ленту без
    // глубины. Наклон камеры задаётся долями выше, а это число отвечает за то,
    // читается ли пол уходящим вдаль.
    depthK: 0.20,
    farDepth: 4.6,         // глубина дальней стены
    // Червь ходит НЕ по всей глубине: у дальней стены он мельче, а стена там
    // ниже него, и голова начинала бы торчать над комнатой.
    // ---------- ГРАНИЦЫ ВЫГУЛА ----------
    // Это не «где червю разрешено стоять», а лишь ВНЕШНИЕ рамки поиска.
    // Настоящая граница считается от габаритов тела: см. refreshWanderRange
    // и clampFloorPoint. Причина — константа не может знать, какого размера
    // червь: он растёт с возрастом, и подобранный вручную отступ перестал бы
    // работать на первом же новом сегменте.
    wanderNear: 0.25,      // ближняя граница поиска
    wanderFar: 3.4,        // дальняя граница поиска
    // Отступ от стен и кромок кадра в условных единицах холста. Меряется от
    // ГАБАРИТА ТЕЛА, а не от точки касания: тело лежит вдоль пола и занимает
    // место, поэтому «касание внутри пола» ещё не значит, что хвост не заехал
    // в стену.
    wanderMargin: 12,
    // Сколько места вбок должно остаться на глубине, чтобы она вообще
    // считалась пригодной. Без этого условия дальняя часть комнаты
    // формально проходима, но полоса там уже тела: червь оказывается
    // намертво прижат к середине и перестаёт двигаться вбок вовсе. Дешевле
    // объявить такую глубину непригодной и не пускать его туда.
    wanderMinSpan: 18,
    // ---------- ПРИГЛУШЕНИЕ МАСШТАБА ПЕРСОНАЖА ----------
    // Пол считается по ЧЕСТНОЙ перспективе, а размер персонажа — нет, и это
    // осознанное расхождение.
    //
    // Если дать персонажу полный перспективный масштаб, у дальней стены он
    // ужмётся вдвое: это читается не «отошёл вглубь», а «провалился в яму»,
    // и мелкую мимику становится не разглядеть. Если же приглушить саму
    // перспективу пола, комната станет плоской.
    //
    // Поэтому глубина у них общая, а сила отклика разная: пол — 1.0,
    // персонаж — вот столько. Так комната остаётся глубокой, а размер
    // меняется заметно, но не пугающе.
    charScaleStrength: 0.45
};

// w — ширина ЭКРАНА (окна), h — его высота. Сама комната шире: её ширина
// возвращается в g.roomW, и все координаты пола/стен считаются в ней.
function roomGeometry(w, h) {
    const roomW = w * ROOM.widthRatio;
    const frontY = h * ROOM.floorFrontRatio;
    const backY = h * ROOM.floorBackRatio;
    const frontHalf = roomW * ROOM.frontHalfRatio;
    const farScale = roomScaleAt(ROOM.farDepth);
    // Точка схода не задаётся числом, а ВЫВОДИТСЯ из того, где должны
    // оказаться передний и дальний края пола. Иначе перспектива и границы
    // комнаты живут отдельными жизнями: подвинул край — пол перестал в него
    // упираться.
    const horizonY = (backY - farScale * frontY) / (1 - farScale);
    return {
        // w/h — ОКНО (экран), roomW — сама комната. Центр по комнате, а не по
        // экрану: вся геометрия пола и стен живёт в координатах комнаты.
        w, h, roomW, cx: roomW / 2,
        // Насколько далеко камера может уехать вбок: от левого края комнаты
        // до правого минус окно.
        panMax: Math.max(0, roomW - w),
        horizonY, frontY, frontHalf,
        backY, backHalf: frontHalf * farScale,
        // Высота стены у переднего края; у дальней она во столько же раз
        // меньше, во сколько уже пол. Считается от ширины ЭКРАНА — см.
        // wallHeightRatio.
        wallH: w * ROOM.wallHeightRatio,
        farScale
    };
}
// Геометрический масштаб на глубине d (0 = у самой камеры).
function roomScaleAt(d) {
    return 1 / (1 + Math.max(0, d) * ROOM.depthK);
}
// Масштаб ПЕРСОНАЖА на той же глубине — приглушённый, см. charScaleStrength.
function roomCharScaleAt(d) {
    return 1 + (roomScaleAt(d) - 1) * ROOM.charScaleStrength;
}
function roomYAt(g, d) { return g.horizonY + (g.frontY - g.horizonY) * roomScaleAt(d); }
function roomHalfAt(g, d) { return g.frontHalf * roomScaleAt(d); }
// Обратная задача: по экранной высоте — глубина. Нужна, чтобы масштабировать
// персонажа и след слизи, зная только их положение на полу.
function roomDepthAt(g, y) {
    const s = (y - g.horizonY) / Math.max(1e-6, g.frontY - g.horizonY);
    return Math.max(0, (1 / Math.max(1e-4, s) - 1) / ROOM.depthK);
}

// Отрисовка комнаты. Намеренно скупая: по формуле стиля интерьер — это
// «смокинг», он не имеет права спорить с персонажем за внимание
// (docs/art-direction.md §1.2, §5). Поэтому только плоскости, одна линия
// стыка и несколько очень слабых линий схода — самый дешёвый признак
// глубины из существующих.
// ---------- РИСУНОК ПОЛА ----------
// Паркет в перспективе. Доски лежат ВДОЛЬ взгляда, поэтому их края — это те
// же линии схода, что раньше изображали глубину: рисунок пола и признак
// глубины здесь одно и то же, и платить за них дважды не нужно.
//
// Поперёк идут торцы досок. Их шаг обязан сжиматься с глубиной по той же
// формуле, что и всё остальное в комнате (roomYAt), иначе пол выглядит
// наклеенной текстурой, а не уходящей поверхностью. Шаг по глубине берётся
// равномерным, а перспектива сама сгущает дальние ряды.
//
// Торцы вразбежку: у соседних рядов они смещены на полдоски. Ровная сетка
// стык-в-стык читается кафелем, а не паркетом, — вразбежку и кладут.
function buildFloorPattern(layer, g, loc) {
    if (loc.pattern !== 'planks') return;

    const PLANKS = 9;          // досок по ширине комнаты
    const ROW_DEPTH = 0.62;    // шаг торцов по глубине (в единицах глубины комнаты)

    // Ряды торцов: доли глубины, на которых доски стыкуются. Считаем один раз
    // и пользуемся в обоих проходах.
    const rows = [{ d: 0, y: g.frontY, half: g.frontHalf }];
    for (let d = ROW_DEPTH; d < ROOM.farDepth; d += ROW_DEPTH) {
        const y = roomYAt(g, d);
        if (y <= g.backY + 0.5) break;
        rows.push({ d, y, half: roomHalfAt(g, d) });
    }
    rows.push({ d: ROOM.farDepth, y: g.backY, half: g.backHalf });

    const xAt = (u, half) => g.cx + u * half;

    // ---------- ПРОХОД 1: заливки ----------
    // Тон меняется ПО ДОСКЕ и остаётся постоянным вдоль всей её длины.
    //
    // Первая версия меняла тон по клеткам «доска × ряд» — и пол получился
    // шахматкой, то есть крупной плиткой, а не паркетом. Разница
    // принципиальная: доска — цельный кусок дерева, у неё один тон от начала
    // до конца, и именно это отличает дощатый пол от кафеля. Разбежку даёт не
    // цвет, а короткие торцевые швы ниже.
    //
    // Тон берётся от номера доски синусом: нужен разброс без «через одну»
    // (полосатый пол читается зеброй) и без случайности (комната
    // перестраивается при каждом изменении размера окна, и пол не должен
    // перекрашиваться на глазах).
    const front = rows[0], back = rows[rows.length - 1];
    for (let i = 0; i < PLANKS; i++) {
        const shade = Math.sin(i * 2.399) * 0.5 + 0.5;    // 0..1, вразнобой
        const u0 = (i / PLANKS) * 2 - 1;
        const u1 = ((i + 1) / PLANKS) * 2 - 1;
        layer.appendChild(svgEl('path', {
            d: 'M ' + xAt(u0, front.half).toFixed(1) + ',' + front.y.toFixed(1) +
               ' L ' + xAt(u1, front.half).toFixed(1) + ',' + front.y.toFixed(1) +
               ' L ' + xAt(u1, back.half).toFixed(1) + ',' + back.y.toFixed(1) +
               ' L ' + xAt(u0, back.half).toFixed(1) + ',' + back.y.toFixed(1) + ' Z',
            fill: shade > 0.5 ? loc.floor.light : loc.floor.seam,
            opacity: (Math.abs(shade - 0.5) * 0.34).toFixed(3)
        }));
    }

    const line = (x1, y1, x2, y2, opacity) => {
        layer.appendChild(svgEl('line', {
            x1: x1.toFixed(1), y1: y1.toFixed(1), x2: x2.toFixed(1), y2: y2.toFixed(1),
            stroke: loc.floor.seam, 'stroke-width': SW.hairline, opacity
        }));
    };

    // ---------- ПРОХОД 2: швы ----------
    // Продольные — от переднего края к дальнему. Они же и есть линии схода:
    // рисунок пола и признак глубины здесь одно и то же.
    for (let i = 1; i < PLANKS; i++) {
        const u = (i / PLANKS) * 2 - 1;
        line(xAt(u, g.frontHalf), g.frontY, xAt(u, g.backHalf), g.backY, 0.5);
    }

    // Торцы — стыки двух досок в длину. Рисуются коротким отрезком в пределах
    // ОДНОЙ доски: сплошная линия через всю комнату превратила бы пол в кафель.
    //
    // И они редкие. Доска длинная, на видимом куске пола её стык попадается
    // не в каждом ряду; если ставить торец через одну, стыки выстраиваются в
    // регулярную сетку — снова кафель. Признак берётся хешем от номера доски
    // и ряда: разброс есть, но он один и тот же при каждой перестройке.
    for (let r = 1; r < rows.length - 1; r++) {
        const row = rows[r];
        for (let i = 0; i < PLANKS; i++) {
            if ((Math.sin(i * 12.9898 + r * 78.233) * 43758.5453 % 1 + 1) % 1 > 0.34) continue;
            const u0 = (i / PLANKS) * 2 - 1;
            const u1 = ((i + 1) / PLANKS) * 2 - 1;
            line(xAt(u0, row.half), row.y, xAt(u1, row.half), row.y, 0.42);
        }
    }
}

function buildRoom(layer, g, locationKey) {
    while (layer.firstChild) layer.removeChild(layer.firstChild);

    // Облик берётся из таблицы локаций (src/core/rooms.js), а не задаётся
    // здесь: комната — косметика, её будут менять на подвал, церковь, пещеру.
    // Отрисовка обязана уметь нарисовать любую, не зная, какая именно.
    const loc = (typeof RoomLocations !== 'undefined')
        ? RoomLocations.get(locationKey)
        : null;
    if (!loc) return;   // rooms.js не подключён — рисовать нечего

    const backY = g.backY, backHalf = g.backHalf;
    const wallH = g.wallH, backWallH = wallH * g.farScale;
    const L = g.cx - g.frontHalf, R = g.cx + g.frontHalf;   // передние углы пола
    const bl = g.cx - backHalf, br = g.cx + backHalf;       // дальние углы пола
    const topFront = g.frontY - wallH;                      // верх стены у камеры
    const topBack = backY - backWallH;                      // верх стены у дальней грани

    const floorFill = loc.floor.base;
    const wallBack = loc.walls.back;
    const wallLit = loc.walls.lit;
    const wallShade = loc.walls.shade;

    const poly = (pts, fill, opacity) => {
        const d = 'M ' + pts.map(p => p[0].toFixed(1) + ',' + p[1].toFixed(1)).join(' L ') + ' Z';
        const el = svgEl('path', { d, fill });
        if (opacity != null) el.setAttribute('opacity', opacity);
        layer.appendChild(el);
        return el;
    };

    // Пустота вокруг коробки. Тот же тон, что у полей за пределами холста, —
    // тогда поля на нетипичном экране не читаются обрезкой, а выглядят
    // продолжением темноты вокруг комнаты.
    layer.appendChild(svgEl('rect', { x: 0, y: 0, width: g.roomW, height: g.h, fill: loc.surround }));

    // Боковые стены: от передних углов пола к дальним, вверх на высоту стены.
    poly([[L, g.frontY], [bl, backY], [bl, topBack], [L, topFront]], wallShade);
    poly([[R, g.frontY], [br, backY], [br, topBack], [R, topFront]], wallLit);

    // Задняя стена.
    poly([[bl, backY], [br, backY], [br, topBack], [bl, topBack]], wallBack);

    // Пол — трапеция между передними и дальними углами.
    poly([[L, g.frontY], [R, g.frontY], [br, backY], [bl, backY]], floorFill);

    // Рисунок пола. Единственное место, где локация требует не цвета, а кода:
    // доски, камень и земля рисуются по-разному.
    buildFloorPattern(layer, g, loc);

    // Плинтус по низу задней стены — самая дешёвая деталь, превращающая две
    // плоскости в комнату: без неё стык читается обрывом.
    const plinthH = Math.max(2, backWallH * 0.14);
    poly([[bl, backY], [br, backY], [br, backY - plinthH], [bl, backY - plinthH]],
         loc.plinth);

    // Плинтус по БОКОВЫМ стенам. Он уходит в перспективу вместе с ними,
    // поэтому у камеры выше, чем у дальней стены — во столько же раз, во
    // сколько сама стена. Без него плинтус задней стены обрывался в воздухе
    // на стыке углов, и было видно, что комната сделана из трёх отдельных
    // плоскостей, а не из стен.
    const plinthFront = plinthH / g.farScale;
    poly([[L, g.frontY], [bl, backY], [bl, backY - plinthH], [L, g.frontY - plinthFront]],
         mixColor(loc.plinth, P_.ink, 0.28));                  // левая — в тени
    poly([[R, g.frontY], [br, backY], [br, backY - plinthH], [R, g.frontY - plinthFront]],
         loc.plinth);

    // Рёбра коробки. Самые тёмные линии сцены после контура персонажа:
    // именно они делают комнату комнатой, а не набором пятен.
    // Прозрачности рёбер заданы относительно локации: в СВЕТЛОЙ комнате та же
    // контурная линия бьёт в глаза куда сильнее, чем в тёмной, и комната
    // начинает спорить с персонажем за внимание. Множитель локации убавляет
    // их все разом, не трогая соотношение между ними.
    const edgeK = loc.edges.opacity / 0.85;
    const edge = (x1, y1, x2, y2, opacity, width) => {
        layer.appendChild(svgEl('line', {
            x1: x1.toFixed(1), y1: y1.toFixed(1), x2: x2.toFixed(1), y2: y2.toFixed(1),
            stroke: loc.edges.ink, 'stroke-width': width || SW.structure,
            opacity: (opacity * edgeK).toFixed(3)
        }));
    };
    edge(bl, backY, br, backY, 0.85);                    // стык задней стены с полом
    edge(L, g.frontY, bl, backY, 0.6);                   // стык левой стены с полом
    edge(R, g.frontY, br, backY, 0.6);                   // стык правой стены с полом
    edge(bl, backY, bl, topBack, 0.5, SW.detail);        // дальние вертикальные рёбра
    edge(br, backY, br, topBack, 0.5, SW.detail);
    edge(L, topFront, bl, topBack, 0.45, SW.detail);     // верхние кромки стен
    edge(R, topFront, br, topBack, 0.45, SW.detail);
    edge(bl, topBack, br, topBack, 0.45, SW.detail);
    // Передний край пола — нижняя кромка коробки.
    edge(L, g.frontY, R, g.frontY, 0.7);

    // Мягкая тень у дальнего стыка: пол уходит в темноту вдали, а не
    // обрывается ступенькой.
    const gradId = 'worm-room-depth-grad';
    if (!layer.querySelector('#' + gradId)) {
        const defs = svgEl('defs');
        const grad = svgEl('linearGradient', { id: gradId, x1: '0', y1: '0', x2: '0', y2: '1' });
        // Тон притемнения задаёт локация. Он НЕ контурный ink: сливовый ink
        // давал полу отчётливый лиловый налёт у дальней стены. У деревянного
        // пола это тёмное дерево — угол комнаты уходит в тень, а не в грязь.
        grad.appendChild(svgEl('stop', {
            offset: '0%', 'stop-color': loc.depth.color, 'stop-opacity': String(loc.depth.opacity)
        }));
        grad.appendChild(svgEl('stop', {
            offset: '100%', 'stop-color': loc.depth.color, 'stop-opacity': '0'
        }));
        defs.appendChild(grad);
        layer.appendChild(defs);
    }
    poly([[bl, backY], [br, backY],
          [g.cx + (g.frontHalf + backHalf) * 0.5, (backY + g.frontY) * 0.5],
          [g.cx - (g.frontHalf + backHalf) * 0.5, (backY + g.frontY) * 0.5]],
         `url(#${gradId})`);
}

// ---------- ОРИЕНТАЦИЯ ТЕЛА ПО НАПРАВЛЕНИЮ ДВИЖЕНИЯ ----------
// Напольная цепь строилась под ЖЁСТКИМ углом 180°: тело всегда уходило влево
// от головы, куда бы червь ни полз. Существо не может ползти в одну сторону,
// держа хвост перед собой.
//
// Теперь есть tailAngle — экранный угол, вдоль которого лежит хвостовая часть.
// Он доворачивается к направлению, ПРОТИВОПОЛОЖНОМУ движению, и делает это
// плавно: мгновенный переброс хвоста читался бы телепортом, а не поворотом.
const WORM_TAIL_TURN_BASE = 0.015;   // 1 - base^dt: меньше = быстрее доворот
// Пол показан в перспективе, а не сверху: шаг вглубь комнаты даёт на экране
// меньше пикселей, чем такой же шаг вбок. Хвост лежит на полу, поэтому его
// вертикальная составляющая сжимается тем же множителем — иначе при движении
// вглубь тело встанет на дыбы вместо того, чтобы уйти в перспективу.
const WORM_FLOOR_PERSPECTIVE = 0.45;
// Насколько сильно голова доворачивается вслед за направлением ползания.
// 0.5 совпадает с именованными позами left/right — то есть автоповорот
// использует те же настроенные крайние значения, а не свои.
const WORM_HEAD_YAW_FOLLOW = 0.5;
// Скорость подъезда головы к целевому повороту (формула 1 - base^dt):
// МЕНЬШЕ значение = БЫСТРЕЕ. 0.0009 даёт поворот примерно за четверть
// секунды — читается щелчком, но остаётся плавным.
const WORM_HEAD_YAW_BASE = 0.0009;
const WORM_HEAD_YAW_EPS = 0.004;
const WORM_SPINE_LEAN = 16;
// Показатель степени: >1 держит шею почти прямой, а изгиб собирает внизу, у
// живота. Линейный снос дал бы равномерный завал всей колонны — это чтение
// «падает», а не «изогнулся».
const WORM_SPINE_LEAN_POW = 1.6;
// Снос сегмента колонны по его положению t (0 = шея у головы, 1 = живот).
// Возвращает МОДУЛЬ сноса; сторону задаёт вызывающий по углу хвоста —
// колонна обязана заваливаться в ту же сторону, куда лежит тело, иначе при
// развороте дуга сломается пополам.
function spineLeanMag(t) {
    return WORM_SPINE_LEAN * Math.pow(Math.max(0, Math.min(1, t)), WORM_SPINE_LEAN_POW);
}

// Насколько мост единого силуэта уже соседних кругов — глубина перетяжки
// между секциями тела. 0 = ровная труба, ~0.2 = выраженные "сосисочные"
// вздутия. Подобрано так, чтобы секции читались, но тело не разваливалось
// обратно на отдельные шары.
const WORM_HULL_WAIST_RATIO = 0.2;

// ---------- ТАЙМИНГ-БАГ "ЭФФЕКТ ВОЛЧКА" ----------
// НИКОГДА не умножать общее накопленное время на переменную скорость:
// `Math.sin(animTime * переменнаяСкорость)` даёт скачок фазы,
// пропорциональный ВСЕЙ прошедшей истории. Вместо этого — отдельный
// аккумулятор ФАЗЫ, который каждый кадр прирастает на
// dtSec * ANIM_TIME_PER_SEC * ТЕКУЩАЯ_скорость (см. state.chainWigglePhase /
// state.tailWagPhase / state.organPhase в tick()).

// "Дыхание" — лёгкая пульсация масштаба вертикальной части тела, работает
// ВСЕГДА, независимо от ходьбы. Голова не участвует. ОДНА общая фаза с
// разной амплитудой по сегментам (WORM_BREATH_RATIO). Волна ОДНОПОЛЯРНАЯ —
// никогда не опускается ниже стандартного радиуса, только поднимается.
const WORM_BREATH_AMP = 0.035;
const WORM_BREATH_SPEED = 0.6;
const WORM_BREATH_RATIO = { 'belly': 1, 'segment-2': 0.7, 'segment-1': 0.3 };

// Слизистый след на полу во время ходьбы (растёт из-под предхвостового
// growing-сегмента) — см. startSlimeTrail/extendSlimeTrail/updateSlimeTrail
// внутри WormRenderer.mount().
const WORM_SLIME_FADE_MS = 15000;
const WORM_SLIME_WIDTH = 15;
const WORM_SLIME_MIN_STEP = 4;
// След слизи на полу. Раньше это был один непрозрачный оливковый штрих
// шириной 15px с круглыми концами — на экране он читался палкой, а не
// слизью. Теперь след состоит из двух штрихов: широкой тёмной мокрой
// кляксы и тонкой яркой сердцевины (свежая слизь блестит).
//
// Почему тёмная ступень кислоты, а не яркая: след — БОЛЬШАЯ площадь, а
// акцент по правилу дозировки большим быть не может (art-direction.md §1.2).
// Яркая кислота остаётся только на узкой сердцевине.
const WORM_SLIME_SMEAR_ALPHA = 0.5;
// Яркая кислота в следе живёт ОТДЕЛЬНЫМИ КАПЛЯМИ, а не непрерывной линией.
// Проверено: тонкая яркая сердцевина вдоль всего следа читается зелёным
// кабелем — та же ошибка "акцент большой площадью", что и широкая заливка,
// только вытянутая. Капли дают кислотность, оставаясь точками.
const WORM_SLIME_DROP_ALPHA = 0.72;
const WORM_SLIME_DROP_EVERY = 4;   // капля на каждую N-ю точку следа
const WORM_SLIME_DROP_R = 2.1;
// На сколько должен измениться масштаб глубины, чтобы начать новый отрезок следа.
const WORM_SLIME_DEPTH_STEP = 0.1;

function lerp(a, b, t) { return a + (b - a) * t; }
function clamp01(v) { return v < 0 ? 0 : (v > 1 ? 1 : v); }

let wormInstanceCounter = 0;

function svgEl(tag, attrs) {
    const el = document.createElementNS(SVG_NS, tag);
    if (attrs) {
        Object.keys(attrs).forEach(key => el.setAttribute(key, attrs[key]));
    }
    return el;
}

// ---------- ЦВЕТОВЫЕ УТИЛИТЫ (для объёмных градиентов) ----------
// Модель хранит цвета то как hex ('#ffb6c1'), то как hsl('hsl(340, 56%, 48%)') —
// чтобы одинаково подмешивать в любой из форматов другой цвет, используем сам
// браузер: временный элемент + getComputedStyle всегда отдаёт цвет в виде
// rgb(...), из которого легко интерполировать в сторону любого целевого цвета.
let colorParseEl = null;
const colorParseCache = Object.create(null);
function parseCssColor(css) {
    // Кэш: parseCssColor вызывается десятки раз при каждой пересборке
    // (у каждого слоя каждого сегмента свои подмешанные оттенки), а сам
    // вызов дорогой — он дёргает getComputedStyle, то есть синхронный
    // пересчёт стилей документа. Цвет → rgb — чистая функция, кэшируется
    // без каких-либо оговорок.
    if (colorParseCache[css]) return colorParseCache[css];
    if (!colorParseEl) {
        colorParseEl = document.createElement('span');
        colorParseEl.style.display = 'none';
        (document.body || document.documentElement).appendChild(colorParseEl);
    }
    colorParseEl.style.color = '';
    colorParseEl.style.color = css;
    const computed = getComputedStyle(colorParseEl).color || '';
    const m = computed.match(/rgba?\(([^)]+)\)/);
    let out;
    if (!m) {
        out = { r: 200, g: 100, b: 120 };
    } else {
        const parts = m[1].split(',').map(s => parseFloat(s));
        out = { r: parts[0] || 0, g: parts[1] || 0, b: parts[2] || 0 };
    }
    colorParseCache[css] = out;
    return out;
}

// Линейная интерполяция цвета css → target на долю t (0..1).
function mixColor(css, targetCss, t) {
    const a = parseCssColor(css);
    const b = parseCssColor(targetCss);
    const tt = clamp01(t);
    const nr = Math.round(a.r + (b.r - a.r) * tt);
    const ng = Math.round(a.g + (b.g - a.g) * tt);
    const nb = Math.round(a.b + (b.b - a.b) * tt);
    return `rgb(${nr},${ng},${nb})`;
}

function withAlpha(css, alpha) {
    const { r, g, b } = parseCssColor(css);
    return `rgba(${Math.round(r)},${Math.round(g)},${Math.round(b)},${alpha})`;
}

// Грязно-оливковый (не чисто чёрный) для теней и болезненно-желтоватый (не
// чисто белый) для бликов — объёмный градиент читается как немытая кожа, а
// не глянцевая игрушка, без единого лишнего пятна/полоски поверх заливки.
const GRIME_SHADOW = INK;
const GRIME_HIGHLIGHT = BILE[200];

// Радиальный градиент "блик сверху-слева → тень снизу-справа" — придаёт
// плоским SVG-эллипсам ощущение объёма без утяжеления разметки. Каждой части
// тела достаётся свой градиент с уникальным id (instanceId + имя части), т.к.
// на экране одновременно может быть смонтировано несколько персонажей.
function ensureVolumeGradient(defs, id, colorCss, opts) {
    opts = opts || {};
    const highlightAmt = opts.highlight != null ? opts.highlight : 0.3;
    const shadowAmt = opts.shadow != null ? opts.shadow : -0.3;
    const highlightTarget = opts.highlightTint || SPEC;
    const shadowTarget = opts.shadowTint || INK;
    const highlight = highlightAmt === 0 ? colorCss : mixColor(colorCss, highlightTarget, Math.abs(highlightAmt));
    const shadow = shadowAmt === 0 ? colorCss : mixColor(colorCss, shadowTarget, Math.abs(shadowAmt));
    // ЕДИНЫЙ ИСТОЧНИК СВЕТА. Раньше каждый вызов передавал СВОИ cx/cy, из-за
    // чего каждая часть тела была освещена собственной лампочкой и выглядела
    // самостоятельным глянцевым шариком — отсюда вид "гирлянда из пластика".
    // Теперь направление света берётся из LIGHT и одинаково для всех частей,
    // поэтому блики выстраиваются в одну линию и фигура читается единым
    // объёмом. Индивидуальные cx/cy намеренно ИГНОРИРУЮТСЯ — см.
    // docs/art-direction.md §3. Управлять размытием (r) по-прежнему можно.
    const grad = svgEl('radialGradient', {
        id,
        cx: (50 + LIGHT.dirX * 50).toFixed(1) + '%',
        cy: (50 + LIGHT.dirY * 50).toFixed(1) + '%',
        r: opts.r || '75%'
    });
    grad.appendChild(svgEl('stop', { offset: '0%', 'stop-color': highlight }));
    grad.appendChild(svgEl('stop', { offset: '55%', 'stop-color': colorCss }));
    grad.appendChild(svgEl('stop', { offset: '100%', 'stop-color': shadow }));
    defs.appendChild(grad);
    return `url(#${id})`;
}

// ---------- ДЕТЕРМИНИРОВАННЫЙ ГЕНЕРАТОР ШУМА ----------
// Обычный Math.random() дал бы новый узор при каждой перерисовке одного и
// того же смонтированного персонажа (rebuild() дёргается на любой
// setOverride/update) — узор бы "мигал" и переставлялся.
function hashStringSeed(str) {
    let h = 2166136261 >>> 0;
    for (let i = 0; i < str.length; i++) {
        h ^= str.charCodeAt(i);
        h = Math.imul(h, 16777619);
    }
    return h >>> 0;
}
function mulberry32(seed) {
    let s = seed >>> 0;
    return function () {
        s = (s + 0x6D2B79F5) >>> 0;
        let t = s;
        t = Math.imul(t ^ (t >>> 15), t | 1);
        t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}

// ============================================================================
//                        АНАТОМИЧЕСКИЕ СЛОИ ТЕЛА
// ============================================================================
// Тело — не один эллипс с градиентом, а слоистый материал. На КАЖДУЮ часть
// (сегмент/живот/хвост/голова) строится одна и та же стопка слоёв, в строго
// фиксированном порядке снизу вверх:
//
//   [0] skin base   — сама заливка части (уже существовавший эллипс/путь);
//   [1] skin tone   — неоднородность тона: крупные мягкие пятна светлее/темнее;
//   [2] dorsoventral— спина темнее, брюхо светлее (как у дождевого червя);
//   [3] muscle      — продольные тяжи под кожей, дают рельеф, а не гладкий шар;
//   [4] organs      — РАЗНЫЕ по форме структуры (кишка/мешочек/узелки/сосуд),
//                     у каждой свой цвет, свой ритм пульсации, своя видимость;
//   [5] coat        — покрытие кожи: кольцевые бороздки, складки, поясок,
//                     щетина, матовые участки и ЧЁТКИЙ блик слизи.
//
// Порядок задан ЯВНО (см. ANAT_LAYER_ORDER и buildAnatomyStack) — слои не
// собираются "как получится" и не могут случайно перекрыть друг друга.
//
// Ключевые технические решения (см. ТЗ по производительности):
//   • НИ ОДНОГО feGaussianBlur и ни одной SMIL-анимации. Мягкость краёв
//     достигается радиальными градиентами с падающей до нуля прозрачностью,
//     а не фильтрами — это стоит примерно как обычная заливка.
//   • "Просвечивание" — не blend-mode, а честный полупрозрачный слой органов
//     МЕЖДУ кожей и её покрытием, с локальной непрозрачностью по зоне тела
//     (skin.thinness): на животе кожа тоньше — видно лучше, на голове почти
//     не видно.
//   • Формы органов имеют ЧЁТКИЙ контур (stroke) — именно он даёт
//     читаемость силуэта органа; мягко растворяется только заливка внутри.
//   • Вся анатомия части лежит в ОДНОЙ группе, обрезанной по силуэту этой
//     части (clipPath) — ни один слой физически не может вылезти за пределы
//     своего сегмента на соседний.
//   • Пульсация органов считается в tick() от dt (framerate-independent),
//     через отдельный аккумулятор фазы — тот же принцип, что и у остальных
//     анимаций рендерера.

const ANAT_LAYER_ORDER = ['tone', 'dorsoventral', 'muscle', 'organs', 'coat'];

// Резервная анатомия для старых сохранённых моделей, в которых блока
// anatomy ещё нет: рендерер тогда просто рисует как раньше.
const ANAT_DISABLED = { enabled: false };

function getAnatomy(model) {
    const a = model && model.anatomy;
    if (!a || !a.enabled) return ANAT_DISABLED;
    return a;
}

// Локальная прозрачность кожи по зоне тела. Ключ 'growing' покрывает все
// растущие сегменты сразу (их количество меняется со взрослением, поэтому
// перечислять их поимённо в модели нельзя).
function anatThinness(anatomy, partName, growingCount) {
    const t = (anatomy.skin && anatomy.skin.thinness) || {};
    const raw = t[partName];
    if (raw != null && !Array.isArray(raw)) return raw;

    if (partName && partName.indexOf('growing-') === 0) {
        const ramp = t.growing;
        if (ramp == null) return 1;
        if (!Array.isArray(ramp)) return ramp;
        // Растущие сегменты идут от живота к хвосту: первый просвечивает
        // почти как живот, последний почти как хвост.
        const idx = parseInt(partName.slice('growing-'.length), 10) || 1;
        const count = Math.max(1, growingCount || idx);
        const k = count > 1 ? (idx - 1) / (count - 1) : 0;
        return ramp[0] + (ramp[1] - ramp[0]) * k;
    }
    return raw != null ? raw : 1;
}

// Сид анатомии берётся из МОДЕЛИ (anatomy.seed), а не из instanceId — иначе
// один и тот же персонаж выглядел бы по-разному на главном экране и в
// мини-игре (у них разные instanceId). Узор особи должен быть её
// собственностью, а не свойством конкретного монтирования.
function anatRng(anatomy, partName, salt) {
    return mulberry32(hashStringSeed(`${anatomy.seed || 0}|${partName}|${salt || ''}`));
}

// Мягкое пятно: радиальный градиент, у которого прозрачность падает до нуля
// к краю. Это и есть замена размытию — края растворяются, но стоимость
// отрисовки как у обычной заливки.
function ensureSoftGradient(ctx, id, colorCss, peakAlpha) {
    if (ctx.gradCache[id]) return `url(#${id})`;
    const grad = svgEl('radialGradient', { id, cx: '50%', cy: '50%', r: '50%' });
    grad.appendChild(svgEl('stop', { offset: '0%', 'stop-color': colorCss, 'stop-opacity': peakAlpha.toFixed(3) }));
    grad.appendChild(svgEl('stop', { offset: '55%', 'stop-color': colorCss, 'stop-opacity': (peakAlpha * 0.5).toFixed(3) }));
    grad.appendChild(svgEl('stop', { offset: '100%', 'stop-color': colorCss, 'stop-opacity': '0' }));
    ctx.defs.appendChild(grad);
    ctx.gradCache[id] = true;
    return `url(#${id})`;
}

// Градиент "спина темнее — брюхо светлее". Один на весь инстанс: сила
// эффекта одинаковая для всех частей тела, поэтому дублировать его на
// каждый сегмент незачем.
function ensureDorsoVentralGradient(ctx) {
    const id = `worm-dv-${ctx.instanceId}`;
    if (ctx.gradCache[id]) return `url(#${id})`;
    const skin = ctx.anatomy.skin || {};
    const dark = skin.dorsalDarkening != null ? skin.dorsalDarkening : 0.3;
    const light = skin.ventralLightening != null ? skin.ventralLightening : 0.14;
    const grad = svgEl('linearGradient', { id, x1: '0', y1: '0', x2: '0', y2: '1' });
    grad.appendChild(svgEl('stop', { offset: '0%', 'stop-color': GRIME_SHADOW, 'stop-opacity': (dark * 0.75).toFixed(3) }));
    grad.appendChild(svgEl('stop', { offset: '30%', 'stop-color': GRIME_SHADOW, 'stop-opacity': (dark * 0.22).toFixed(3) }));
    grad.appendChild(svgEl('stop', { offset: '52%', 'stop-color': GRIME_SHADOW, 'stop-opacity': '0' }));
    grad.appendChild(svgEl('stop', { offset: '78%', 'stop-color': GRIME_HIGHLIGHT, 'stop-opacity': (light * 0.45).toFixed(3) }));
    grad.appendChild(svgEl('stop', { offset: '100%', 'stop-color': GRIME_HIGHLIGHT, 'stop-opacity': light.toFixed(3) }));
    ctx.defs.appendChild(grad);
    ctx.gradCache[id] = true;
    return `url(#${id})`;
}

// ---------- ПЛАН ОРГАНОВ ----------
// Органы — не "цветные пятна", а несколько РАЗНЫХ по форме и поведению
// структур. План (что где лежит) считается детерминированно от сида особи,
// поэтому у разных червей внутренности разложены по-разному, но у одного и
// того же червя всегда одинаково.
//
// zone:
//   'core'  — живот: самое насыщенное место (кишка + мешочек + узелки);
//   'neck'  — сегменты между головой и животом: кишка проходит транзитом;
//   'floor' — растущие сегменты: кишка + иногда узелки;
//   'tail'  — хвост: только тонкий отросток кишки;
//   'head'  — голова: органов нет (кожа/череп плотные), только сосудики в ушах.
function organPlanForZone(zone, rng, density) {
    const plan = [];
    const d = density != null ? density : 1;
    function maybe(chance) { return rng() < chance * d; }

    // ВАЖНО: отдельных "кишок" по сегментам здесь больше нет. Кишечник —
    // ОДИН непрерывный тракт на всё тело (см. buildGutTractGeometry): куски
    // кишки, живущие каждый в своём сегменте, не могут быть связаны между
    // собой в принципе — на каждом стыке был разрыв. Здесь остаются только
    // локальные органы: мешочки и грозди узелков.
    if (zone === 'core') {
        // ---------- ЖИВОТ: УЗНАВАЕМЫЕ ОРГАНЫ ----------
        // Раньше здесь лежали абстрактные "мешочек" и "гроздь узелков". Через
        // тонкую кожу живота это читалось как набор пятен: понятно, что
        // внутри что-то есть, непонятно что. Свиночервь — существо с
        // характером, и внутренности у него должны опознаваться: сердце как
        // сердце, желудок как желудок.
        //
        // Позиции слегка гуляют от сида, но НЕ произвольно: сердце всегда
        // выше и ближе к голове, желудок ниже и к хвосту от него. Анатомия у
        // особей одна, разными их делает мелочь, а не перестановка органов.
        // Сердце и желудок сидят в ВЕРХНЕЙ половине живота: петли кишечника
        // занимают низ, и органы, положенные по центру, тонули в них.
        plan.push({
            kind: 'heart', cx: 0.32 + rng() * 0.08, cy: -0.44 - rng() * 0.06, len: 0.34, thick: 0.38,
            rot: rng() * 16 - 8, speedMul: 2.1, ampMul: 1.8, phase: rng() * 6.28
        });
        plan.push({
            kind: 'stomach', cx: -0.22 + rng() * 0.08, cy: -0.3 + rng() * 0.06, len: 0.46, thick: 0.42,
            rot: rng() * 14 - 7, speedMul: 0.75, ampMul: 0.9, phase: rng() * 6.28
        });
        // Рёбра идут последними: они обнимают органы снаружи, значит и
        // рисуются поверх них — ближе к коже.
        plan.push({
            kind: 'ribs', cx: 0, cy: 0, len: 0.92, thick: 0.86, count: 5,
            rot: 0, speedMul: 0.5, ampMul: 0.35, phase: rng() * 6.28
        });
    } else if (zone === 'neck') {
        // В сегменте перед животом рёбер меньше — грудная клетка сходит на нет.
        plan.push({
            kind: 'ribs', cx: 0, cy: 0, len: 0.8, thick: 0.78, count: 3,
            rot: 0, speedMul: 0.5, ampMul: 0.3, phase: rng() * 6.28
        });
    } else if (zone === 'floor') {
        if (maybe(0.65)) {
            plan.push({
                kind: 'node', cx: -0.25 + rng() * 0.5, cy: -0.22, len: 0.16, thick: 0.18,
                rot: rng() * 40 - 20, speedMul: 1.2, ampMul: 0.7, phase: rng() * 6.28
            });
        }
    }
    return plan;
}

// Сосудистая сеть, расходящаяся от органа. На хороших артах именно она
// связывает внутренности с телом: орган без сосудов выглядит проглоченным
// предметом, а не частью существа. Рекурсивное ветвление, каждый уровень
// тоньше и бледнее предыдущего.
function buildVesselTree(group, rng, x, y, angle, len, depth, color, width) {
    if (depth <= 0 || len < 1.5) return;
    const spread = (rng() - 0.5) * 0.9;
    const ex = x + Math.cos(angle) * len;
    const ey = y + Math.sin(angle) * len;
    const cx = x + Math.cos(angle + spread * 0.6) * len * 0.55;
    const cy = y + Math.sin(angle + spread * 0.6) * len * 0.55;
    group.appendChild(svgEl('path', {
        d: `M ${x.toFixed(1)},${y.toFixed(1)} Q ${cx.toFixed(1)},${cy.toFixed(1)} ${ex.toFixed(1)},${ey.toFixed(1)}`,
        fill: 'none', stroke: color, 'stroke-width': width.toFixed(2),
        'stroke-linecap': 'round', opacity: (0.28 + 0.12 * depth).toFixed(2)
    }));
    const branches = depth > 1 ? 2 : 1;
    for (let i = 0; i < branches; i++) {
        buildVesselTree(group, rng, ex, ey,
            angle + (rng() - 0.5) * 1.5, len * (0.5 + rng() * 0.25),
            depth - 1, color, Math.max(0.35, width * 0.6));
    }
}

// Один орган: заливка мягко растворяется к краям (без фильтров), а КОНТУР
// остаётся чётким — именно контур делает орган "формой", а не пятном света.
function buildOrganNode(ctx, plan, halfLen, halfThick, idKey) {
    const palette = (ctx.anatomy.organs && ctx.anatomy.organs.palette) || {};
    const group = svgEl('g', { class: `worm-organ worm-organ-${plan.kind}` });
    const x = plan.cx * halfLen;
    const y = plan.cy * halfThick;

    if (plan.kind === 'gut') {
        const color = palette.gut || VISCERA[700];
        const L = plan.len * halfLen;
        const w = Math.max(2.2, plan.thick * halfThick);
        const bend = (plan.bend || 0.3) * halfThick * 0.9;
        const d = `M ${(-L).toFixed(1)},0 C ${(-L * 0.45).toFixed(1)},${(-bend).toFixed(1)} ` +
                  `${(L * 0.45).toFixed(1)},${bend.toFixed(1)} ${L.toFixed(1)},0`;
        // Мягкая тень вокруг трубки — орган лежит ПОД кожей, а не наклеен
        // сверху. Без неё даже правильный по цвету орган читается как
        // нарисованная поверх линия.
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: GRIME_SHADOW,
            'stroke-width': (w + 5).toFixed(1), 'stroke-linecap': 'round', opacity: 0.16
        }));
        // Контур (чуть шире и темнее) — читаемая граница трубки.
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.5),
            'stroke-width': (w + 1.8).toFixed(1), 'stroke-linecap': 'round', opacity: 0.7
        }));
        // Тело трубки.
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: color,
            'stroke-width': w.toFixed(1), 'stroke-linecap': 'round', opacity: 1
        }));
        // Продольный светлый рефлекс вдоль трубки — она читается объёмной,
        // а не плоской лентой.
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: mixColor(color, GRIME_HIGHLIGHT, 0.5),
            'stroke-width': Math.max(0.8, w * 0.28).toFixed(1), 'stroke-linecap': 'round',
            opacity: 0.35, transform: `translate(0,${(-w * 0.22).toFixed(1)})`
        }));
    } else if (plan.kind === 'sac') {
        // Капсула из пяти слоёв, как на референсных артах: тень под органом →
        // ореол свечения → тело → чёткий ободок → яркое ядро с бликом.
        // Свечение сделано вложенными градиентами с падающей прозрачностью —
        // визуально это то же, что размытие, но без единого фильтра.
        const color = palette.sac || BILE[600];
        const glow = (ctx.anatomy.organs && ctx.anatomy.organs.glow != null) ? ctx.anatomy.organs.glow : 0.6;
        const rx = plan.len * halfLen;
        const ry = plan.thick * halfThick;
        const gid = `worm-organ-sac-${ctx.instanceId}-${idKey}`;
        const fill = ensureSoftGradient(ctx, gid, color, 1);
        const shadowGid = `worm-organ-shadow-${ctx.instanceId}`;
        const coreColor = mixColor(color, BILE[200], 0.62);

        group.appendChild(svgEl('ellipse', {
            cx: 0, cy: 0, rx: (rx * 1.35).toFixed(1), ry: (ry * 1.35).toFixed(1),
            fill: ensureSoftGradient(ctx, shadowGid, GRIME_SHADOW, 1), opacity: 0.28
        }));
        if (glow > 0.02) {
            const glowFill = ensureSoftGradient(ctx, `worm-organ-glow-${ctx.instanceId}-${idKey}`, coreColor, 1);
            group.appendChild(svgEl('ellipse', {
                cx: 0, cy: 0, rx: (rx * 2.1).toFixed(1), ry: (ry * 2.1).toFixed(1),
                fill: glowFill, opacity: (0.32 * glow).toFixed(3)
            }));
            group.appendChild(svgEl('ellipse', {
                cx: 0, cy: 0, rx: (rx * 1.45).toFixed(1), ry: (ry * 1.45).toFixed(1),
                fill: glowFill, opacity: (0.3 * glow).toFixed(3)
            }));
        }
        group.appendChild(svgEl('ellipse', { cx: 0, cy: 0, rx: rx.toFixed(1), ry: ry.toFixed(1), fill }));
        group.appendChild(svgEl('ellipse', {
            cx: 0, cy: 0, rx: rx.toFixed(1), ry: ry.toFixed(1),
            fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.45),
            'stroke-width': SW.detail, opacity: 0.75
        }));
        group.appendChild(svgEl('ellipse', {
            cx: (-rx * 0.12).toFixed(1), cy: (-ry * 0.12).toFixed(1),
            rx: (rx * 0.45).toFixed(1), ry: (ry * 0.45).toFixed(1),
            fill: coreColor, opacity: (0.5 + 0.3 * glow).toFixed(2)
        }));
        group.appendChild(svgEl('ellipse', {
            cx: (-rx * 0.3).toFixed(1), cy: (-ry * 0.34).toFixed(1),
            rx: (rx * 0.16).toFixed(1), ry: (ry * 0.13).toFixed(1),
            fill: SPEC, opacity: 0.4
        }));

        // Сосуды от капсулы — 3-5 стволов в разные стороны.
        const vrng = anatRng(ctx.anatomy, idKey, 'vessels');
        const vGroup = svgEl('g', { class: 'worm-organ-vessels' });
        const vColor = mixColor(color, palette.vessel || VISCERA[700], 0.45);
        const trunks = 3 + Math.floor(vrng() * 3);
        for (let i = 0; i < trunks; i++) {
            const a = (i / trunks) * Math.PI * 2 + vrng() * 0.6;
            buildVesselTree(vGroup, vrng,
                Math.cos(a) * rx * 0.85, Math.sin(a) * ry * 0.85, a,
                Math.max(rx, ry) * (0.7 + vrng() * 0.6), 3, vColor, 1.1);
        }
        group.insertBefore(vGroup, group.firstChild ? group.firstChild.nextSibling : null);
    } else if (plan.kind === 'heart') {
        // ---------- СЕРДЦЕ ----------
        // Силуэт узнаваемый, детализация минимальная: сквозь кожу видно
        // пятно, и всё, что от него требуется — читаться как сердце с
        // первого взгляда. Анатомически достоверное сердце в этом размере
        // превратится в кляксу.
        const color = palette.heart || VISCERA[700];
        const rx = plan.len * halfLen;
        const ry = plan.thick * halfThick;
        // Классический силуэт: две доли сверху, острие вниз.
        const d = `M 0,${(-ry * 0.32).toFixed(1)} ` +
                  `C ${(-rx * 0.52).toFixed(1)},${(-ry * 1.15).toFixed(1)} ` +
                  `${(-rx * 1.18).toFixed(1)},${(-ry * 0.1).toFixed(1)} ` +
                  `0,${(ry * 0.98).toFixed(1)} ` +
                  `C ${(rx * 1.18).toFixed(1)},${(-ry * 0.1).toFixed(1)} ` +
                  `${(rx * 0.52).toFixed(1)},${(-ry * 1.15).toFixed(1)} ` +
                  `0,${(-ry * 0.32).toFixed(1)} Z`;

        group.appendChild(svgEl('path', {
            d, fill: ensureSoftGradient(ctx, `worm-organ-shadow-${ctx.instanceId}`, GRIME_SHADOW, 1),
            opacity: 0.3, transform: 'scale(1.25)'
        }));
        group.appendChild(svgEl('path', { d, fill: color, opacity: 0.95 }));
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.5),
            'stroke-width': SW.detail, opacity: 0.8
        }));
        // Блик на левой доле — объём.
        group.appendChild(svgEl('ellipse', {
            cx: (-rx * 0.34).toFixed(1), cy: (-ry * 0.34).toFixed(1),
            rx: (rx * 0.22).toFixed(1), ry: (ry * 0.18).toFixed(1),
            fill: mixColor(color, GRIME_HIGHLIGHT, 0.5), opacity: 0.45
        }));
        // Пара крупных сосудов сверху: без них сердце висит само по себе.
        const hrng = anatRng(ctx.anatomy, idKey, 'heart-vessels');
        const vColor = mixColor(color, palette.vessel || VISCERA[700], 0.5);
        buildVesselTree(group, hrng, -rx * 0.3, -ry * 0.75, -1.9, Math.max(rx, ry) * 0.9, 2, vColor, 1.3);
        buildVesselTree(group, hrng, rx * 0.25, -ry * 0.8, -1.2, Math.max(rx, ry) * 0.8, 2, vColor, 1.1);
    } else if (plan.kind === 'stomach') {
        // ---------- ЖЕЛУДОК ----------
        // Мешок-фасолина: широкий свод слева-сверху, сужается к выходу
        // справа-снизу. Именно этот изгиб и делает силуэт узнаваемым.
        const color = palette.stomach || VISCERA[700];
        const rx = plan.len * halfLen;
        const ry = plan.thick * halfThick;
        const d = `M ${(-rx * 0.75).toFixed(1)},${(-ry * 0.2).toFixed(1)} ` +
                  `C ${(-rx * 0.7).toFixed(1)},${(-ry * 1.05).toFixed(1)} ` +
                  `${(rx * 0.45).toFixed(1)},${(-ry * 1.1).toFixed(1)} ` +
                  `${(rx * 0.62).toFixed(1)},${(-ry * 0.3).toFixed(1)} ` +
                  `C ${(rx * 0.78).toFixed(1)},${(ry * 0.45).toFixed(1)} ` +
                  `${(rx * 0.2).toFixed(1)},${(ry * 1.02).toFixed(1)} ` +
                  `${(-rx * 0.28).toFixed(1)},${(ry * 0.82).toFixed(1)} ` +
                  `C ${(-rx * 0.72).toFixed(1)},${(ry * 0.66).toFixed(1)} ` +
                  `${(-rx * 0.92).toFixed(1)},${(ry * 0.2).toFixed(1)} ` +
                  `${(-rx * 0.75).toFixed(1)},${(-ry * 0.2).toFixed(1)} Z`;

        group.appendChild(svgEl('path', {
            d, fill: ensureSoftGradient(ctx, `worm-organ-shadow-${ctx.instanceId}`, GRIME_SHADOW, 1),
            opacity: 0.26, transform: 'scale(1.2)'
        }));
        group.appendChild(svgEl('path', { d, fill: color, opacity: 0.92 }));
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.5),
            'stroke-width': SW.detail, opacity: 0.75
        }));
        // Содержимое: пока пусто, наполняется при кормёжке. Отдельным
        // элементом, а не перекраской желудка: желудок должен оставаться
        // собой, просто с комком внутри.
        const content = svgEl('ellipse', {
            class: 'worm-stomach-content',
            cx: (-rx * 0.08).toFixed(1), cy: (ry * 0.12).toFixed(1),
            rx: 0, ry: 0, fill: mixColor(color, BILE[400], 0.5), opacity: 0.85
        });
        content.setAttribute('data-full-rx', (rx * 0.52).toFixed(1));
        content.setAttribute('data-full-ry', (ry * 0.46).toFixed(1));
        group.appendChild(content);

        // Складки на своде — стенка желудка не гладкий шар.
        const srng = anatRng(ctx.anatomy, idKey, 'stomach-folds');
        for (let i = 0; i < 3; i++) {
            const fy = -ry * (0.45 - i * 0.3) + (srng() - 0.5) * ry * 0.12;
            group.appendChild(svgEl('path', {
                d: `M ${(-rx * 0.5).toFixed(1)},${fy.toFixed(1)} Q 0,${(fy + ry * 0.22).toFixed(1)} ${(rx * 0.42).toFixed(1)},${(fy + ry * 0.05).toFixed(1)}`,
                fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.35),
                'stroke-width': SW.hairline, opacity: 0.5
            }));
        }
    } else if (plan.kind === 'ribs') {
        // ---------- РЁБРА ----------
        // Червю рёбра не полагаются, но это и не червь: свиночервю они нужны
        // для образа — грудная клетка сразу превращает «мешок с органами» в
        // существо. Дуги обнимают внутренности, поэтому и рисуются поверх
        // них, ближе к коже.
        const color = palette.bone || BILE[200];
        const count = plan.count || 5;
        const halfSpan = plan.len * halfLen;
        const reach = plan.thick * halfThick;
        const rrng = anatRng(ctx.anatomy, idKey, 'ribs');
        for (let i = 0; i < count; i++) {
            const k = count > 1 ? i / (count - 1) : 0.5;
            const cx = (k * 2 - 1) * halfSpan * 0.72;
            // Крайние рёбра короче: клетка сужается к концам.
            const shrink = 0.72 + 0.28 * Math.sin(Math.PI * k);
            const drop = reach * shrink;
            // Рёбра расходятся веером от середины, а не стоят параллельно:
            // параллельные дуги читаются как решётка радиатора, а не как
            // грудная клетка. Верхний конец ребра клонится к центру, нижний
            // уходит наружу.
            const side = (k * 2 - 1);
            const lean = side * halfSpan * 0.16;
            const bow = drop * (0.5 + rrng() * 0.12) * (side >= 0 ? 1 : -1);
            const d = `M ${(cx - lean).toFixed(1)},${(-drop).toFixed(1)} ` +
                      `Q ${(cx + bow).toFixed(1)},0 ${(cx + lean * 0.6).toFixed(1)},${(drop * 0.84).toFixed(1)}`;
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: mixColor(color, GRIME_SHADOW, 0.55),
                'stroke-width': (SW.structure * 1.1).toFixed(2), 'stroke-linecap': 'round', opacity: 0.32
            }));
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: color,
                'stroke-width': SW.structure,
                'stroke-linecap': 'round', opacity: 0.55
            }));
        }
    } else if (plan.kind === 'node') {
        const color = palette.node || BILE[400];
        const rng = anatRng(ctx.anatomy, idKey, 'node');
        const base = plan.thick * halfThick;
        for (let i = 0; i < 3; i++) {
            const r = base * (0.45 + rng() * 0.4);
            const nx = (rng() - 0.5) * plan.len * halfLen * 1.4;
            const ny = (rng() - 0.5) * base * 1.2;
            group.appendChild(svgEl('circle', {
                cx: nx.toFixed(1), cy: ny.toFixed(1), r: r.toFixed(1),
                fill: color, opacity: 0.75,
                stroke: mixColor(color, GRIME_SHADOW, 0.45), 'stroke-width': SW.hairline
            }));
            group.appendChild(svgEl('circle', {
                cx: (nx - r * 0.2).toFixed(1), cy: (ny - r * 0.2).toFixed(1), r: (r * 0.42).toFixed(1),
                fill: mixColor(color, BILE[200], 0.55), opacity: 0.6
            }));
        }
    }

    group.setAttribute('transform', `translate(${x.toFixed(1)},${y.toFixed(1)}) rotate(${(plan.rot || 0).toFixed(1)})`);
    return {
        group, x, y, rot: plan.rot || 0, kind: plan.kind,
        speedMul: plan.speedMul || 1, ampMul: plan.ampMul || 1, phase: plan.phase || 0
    };
}

// ---------- СЛОЙ МЫШЦ ----------
// Продольные тяжи: слегка светлее по верхней грани и темнее по нижней —
// читается как объёмный жгут под кожей, а не как нарисованная полоска.
function buildMuscleLayer(ctx, partName, halfLen, halfThick, enabled) {
    if (enabled === false) return null;
    const muscle = ctx.anatomy.muscle || {};
    const tone = muscle.tone != null ? muscle.tone : 0.55;
    if (tone <= 0.01) return null;
    const bundles = Math.max(1, Math.round(muscle.bundles != null ? muscle.bundles : 3));
    const rng = anatRng(ctx.anatomy, partName, 'muscle');
    const group = svgEl('g', { class: 'worm-muscle-layer' });

    for (let i = 0; i < bundles; i++) {
        const t = bundles === 1 ? 0 : (i / (bundles - 1)) * 2 - 1; // -1..1 поперёк тела
        const cy = t * halfThick * 0.5 + (rng() - 0.5) * halfThick * 0.12;
        const L = halfLen * (0.62 + rng() * 0.24);
        const w = halfThick * (0.16 + rng() * 0.1);
        const bend = (rng() - 0.5) * halfThick * 0.3;
        const d = `M ${(-L).toFixed(1)},${cy.toFixed(1)} Q 0,${(cy + bend).toFixed(1)} ${L.toFixed(1)},${cy.toFixed(1)}`;
        // Тяж читается ОЩУЩЕНИЕМ рельефа, а не нарисованной полоской:
        // непрозрачность намеренно низкая (единицы процентов), светлая грань
        // сверху и тёмная снизу дают лёгкую выпуклость под кожей. Всё, что
        // выше этих значений, немедленно превращается в "полосатую банку".
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: GRIME_HIGHLIGHT,
            'stroke-width': w.toFixed(1), 'stroke-linecap': 'round',
            opacity: (0.055 * tone).toFixed(3),
            transform: `translate(0,${(-w * 0.55).toFixed(1)})`
        }));
        group.appendChild(svgEl('path', {
            d, fill: 'none', stroke: GRIME_SHADOW,
            'stroke-width': (w * 0.8).toFixed(1), 'stroke-linecap': 'round',
            opacity: (0.075 * tone).toFixed(3),
            transform: `translate(0,${(w * 0.6).toFixed(1)})`
        }));
    }
    return group;
}

// ---------- СЛОЙ НЕОДНОРОДНОСТИ ТОНА КОЖИ ----------
// "У каждой особи/сегмента — вариация тона, а не одна плоская заливка":
// 2-4 крупных мягких пятна (светлее/темнее) поверх базовой заливки.
function buildSkinToneLayer(ctx, partName, halfLen, halfThick) {
    const skin = ctx.anatomy.skin || {};
    const amount = skin.toneVariation != null ? skin.toneVariation : 0.55;
    if (amount <= 0.01) return null;
    const rng = anatRng(ctx.anatomy, partName, 'tone');
    const group = svgEl('g', { class: 'worm-skin-tone' });
    const count = 2 + Math.floor(rng() * 3);
    for (let i = 0; i < count; i++) {
        const dark = rng() < 0.55;
        const color = dark ? GRIME_SHADOW : GRIME_HIGHLIGHT;
        const gid = `worm-tone-${ctx.instanceId}-${dark ? 'd' : 'l'}`;
        const fill = ensureSoftGradient(ctx, gid, color, 1);
        const rx = halfLen * (0.28 + rng() * 0.3);
        const ry = halfThick * (0.3 + rng() * 0.32);
        const cx = (rng() * 2 - 1) * halfLen * 0.5;
        const cy = (rng() * 2 - 1) * halfThick * 0.45;
        // Тёмные пятна работают лучше светлых: светлое пятно на розовой коже
        // быстро начинает читаться как запотевшее стекло, тёмное — как
        // неровный пигмент. Поэтому у светлых заметно меньший вес.
        group.appendChild(svgEl('ellipse', {
            cx: cx.toFixed(1), cy: cy.toFixed(1), rx: rx.toFixed(1), ry: ry.toFixed(1),
            fill, opacity: ((dark ? 0.34 : 0.14) * amount).toFixed(3)
        }));
    }
    return group;
}

// ---------- СЛОЙ ПОКРЫТИЯ КОЖИ ----------
// Кольцевые бороздки (червь), складки (свинья), поясок-клителлум, щетина,
// матовые участки и ЧЁТКИЙ блик слизи. Разные части тела получают разный
// набор — не одинаковый шаблон на всё тело.
//
// features:
//   rings — кольцевая сегментация; folds — свиные складки;
//   bristle — щетина; clitellum — поясок; vessel — спинной сосуд.
function buildCoatLayer(ctx, partName, halfLen, halfThick, features) {
    const coat = ctx.anatomy.coat || {};
    const rng = anatRng(ctx.anatomy, partName, 'coat');
    const group = svgEl('g', { class: 'worm-coat-layer' });
    let empty = true;

    // --- кольцевые бороздки: у дождевого червя тело разбито на кольца,
    // и это самая узнаваемая его черта. Рисуются дугами ПОПЕРЁК тела.
    // Важно: бороздка — это ВМЯТИНА, а не нарисованная линия. Поэтому она
    // (а) не пересекает сегмент насквозь — обрывается, не доходя до контура,
    // (б) заметно изогнута по кривизне тела, (в) сопровождается светлым
    // ребром с одной стороны. Прямая линия через весь сегмент читается как
    // полоска краски на банке — ровно это и было первой ошибкой.
    const rings = features.rings === false ? 0 : (coat.rings != null ? coat.rings : 0.5);
    if (rings > 0.01) {
        const count = 2 + Math.floor(rng() * 2);
        for (let i = 0; i < count; i++) {
            const t = (i + 1) / (count + 1);
            const x = (t * 2 - 1) * halfLen * 0.66 + (rng() - 0.5) * halfLen * 0.1;
            const h = halfThick * (0.5 + rng() * 0.14);
            const curve = halfLen * 0.22 * (x > 0 ? 1 : -1);
            const d = `M ${x.toFixed(1)},${(-h).toFixed(1)} Q ${(x + curve).toFixed(1)},0 ${x.toFixed(1)},${h.toFixed(1)}`;
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: GRIME_SHADOW, 'stroke-width': SW.detail,
                opacity: (0.16 * rings).toFixed(3), 'stroke-linecap': 'round'
            }));
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: GRIME_HIGHLIGHT, 'stroke-width': SW.hairline,
                opacity: (0.1 * rings).toFixed(3), 'stroke-linecap': 'round',
                transform: 'translate(1.8,0)'
            }));
            empty = false;
        }
    }

    // --- поясок (клителлум): у зрелого червя 14-16 сегменты охвачены
    // гладким утолщённым "ошейником". Здесь он живёт на сегменте-2 и
    // заодно визуально сшивает свиную голову с червячным телом.
    if (features.clitellum && (coat.clitellum || 0) > 0.01) {
        const strength = coat.clitellum;
        const w = halfLen * 0.5;
        group.appendChild(svgEl('ellipse', {
            cx: 0, cy: 0, rx: w.toFixed(1), ry: (halfThick * 0.99).toFixed(1),
            fill: GRIME_HIGHLIGHT, opacity: (0.14 * strength).toFixed(3)
        }));
        [-w, w].forEach(edge => {
            group.appendChild(svgEl('path', {
                d: `M ${edge.toFixed(1)},${(-halfThick * 0.92).toFixed(1)} Q ${(edge * 1.12).toFixed(1)},0 ${edge.toFixed(1)},${(halfThick * 0.92).toFixed(1)}`,
                fill: 'none', stroke: GRIME_SHADOW, 'stroke-width': SW.detail,
                opacity: (0.3 * strength).toFixed(3), 'stroke-linecap': 'round'
            }));
        });
        empty = false;
    }

    // --- свиные складки: короткие мягкие дуги у "плеча" (там, где кожа
    // собирается при движении). Длинные штрихи через всю часть читались на
    // морде как царапины или усы — поэтому длина ограничена третью
    // поперечника, а сами складки прижаты к краю силуэта.
    if (features.folds && (coat.folds || 0) > 0.01) {
        const strength = coat.folds;
        const count = 2;
        for (let i = 0; i < count; i++) {
            const x = -halfLen * (0.42 + i * 0.18) - rng() * halfLen * 0.05;
            const y0 = -halfThick * (0.05 + rng() * 0.16);
            const len = halfThick * (0.24 + rng() * 0.12);
            const d = `M ${x.toFixed(1)},${y0.toFixed(1)} q ${(halfLen * 0.08).toFixed(1)},${(len * 0.5).toFixed(1)} ${(-halfLen * 0.02).toFixed(1)},${len.toFixed(1)}`;
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: GRIME_SHADOW, 'stroke-width': SW.detail,
                opacity: (0.16 * strength).toFixed(3), 'stroke-linecap': 'round'
            }));
            group.appendChild(svgEl('path', {
                d, fill: 'none', stroke: GRIME_HIGHLIGHT, 'stroke-width': SW.hairline,
                opacity: (0.1 * strength).toFixed(3), 'stroke-linecap': 'round',
                transform: 'translate(-1.2,0)'
            }));
            empty = false;
        }
    }

    // --- щетина: короткие редкие волоски ВДОЛЬ ВЕРХНЕГО КРАЯ силуэта.
    // Раньше они сеялись по всей площади части и на морде читались как
    // царапины/усы. Настоящая свиная щетина заметна именно на просвет по
    // контуру — поэтому каждый волосок ставится на дугу у края (радиус
    // 0.72..0.94 от габарита) и растёт наружу, коротким штрихом.
    if (features.bristle && (coat.bristle || 0) > 0.01) {
        const strength = coat.bristle;
        const count = 5 + Math.floor(rng() * 4);
        for (let i = 0; i < count; i++) {
            // Угол только по верхней половине: 200°..340°.
            const ang = (200 + (i / count) * 140 + rng() * 12) * Math.PI / 180;
            const rr = 0.72 + rng() * 0.2;
            const bx = Math.cos(ang) * halfLen * rr;
            const by = Math.sin(ang) * halfThick * rr;
            const len = 1.6 + rng() * 1.8;
            group.appendChild(svgEl('path', {
                d: `M ${bx.toFixed(1)},${by.toFixed(1)} l ${(Math.cos(ang) * len).toFixed(1)},${(Math.sin(ang) * len * 1.2).toFixed(1)}`,
                stroke: GRIME_SHADOW, 'stroke-width': SW.hairline, fill: 'none',
                opacity: (0.32 * strength).toFixed(3), 'stroke-linecap': 'round'
            }));
            empty = false;
        }
    }

    // --- спинной сосуд: тёмная линия, идущая под кожей вдоль всей спины.
    // У настоящего дождевого червя это самая заметная просвечивающая
    // структура — и заодно бесплатный способ связать сегменты в одно тело.
    if (features.vessel && (coat.dorsalVessel || 0) > 0.01) {
        const palette = (ctx.anatomy.organs && ctx.anatomy.organs.palette) || {};
        const strength = coat.dorsalVessel;
        const y = -halfThick * 0.55;
        group.appendChild(svgEl('path', {
            d: `M ${(-halfLen * 0.9).toFixed(1)},${y.toFixed(1)} Q 0,${(y - halfThick * 0.12).toFixed(1)} ${(halfLen * 0.9).toFixed(1)},${y.toFixed(1)}`,
            fill: 'none', stroke: palette.vessel || VISCERA[700], 'stroke-width': SW.detail,
            opacity: (0.5 * strength).toFixed(3), 'stroke-linecap': 'round'
        }));
        empty = false;
    }

    return empty ? null : group;
}

// ---------- ПОВЕРХНОСТЬ: БЛЕСК СЛИЗИ И МАТОВЫЕ УЧАСТКИ ----------
// Отдельный слой от buildCoatLayer, и вот почему: складки, кольца и щетина —
// свойства САМОЙ ТКАНИ, они живут в системе координат тела (вдоль/поперёк
// сегмента). А блеск — это отражение внешнего света, он должен быть с одной
// и той же стороны у ВСЕХ частей тела, как бы они ни были повёрнуты. Пока
// блеск считался вместе с остальным покрытием, у вертикально стоящих
// сегментов он уезжал вбок и читался как полоска краски на банке.
//
// Форма блика — узкий серп с ЧЁТКИМИ краями, изогнутый по кривизне части
// (референс: в 2D слизь и мокрая кожа рисуются жёсткой кистью поверх
// матовой основы; размытое пятно вместо блика — самая частая ошибка,
// именно она и провалила первую попытку с blur).
function buildSurfaceLayer(ctx, partName, rx, ry, features) {
    const coat = ctx.anatomy.coat || {};
    const group = svgEl('g', { class: 'worm-surface-layer' });
    let empty = true;

    // Контактная тень: часть, стоящая непосредственно под другой (шея под
    // головой), должна получать от неё тень — иначе на светлой коже шеи
    // граница головы растворяется и голова кажется парящей.
    if (features && features.contactTop) {
        const gid = `worm-contact-${ctx.instanceId}`;
        group.appendChild(svgEl('ellipse', {
            cx: 0, cy: (-ry * 0.72).toFixed(1),
            rx: (rx * 0.92).toFixed(1), ry: (ry * 0.5).toFixed(1),
            fill: ensureSoftGradient(ctx, gid, GRIME_SHADOW, 1),
            opacity: (0.3 * (features.contactStrength || 1)).toFixed(3)
        }));
        empty = false;
    }

    const matte = coat.matte != null ? coat.matte : 0.35;
    if (matte > 0.01) {
        const gid = `worm-matte-${ctx.instanceId}`;
        const fill = ensureSoftGradient(ctx, gid, GRIME_SHADOW, 1);
        group.appendChild(svgEl('ellipse', {
            cx: (rx * 0.3).toFixed(1), cy: (ry * 0.42).toFixed(1),
            rx: (rx * 0.46).toFixed(1), ry: (ry * 0.42).toFixed(1),
            fill, opacity: (0.26 * matte).toFixed(3)
        }));
        empty = false;
    }

    const gloss = coat.slimeGloss != null ? coat.slimeGloss : 0.55;
    if (gloss > 0.01) {
        // Серп: внешняя дуга по верхне-левой части силуэта, внутренняя —
        // чуть ниже, из-за чего фигура сходится в тонкие острые концы.
        const R = 0.62;                 // на каком удалении от центра лежит блик
        const a0 = Math.PI * 1.12, a1 = Math.PI * 1.62; // сектор верх-лево
        const p = (ang, k) => `${(Math.cos(ang) * rx * R * k).toFixed(1)},${(Math.sin(ang) * ry * R * k).toFixed(1)}`;
        const mid = (a0 + a1) / 2;
        const d = `M ${p(a0, 1)} Q ${p(mid, 1.13)} ${p(a1, 1)} Q ${p(mid, 0.9)} ${p(a0, 1)} Z`;
        // Широкий серп — это ОТРАЖЁННЫЙ СВЕТ на влажной коже, а не сама
        // слизь, поэтому он тёплый, а не кислотный: блик перенимает цвет
        // источника света, а не вещества. Кислоту сюда класть нельзя ещё и
        // физически — полупрозрачная заливка не может быть насыщеннее смеси
        // с подложкой, кислотная зелень на розовом даёт хаки, и акцент
        // умирает, размазанный по большой площади.
        group.appendChild(svgEl('path', { d, fill: SPEC, opacity: (0.3 * gloss).toFixed(3) }));
        // А вот это — САМА слизь: маленькая, почти непрозрачная капля.
        // Акцент работает малой площадью и высокой плотностью, ровно
        // наоборот к широкому блику (docs/art-direction.md §2.5).
        group.appendChild(svgEl('ellipse', {
            cx: (rx * 0.34).toFixed(1), cy: (-ry * 0.34).toFixed(1),
            rx: (rx * 0.11).toFixed(1), ry: (ry * 0.085).toFixed(1),
            fill: ACID, opacity: (0.88 * gloss).toFixed(3)
        }));
        // Блик на самой капле — она выпуклая и мокрая.
        group.appendChild(svgEl('ellipse', {
            cx: (rx * 0.32).toFixed(1), cy: (-ry * 0.36).toFixed(1),
            rx: (rx * 0.04).toFixed(1), ry: (ry * 0.03).toFixed(1),
            fill: SPEC, opacity: (0.7 * gloss).toFixed(3)
        }));
        empty = false;
    }

    return empty ? null : group;
}

// ---------- СБОРКА ВСЕЙ СТОПКИ СЛОЁВ ДЛЯ ОДНОЙ ЧАСТИ ТЕЛА ----------
// Возвращает { group, organs, muscleGroup } либо null, если анатомия
// выключена. group — ОДИН узел, который вызывающий код кладёт в нужное
// место своей части; всё, что внутри, обрезано по силуэту этой части.
//
// axis:  'x' — тело части вытянуто вдоль экранного X (напольная цепь,
//              живот, хвост);
//        'y' — часть стоит "столбиком" (сегменты между головой и животом):
//              слои строятся в той же локальной системе (вдоль → +X) и
//              разворачиваются поворотом на 90°, чтобы продольные структуры
//              шли вдоль тела, а не поперёк него.
function buildAnatomyStack(ctx, partName, opts) {
    const anatomy = ctx.anatomy;
    if (!anatomy.enabled) return null;

    const rx = opts.rx, ry = opts.ry;
    const axis = opts.axis || 'x';
    const halfLen = axis === 'x' ? rx : ry;
    const halfThick = axis === 'x' ? ry : rx;

    // Клип по силуэту части — гарантия, что ни один слой не вылезет на
    // соседний сегмент, какие бы параметры ни выставили.
    const clipId = `worm-anat-clip-${ctx.instanceId}-${partName}`;
    const clip = svgEl('clipPath', { id: clipId });
    if (opts.clipPathData) {
        clip.appendChild(svgEl('path', { d: opts.clipPathData }));
    } else {
        clip.appendChild(svgEl('ellipse', { cx: 0, cy: 0, rx: rx.toFixed(2), ry: ry.toFixed(2) }));
    }
    ctx.defs.appendChild(clip);

    // Внешняя группа — её масштабирует tick() (дыхание/раздутие живота).
    // Внутренняя — держит клип, ещё внутри — разворот вдоль оси тела.
    const outer = svgEl('g', { class: 'worm-anatomy', 'data-anat': partName });
    const clipped = svgEl('g', { 'clip-path': `url(#${clipId})` });
    const axisGroup = svgEl('g', axis === 'y' ? { transform: 'rotate(90)' } : null);
    clipped.appendChild(axisGroup);
    outer.appendChild(clipped);

    const layers = {};
    layers.tone = buildSkinToneLayer(ctx, partName, halfLen, halfThick);

    if ((anatomy.skin && (anatomy.skin.dorsalDarkening || anatomy.skin.ventralLightening))) {
        const dv = svgEl('ellipse', {
            cx: 0, cy: 0, rx: halfLen.toFixed(2), ry: halfThick.toFixed(2),
            fill: ensureDorsoVentralGradient(ctx)
        });
        layers.dorsoventral = dv;
    }

    layers.muscle = buildMuscleLayer(ctx, partName, halfLen, halfThick, opts.muscle);

    // Органы: собственная группа с непрозрачностью = общая видимость ×
    // локальная тонкость кожи в этой зоне. Именно здесь "разная степень
    // просвечивания в разных местах" — не в blur и не в blend-mode.
    const organs = [];
    const zone = opts.organZone;
    if (zone && anatomy.organs && (anatomy.organs.visibility || 0) > 0.01) {
        const thin = anatThinness(anatomy, partName, ctx.growingCount);
        const alpha = clamp01(anatomy.organs.visibility * thin);
        if (alpha > 0.02) {
            const rng = anatRng(anatomy, partName, 'organs');
            const plan = organPlanForZone(zone, rng, anatomy.organs.density);
            const organGroup = svgEl('g', { class: 'worm-organ-layer', opacity: alpha.toFixed(3) });
            plan.forEach((p, i) => {
                const built = buildOrganNode(ctx, p, halfLen, halfThick, `${partName}-${i}`);
                organGroup.appendChild(built.group);
                organs.push(built);
            });
            layers.organs = organGroup;
        }
    }

    layers.coat = buildCoatLayer(ctx, partName, halfLen, halfThick, opts.coat || {});

    // Порядок слоёв — ЯВНЫЙ (ANAT_LAYER_ORDER), а не "как получилось".
    ANAT_LAYER_ORDER.forEach(name => {
        if (layers[name]) axisGroup.appendChild(layers[name]);
    });

    // Блеск/матовость — последними и УЖЕ ВНЕ поворота оси тела: свет падает
    // на персонажа снаружи, он не поворачивается вместе с сегментом.
    const surface = buildSurfaceLayer(ctx, partName, rx, ry, opts.surface || {});
    if (surface) clipped.appendChild(surface);

    return { group: outer, organs, muscleGroup: layers.muscle || null };
}

// ============================================================================
//                     ПОВОРОТ ГОЛОВЫ (YAW, «ТРИ ЧЕТВЕРТИ»)
// ============================================================================
// Голова была строго анфас, а тело — в профиль. Смешанная проекция — самый
// заметный признак детского рисунка: ровно так дети рисуют человека, лицо
// анфас и ноги вбок (art-direction.md §4.3).
//
// Ключевое решение: это НЕ «перерисованная в три четверти голова», а ОСЬ
// ПОВОРОТА. При yaw = 0 всё встаёт ровно туда, где стояло раньше, а
// значение по умолчанию просто сдвинуто в три четверти. Побочная выгода
// параметрического подхода: голову теперь можно ПОВОРАЧИВАТЬ на ходу —
// проводить взглядом, отворачиваться, коситься.
//
// Модель: череп приближается сферой радиуса rx, и каждая черта лица сидит на
// её поверхности под азимутом phi (0 = точно спереди, плюс — к правому уху
// зрителя). Поворот головы просто прибавляется к азимуту, а экранное
// положение черты — rx*sin(phi + theta). Одна формула даёт сразу всё:
//   • дальний глаз уезжает к краю лица и сплющивается;
//   • ближний глаз выходит к середине;
//   • дальнее ухо прячется за череп (проекция уходит в минус);
//   • ближнее ухо разворачивается к зрителю.
// Горизонтальное сжатие черты — cos(phi + theta): то самое ракурсное
// сокращение, из-за которого дальняя половина лица «уже» ближней.
//
// Азимуты НЕ выдуманы, а посчитаны из нынешних анфасных отступов
// (phi = asin(offset / rx)), поэтому yaw = 0 воспроизводит сегодняшнюю
// голову с точностью до пикселя, и правка безопасна.
const YAW_MAX_DEG = 42;   // сколько градусов даёт yaw = 1

// ---------- ИМЕНОВАННЫЕ ПОЗЫ ГОЛОВЫ ----------
// Ось непрерывная — это механизм. Позы — словарь: код игры говорит
// «смотрит влево», а не «yaw = -0.5». Три значения настраиваются один раз и
// дальше гарантированно хороши, а у любой анимации поворота появляются
// определённые ключи. Левая и правая — честное зеркало друг друга: проверено
// замером, все черты сходятся с точностью 0.00 px (расходятся только
// веснушки и складки, они раскладываются сеянным генератором и на сторонах
// разные — такая асимметрия как раз нужна).
//
// Важно: это НЕ зеркальная копия картинки. У отражённого спрайта вместе с ним
// отразился бы и свет — блик перепрыгнул бы на другую скулу, и персонаж
// выглядел бы освещённым разными лампами в разных позах. Здесь источник
// света остаётся на месте (art-direction.md §3), а шрам не перескакивает с
// щеки на щеку.
const WORM_HEAD_POSES = { left: -0.5, center: 0, right: 0.5 };

// Черты, которые ВЫСТУПАЮТ вперёд (пятачок, морда), при повороте уезжают в
// сторону сильнее, чем лежащие на поверхности: они дальше от оси вращения.
// Это и есть главный признак ракурса — нос уходит с центра лица.
function yawProject(rx, phiDeg, yaw, protrude) {
    const theta = yaw * YAW_MAX_DEG;
    const a = (phiDeg + theta) * Math.PI / 180;
    const reach = rx * (1 + (protrude || 0));
    // Сжатие НОРМИРОВАНО на своё же значение при нулевом повороте.
    //
    // Без нормировки squash = cos(phi) уже при анфасе: у глаза на азимуте
    // 40° это 0.77, у уха на 73° — 0.29. То есть черты оказывались
    // сплющены В САМОМ АНФАСЕ, и обещание «yaw = 0 воспроизводит прежнюю
    // голову» держалось только для позиций, но не для ширин. Замер это и
    // показал: оба уха выходили одинаково узкими даже в центральной позе.
    //
    // Нас интересует не абсолютный ракурс черты, а ИЗМЕНЕНИЕ ракурса от
    // поворота головы. Отсюда деление на cos(phi).
    const base = Math.cos(phiDeg * Math.PI / 180);
    const rel = Math.abs(base) > 1e-3 ? Math.cos(a) / base : Math.cos(a);
    return {
        x: reach * Math.sin(a),
        // Верхний предел: ближняя черта при повороте к зрителю честно
        // становится шире, но раздувать её сверх меры незачем.
        squash: Math.min(1.08, rel),
        front: rel > 0.08
    };
}

// Азимут черты, стоящей при анфасе на расстоянии offset от центра лица.
function yawAzimuth(offset, rx) {
    return Math.asin(Math.max(-1, Math.min(1, offset / rx))) * 180 / Math.PI;
}

// ---------- ПОСАДКА УШЕЙ ----------
// Высота корня уха (доля ry, вверх — отрицательно).
const EAR_Y_RATIO = 0.66;
// Насколько сильно ухо может сократиться в ширину, встав к зрителю ребром.
const EAR_SQUASH_MIN = 0.42;
// Насколько распрямляется разворот уха наружу, когда оно встаёт ребром.
// Узкое ухо под тем же углом 30° читается лезвием, воткнутым сбоку в голову:
// оно топорщится в сторону ровно тогда, когда меньше всего похоже на ухо.
// Повёрнутое ухо должно уходить ЗА голову, а не отставать от неё, — уши и
// рисуются первыми, до черепа, так что подобранное ухо честно им закрывается.
const EAR_EDGE_STRAIGHTEN = 0.55;

// Полуширина черепа на заданной высоте (yNorm — доля ry).
//
// Понадобилась ушам, и вот почему. Корень уха считался проекцией точки на
// ЭКВАТОРИАЛЬНОМ круге радиуса rx, хотя ухо сидит на макушке, где череп вдвое
// уже своей самой широкой части (browWidth 0.42 против cheekWidth 0.97).
// Круга такого радиуса на этой высоте головы просто нет. Пока ухо было
// широким, разрыв закрывало его мясистое основание; при повороте якорь ехал
// НАРУЖУ (35.7 → 40), контур черепа на той же высоте — ВНУТРЬ (26.9 → 23.4),
// а ухо в этот момент сжималось до 40% ширины и перекрывать разрыв ему было
// уже нечем. Отсюда и «ухо отрывается от головы, когда становится узким».
function skullHalfAtY(rx, p, yNorm) {
    // Верхняя дуга контура из skullPathData: (0,-1) → свод → виски → скулы.
    const xs = [0, (p.browWidth != null ? p.browWidth : 0.62),
        (p.templeWidth != null ? p.templeWidth : 0.97),
        (p.cheekWidth != null ? p.cheekWidth : 1)];
    const ys = [-1, -0.99, -0.72, -0.08];
    const bez = (a, t) => {
        const u = 1 - t;
        return u * u * u * a[0] + 3 * u * u * t * a[1] + 3 * u * t * t * a[2] + t * t * t * a[3];
    };
    // По y дуга монотонна, поэтому параметр ищется делением пополам: два
    // десятка итераций дешевле и надёжнее, чем решать кубическое уравнение.
    let lo = 0, hi = 1;
    for (let i = 0; i < 24; i++) {
        const m = (lo + hi) / 2;
        if (bez(ys, m) < yNorm) lo = m; else hi = m;
    }
    return rx * bez(xs, (lo + hi) / 2);
}

// Где корень уха при данном повороте головы и насколько ухо сплющено.
//
// Одна функция и на сборку, и на живой пересчёт. Это не вкусовщина: тут уже
// один раз разъехались два места, считавшие одно и то же, и калибровка
// размера уха месяц не доезжала до экрана (см. EAR_FORM_SCALE).
function earPlacement(ref, yaw) {
    const proj = yawProject(ref.latR, ref.yawPhi, yaw, 0);
    const squash = Math.max(EAR_SQUASH_MIN, Math.abs(proj.squash));
    // Череп при повороте несимметричен (см. skullPathData): свод со стороны
    // лица оптически уже, затылочный — полнее. Корень обязан ехать по ТОМУ
    // контуру, который реально нарисован, иначе ухо повисает рядом с головой.
    const t = Math.abs(yaw || 0);
    const faceSide = (yaw || 0) >= 0 ? 1 : -1;
    const widen = ref.mirror === faceSide ? (1 - 0.13 * t) : (1 + 0.11 * t);
    // Вылет корня наружу от контура — это собственная плоть уха, и при
    // развороте она сокращается вместе с ухом. Постоянный вылет как раз и
    // отрывал ухо: ракурс сжимал полотно, а точку крепления — нет.
    return {
        x: proj.x * widen + ref.rootOut * squash,
        squash,
        // 0 — ухо анфас, 1 — стоит ребром.
        edge: clamp01((1 - squash) / (1 - EAR_SQUASH_MIN))
    };
}

// ---------- ЛОКАЛЬНЫЕ ФОРМЫ (до позиционирования) ----------
function earPathData(mirror) {
    // mirror: 1 = правое ухо, -1 = левое. Точка (0,0) — место крепления.
    //
    // Тест «залей силуэт чёрным» показывал кошку: ухо было тонким шипом с
    // узким основанием и острой вершиной вверх. Свинья узнавалась только по
    // пятачку ВНУТРИ контура — то есть опознавательный признак сидел не там,
    // где его читает глаз (art-direction.md §4.1).
    //
    // Разница кошка/свинья в силуэте — это ПРОПОРЦИИ КЛИНА, а не скругления:
    //   • кошка: основание узкое, ухо заметно выше своей ширины, тонкий шип;
    //   • свинья: основание широченное (почти половина ширины черепа), ухо
    //     примерно квадратное в габаритах, это тяжёлый мясистый клин.
    // Плюс кончик: у кошки это остриё в зенит, у свиньи вершина
    // перекатывается и уходит НАРУЖУ, а задняя кромка провисает вниз.
    // Ключ к прочтению — ПРЯМЫЕ РЁБРА И УГОЛ. Выпуклая дуга по задней кромке
    // читается шариком независимо от габаритов; прямая кромка с изломом у
    // основания читается клином. Плюс ухо должно ВЫХОДИТЬ за череп: пока оно
    // сидит внутри купола, наружу торчит только скруглённая макушка и вся
    // работа над формой пропадает.
    const s = mirror;
    return `M ${(-s * 19).toFixed(1)},11 ` +
        // передняя кромка — длинная и почти прямая
        `C ${(-s * 18).toFixed(1)},-3 ${(-s * 12).toFixed(1)},-18 ${(-s * 3).toFixed(1)},-27 ` +
        // короткий перекат через вершину, наружу
        `C ${(s * 4).toFixed(1)},-34 ${(s * 14).toFixed(1)},-36 ${(s * 19).toFixed(1)},-32 ` +
        // задняя кромка — почти прямая, идёт вниз-наружу до излома
        `C ${(s * 23).toFixed(1)},-24 ${(s * 26).toFixed(1)},-13 ${(s * 27).toFixed(1)},-3 ` +
        // излом у основания: угол, а не скругление
        `C ${(s * 27).toFixed(1)},5 ${(s * 20).toFixed(1)},11 ${(s * 12).toFixed(1)},12 ` +
        // широкое мясистое основание
        `C ${(s * 2).toFixed(1)},13 ${(-s * 10).toFixed(1)},13 ${(-s * 19).toFixed(1)},11 Z`;
}

// Раковина — углублённая часть уха: повторяет внешний контур с отступом
// внутрь, за счёт чего у уха появляется толщина, а не плоская заливка.
function earInnerPathData(mirror) {
    const s = mirror;
    return `M ${(-s * 11).toFixed(1)},7 ` +
        `C ${(-s * 10).toFixed(1)},-3 ${(-s * 6).toFixed(1)},-15 ${(s * 1).toFixed(1)},-22 ` +
        `C ${(s * 6).toFixed(1)},-27 ${(s * 13).toFixed(1)},-28 ${(s * 16).toFixed(1)},-25 ` +
        `C ${(s * 19).toFixed(1)},-19 ${(s * 21).toFixed(1)},-10 ${(s * 21).toFixed(1)},-3 ` +
        `C ${(s * 21).toFixed(1)},3 ${(s * 16).toFixed(1)},7 ${(s * 9).toFixed(1)},8 ` +
        `C ${(s * 1).toFixed(1)},9 ${(-s * 5).toFixed(1)},9 ${(-s * 11).toFixed(1)},7 Z`;
}

// Сосудики внутри уха: у свиньи ухо — самая тонкая кожа на всём теле, оно
// реально просвечивает на свет. Дешёвая деталь (3-4 тонких пути), которая
// сразу сообщает "это живая ткань, а не розовый треугольник".
function buildEarVessels(ctx, mirror, side) {
    const anatomy = ctx.anatomy;
    if (!anatomy.enabled) return null;
    const palette = (anatomy.organs && anatomy.organs.palette) || {};
    const vis = clamp01((anatomy.organs && anatomy.organs.visibility != null ? anatomy.organs.visibility : 0.55));
    if (vis <= 0.02) return null;
    const rng = anatRng(anatomy, `ear-${side}`, 'vessel');
    const group = svgEl('g', { class: 'worm-ear-vessels', opacity: (0.5 * vis + 0.15).toFixed(3) });
    const s = mirror;
    const branches = 2 + Math.floor(rng() * 2);
    for (let i = 0; i < branches; i++) {
        const t = (i + 1) / (branches + 1);
        const ex = s * (5 + t * 8 + rng() * 2);
        const ey = -6 - t * 14 - rng() * 3;
        group.appendChild(svgEl('path', {
            d: `M ${(s * 2).toFixed(1)},-2 Q ${(ex * 0.55).toFixed(1)},${(ey * 0.5).toFixed(1)} ${ex.toFixed(1)},${ey.toFixed(1)}`,
            fill: 'none', stroke: palette.vessel || VISCERA[700],
            'stroke-width': (0.9 - i * 0.15).toFixed(2), opacity: 0.55, 'stroke-linecap': 'round'
        }));
    }
    return group;
}

// Пара тонких "лопнувших сосудиков" на белке глаза — усталый/нездоровый вид
// без ресничек и без румян.
function buildEyeVeins(seedKey, rx, ry) {
    const rng = mulberry32(hashStringSeed(seedKey));
    const group = svgEl('g', { class: 'worm-eye-veins' });
    const veinCount = 2 + Math.floor(rng() * 2);
    for (let i = 0; i < veinCount; i++) {
        const angle = rng() * Math.PI * 2;
        const startR = rx * (0.55 + rng() * 0.2);
        const ratio = ry / rx;
        const sx = Math.cos(angle) * startR;
        const sy = Math.sin(angle) * startR * ratio;
        const midAngle = angle + (rng() * 0.6 - 0.3);
        const midR = startR * 0.55;
        const mx = Math.cos(midAngle) * midR;
        const my = Math.sin(midAngle) * midR * ratio;
        const vein = svgEl('path', {
            d: `M ${sx.toFixed(1)},${sy.toFixed(1)} Q ${mx.toFixed(1)},${my.toFixed(1)} 0,0`,
            fill: 'none', stroke: VISCERA[300], 'stroke-width': SW.hairline, opacity: 0.4, 'stroke-linecap': 'round'
        });
        group.appendChild(vein);
    }
    return group;
}

// ---------- ПОСТРОЕНИЕ ОДНОГО СЕГМЕНТА ТЕЛА (не хвост, не голова) ----------
// ctx несёт общий контекст инстанса (defs, кэш градиентов, анатомию) — см.
// buildWormSVGGroup.
function buildSegmentNode(partName, seg, ctx, opts) {
    opts = opts || {};
    const group = svgEl('g', { 'data-part': partName });

    // ---------- СЛОЙ 0: СКЕЛЕТ ----------
    // Скелет буквально не рисуется, но задаёт форму: индивидуальная
    // вариация пропорций конкретного сегмента ("где тело толще, где
    // тоньше"). Держится маленькой — цепочка рассчитана на перекрытие
    // соседей, сильный разброс открыл бы зазоры между звеньями.
    let skelX = 1, skelY = 1;
    const skeleton = ctx.anatomy.enabled ? (ctx.anatomy.skeleton || {}) : null;
    if (skeleton && (skeleton.variation || 0) > 0.001) {
        const rng = anatRng(ctx.anatomy, partName, 'skeleton');
        skelX = 1 + (rng() * 2 - 1) * skeleton.variation;
        skelY = 1 + (rng() * 2 - 1) * skeleton.variation;
    }

    const baseRx = seg.radius * seg.stretchX * seg.scale * skelX;
    const baseRy = seg.radius * seg.stretchY * seg.scale * skelY;

    // Цвет сегмента может быть подмешан к цвету головы (переход червь →
    // свиная голова, см. skin.neckBlend) — сам цвет в модели при этом не
    // меняется, подмешивание делает только рендерер.
    const fillColor = opts.blendFill || seg.fill;

    const gradId = `worm-seg-grad-${ctx.instanceId}-${partName}`;
    const fillUrl = ensureVolumeGradient(ctx.defs, gradId, fillColor, {
        cx: '38%', cy: '30%', r: '80%',
        highlight: 0.22, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.32, shadowTint: GRIME_SHADOW
    });

    // ВАЖНО: у сегмента больше нет собственной обводки. Контур тела теперь
    // единый (см. createHullLayers) — иначе на каждом стыке виден шов, и тело
    // читается стопкой отдельных шаров, а не одним существом.
    const ellipse = svgEl('ellipse', {
        cx: 0, cy: 0,
        rx: baseRx.toFixed(2),
        ry: baseRy.toFixed(2),
        fill: fillUrl,
        stroke: 'none'
    });
    group.appendChild(ellipse);

    // Глянцевый блик — небольшой полупрозрачный эллипс в верхне-левой части
    // сегмента, поверх градиента усиливает объём.
    const shine = svgEl('ellipse', {
        cx: (-baseRx * 0.25).toFixed(2), cy: (-baseRy * 0.4).toFixed(2),
        rx: (baseRx * 0.38).toFixed(2), ry: (baseRy * 0.22).toFixed(2),
        fill: SPEC, opacity: 0.16
    });
    group.appendChild(shine);

    // ---------- СЛОИ 1..5: АНАТОМИЯ ----------
    const anat = buildAnatomyStack(ctx, partName, {
        rx: baseRx, ry: baseRy,
        axis: opts.axis || 'x',
        organZone: opts.organZone,
        muscle: opts.muscle,
        coat: opts.coat || {},
        surface: opts.surface || {}
    });
    if (anat) group.appendChild(anat.group);

    // Якорь под шрамы/эффекты этого сегмента — шрамы монтируются сюда же,
    // как дочерние элементы group, и наследуют её transform.
    const scarLayer = svgEl('g', { 'data-anchor': `${partName}-scars`, class: 'worm-scar-layer' });
    group.appendChild(scarLayer);
    // baseRx/baseRy сохраняются отдельно, чтобы мини-игры могли "живо"
    // (без пересборки SVG) масштабировать конкретный сегмент — например,
    // раздувание живота в Чревоугодии через handle.setLivePose({ bellyScale }).
    return { group, ellipse, shine, scarLayer, baseRx, baseRy, anat, fillColor };
}

// ---------- ПОСТРОЕНИЕ ХВОСТА (отдельная сущность, каплевидная форма) ----------
// attachRadius — реальный отрисованный радиус ПОСЛЕДНЕГО growing-сегмента
// (предхвостового): основание хвоста считается ДОЛЕЙ от него, а не
// собственным независимым числом — тогда сужение цепочки продолжается
// естественно и на хвост тоже.
function buildTailNode(tail, ctx, attachRadius) {
    const group = svgEl('g', { 'data-part': 'tail' });
    const L = 34 * tail.length; // общая длина хвоста, от основания до кончика
    const Rbase = (attachRadius || 15) * WORM_TAIL_BASE_RATIO * tail.thickness;
    // Кончик — маленький ЗАКРУГЛЁННЫЙ овал, а не точка: у него есть
    // собственный небольшой радиус, форма читается как капля/яйцо, не шип.
    const Rtip = Rbase * WORM_TAIL_TIP_RATIO;
    const tipCx = -(L - Rtip);
    const d = `M 0,${(-Rbase).toFixed(1)} ` +
              `A ${Rbase.toFixed(1)},${Rbase.toFixed(1)} 0 0 1 0,${Rbase.toFixed(1)} ` +
              `Q ${(tipCx * 0.55).toFixed(1)},${(Rbase * 0.9).toFixed(1)} ${tipCx.toFixed(1)},${Rtip.toFixed(1)} ` +
              `A ${Rtip.toFixed(1)},${Rtip.toFixed(1)} 0 0 1 ${tipCx.toFixed(1)},${(-Rtip).toFixed(1)} ` +
              `Q ${(tipCx * 0.55).toFixed(1)},${(-Rbase * 0.9).toFixed(1)} 0,${(-Rbase).toFixed(1)} Z`;

    const gradId = `worm-tail-grad-${ctx.instanceId}`;
    const fillUrl = ensureVolumeGradient(ctx.defs, gradId, tail.fill, {
        cx: '62%', cy: '35%', r: '85%',
        highlight: 0.2, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.32, shadowTint: GRIME_SHADOW
    });
    const path = svgEl('path', { d, fill: fillUrl, stroke: tail.stroke, 'stroke-width': SW.contour });

    // Внутренняя группа для "живого" изгиба хвоста — вращается вокруг точки
    // крепления (0,0), не требует пересборки SVG, обновляется напрямую через
    // handle.setLivePose({ tailBendAngle }).
    const bendGroup = svgEl('g', { 'data-part': 'tail-bend' });
    bendGroup.appendChild(path);

    // Анатомия хвоста обрезается по ЕГО СОБСТВЕННОЙ форме (тот же путь), а
    // не по эллипсу — иначе слои торчали бы за пределы каплевидного силуэта.
    // Центр анатомии смещён к середине хвоста, длина — половина хвоста.
    const anat = buildAnatomyStack(ctx, 'tail', {
        rx: L * 0.5, ry: Rbase * 0.92,
        axis: 'x',
        organZone: 'tail',
        clipPathData: d,
        coat: { rings: true }
    });
    if (anat) {
        anat.group.setAttribute('transform', `translate(${(-L * 0.5).toFixed(1)},0)`);
        bendGroup.appendChild(anat.group);
    }

    group.appendChild(bendGroup);
    const scarLayer = svgEl('g', { 'data-anchor': 'tail-scars', class: 'worm-scar-layer' });
    group.appendChild(scarLayer);
    return { group, path, bendGroup, scarLayer, baseRadius: Rbase, anat };
}

// ---------- ПОСТРОЕНИЕ ОДНОГО ГЛАЗА (склера, радужка, зрачок, веко-шторка) ----------
function buildEyeNode(eye, mirror, instanceId, eyeKey, defs, yawCtx) {
    // Возвращает, помимо узлов, всё нужное для ЖИВОГО пересчёта поворота.
    // yawCtx: { yaw, headRx } — при yaw = 0 всё сходится к прежнему x.
    const yaw = yawCtx ? yawCtx.yaw : 0;
    // ВАЖНО: радиус берётся не полный, а поверхности черепа НА ВЫСОТЕ ГЛАЗ —
    // там голова уже, чем в самом широком месте. С полным радиусом дальний
    // глаз при повороте вылезал за контур лица.
    const headRx = yawCtx ? yawCtx.headRx : (eye.offsetX / 0.55);
    const phi = yawAzimuth(eye.offsetX * mirror, headRx);
    const proj = yawProject(headRx, phi, yaw, 0);
    const y = eye.offsetY;
    // Ракурсное сокращение: дальний глаз сплющивается по горизонтали.
    // Ограничено снизу — полностью схлопнутый глаз читается дефектом,
    // а не поворотом.
    // Нижний предел сжатия. 0.42 давал дальний глаз-щёлочку, которая
    // читалась дефектом отрисовки, а не ракурсом: у стилизованного персонажа
    // глаз обязан остаться глазом. Ракурс здесь уступает читаемости.
    const yawSquash = Math.max(0.58, Math.abs(proj.squash));

    // Сжатие НЕ запекается в rx: иначе при живом повороте пришлось бы
    // пересобирать всю внутреннюю геометрию глаза (склера, радужка, веко,
    // clipPath) каждый кадр. Оно живёт в scale() группы — там его можно
    // переставить одним атрибутом.
    const rx = 8 * eye.stretchX * eye.scale;
    const ry = 8 * eye.stretchY * eye.scale;
    // Страховка: даже на правильной поверхности глаз со своей шириной может
    // задеть контур. Держим его целиком внутри лица — наполовину срезанный
    // глаз читается браком отрисовки, а не ракурсом.
    const xLimit = (yawCtx && yawCtx.maxAbsX != null) ? Math.max(0, yawCtx.maxAbsX - rx * yawSquash * 1.12) : Infinity;
    const x = Math.sign(proj.x) * Math.min(Math.abs(proj.x), xLimit);

    const group = svgEl('g', {
        'data-part': `eye-${eyeKey}`,
        transform: `translate(${x.toFixed(2)},${y}) scale(${yawSquash.toFixed(3)},1)`,
        visibility: eye.visible ? 'visible' : 'hidden'
    });

    // Глазница — тень вокруг глаза, "усаживает" его в морду и вместе с
    // веком-шторкой ниже создаёт усталый, нездоровый взгляд.
    const socket = svgEl('ellipse', {
        cx: 0, cy: (-ry * 0.1).toFixed(2),
        rx: (rx * 1.45).toFixed(2), ry: (ry * 1.4).toFixed(2),
        fill: withAlpha(INK, 0.13)
    });
    // Тень от нависающего верхнего века: без неё глаз выглядит наклеенным
    // кружком, а не сидящим в глазнице.
    const browShadow = svgEl('ellipse', {
        cx: 0, cy: (-ry * 0.72).toFixed(2),
        rx: (rx * 1.2).toFixed(2), ry: (ry * 0.6).toFixed(2),
        fill: withAlpha(FLESH[900], 0.22)
    });

    const scleraGradId = `worm-eye-sclera-${instanceId}-${eyeKey}`;
    const scleraFill = ensureVolumeGradient(defs, scleraGradId, SCLERA, { cx: '40%', cy: '35%', r: '75%', highlight: 0.05, shadow: -0.1 });
    const sclera = svgEl('ellipse', {
        cx: 0, cy: 0, rx: rx.toFixed(2), ry: ry.toFixed(2),
        fill: scleraFill, stroke: withAlpha(INK, 0.2), 'stroke-width': SW.hairline
    });

    // Лопнувшие сосудики вместо ресничек/румян — не милота, а нездоровый вид.
    const veins = buildEyeVeins(`${instanceId}-${eyeKey}`, rx, ry);

    const irisR = rx * 0.6;
    const irisGradId = `worm-eye-iris-${instanceId}-${eyeKey}`;
    const irisFill = ensureVolumeGradient(defs, irisGradId, eye.color, { cx: '40%', cy: '35%', r: '80%', highlight: 0.4, shadow: -0.35 });
    const iris = svgEl('circle', { cx: 0, cy: 0, r: irisR.toFixed(2), fill: irisFill });
    // Лимб — тёмное кольцо по краю радужки. Дешёвая деталь, но именно она
    // отличает живой глаз от плоского кружка: без неё радужка сливается со
    // склерой и взгляд выглядит нарисованным.
    const limbus = svgEl('circle', {
        cx: 0, cy: 0, r: (irisR * 0.94).toFixed(2), fill: 'none',
        stroke: mixColor(eye.color, INK, 0.55), 'stroke-width': (irisR * 0.22).toFixed(2), opacity: 0.55
    });
    const pupil = svgEl('circle', { cx: 0, cy: 0, r: (irisR * 0.62).toFixed(2), fill: INK });

    // Один скромный блик (не два "искрящихся", как у милого зверька).
    const highlight = svgEl('ellipse', {
        cx: (-irisR * 0.3).toFixed(2), cy: (-irisR * 0.32).toFixed(2),
        rx: (irisR * 0.22).toFixed(2), ry: (irisR * 0.16).toFixed(2),
        fill: SPEC, opacity: 0.5
    });

    // ---------- БРОВЬ ----------
    // Была дугой равномерной толщины (stroke-width 3.2, круглые колпачки,
    // чистый INK) — то есть жирным чёрным мазком одинаковой ширины по всей
    // длине. Такая линия не бывает у нарисованного от руки персонажа: у
    // живого штриха толщина МЕНЯЕТСЯ по длине, и именно это отличает
    // рисунок от клипарта. Плюс чистый INK делал бровь такой же тёмной, как
    // внешний контур, и она спорила с силуэтом за внимание.
    //
    // Теперь бровь — не обводка, а ЗАЛИТАЯ ФОРМА с сужением: толстая у носа,
    // сходящая в остриё к виску (так растёт настоящая бровь). Цвет —
    // осветлённый контурный тон, на ступень светлее силуэта.
    const browGroup = svgEl('g', {
        'data-part': `brow-${eyeKey}`,
        transform: `translate(0,${(-ry - 7).toFixed(2)}) rotate(${eye.brow.angle * mirror})`,
        visibility: eye.brow.visible ? 'visible' : 'hidden'
    });
    // s = 1 указывает НАРУЖУ (к виску), -s — к носу.
    const s = mirror;
    const bIn = -s * rx * 1.12;   // конец у носа — толстый
    const bOut = s * rx * 1.02;   // конец у виска — остриё
    const bArc = -rx * 0.5;       // высота подъёма дуги
    const bT = 3.6;               // толщина у носового конца
    // Верхняя кромка брови как квадратичная кривая — её же потом
    // используем, чтобы САЖАТЬ щетинки точно на край, а не рядом.
    const bp0 = { x: bIn, y: 2.0 - bT * 0.5 };
    const bc  = { x: 0,   y: bArc - bT * 0.35 };
    const bp1 = { x: bOut, y: 1.0 };
    const browTop = (t) => {
        const u = 1 - t;
        return { x: u * u * bp0.x + 2 * u * t * bc.x + t * t * bp1.x,
                 y: u * u * bp0.y + 2 * u * t * bc.y + t * t * bp1.y };
    };
    // Касательная к той же кривой — нужна, чтобы волосок торчал ПОПЕРЁК
    // кромки, а не в случайную сторону.
    const browTangent = (t) => {
        const u = 1 - t;
        return { x: 2 * u * (bc.x - bp0.x) + 2 * t * (bp1.x - bc.x),
                 y: 2 * u * (bc.y - bp0.y) + 2 * t * (bp1.y - bc.y) };
    };
    // Носовой конец не обрублен вертикально: срез скруглён небольшой дугой,
    // выпуклой наружу. Прямой срез читается обрезком ленты, а не волосом.
    const capBulge = -s * bT * 0.55;
    const browShape = svgEl('path', {
        d: `M ${bp0.x.toFixed(2)},${bp0.y.toFixed(2)} ` +
           `Q ${bc.x.toFixed(2)},${bc.y.toFixed(2)} ${bp1.x.toFixed(2)},${bp1.y.toFixed(2)} ` +
           `Q 0,${(bArc + bT * 0.6).toFixed(2)} ${bIn.toFixed(2)},${(2.0 + bT * 0.5).toFixed(2)} ` +
           `Q ${(bIn + capBulge).toFixed(2)},${(2.0).toFixed(2)} ${bp0.x.toFixed(2)},${bp0.y.toFixed(2)} Z`,
        fill: inkSoftColor()
    });
    browGroup.appendChild(browShape);
    // Отдельные жёсткие волоски. Они РАСТУТ ИЗ кромки брови: точка посадки
    // берётся с самой кривой, направление — по нормали к ней, поэтому
    // волосок читается продолжением брови, а не царапиной рядом с ней.
    // Работают на образ: редкая грубая щетина неприятна сама по себе —
    // мерзость в детали при сохранённом милом силуэте (art-direction.md §1.3).
    const browRng = mulberry32(hashStringSeed(`brow-${instanceId}-${eyeKey}`));
    for (let i = 0; i < 3; i++) {
        const t = 0.2 + i * 0.28 + (browRng() - 0.5) * 0.12;
        const pt = browTop(t);
        const tg = browTangent(t);
        const len = Math.hypot(tg.x, tg.y) || 1;
        // Нормаль, развёрнутая вверх (от тела брови наружу).
        let nx = tg.y / len, ny = -tg.x / len;
        if (ny > 0) { nx = -nx; ny = -ny; }
        const hair = 2.4 + browRng() * 2.6;
        // Лёгкий завал вдоль кромки, чтобы волоски не стояли частоколом.
        const skew = (browRng() - 0.5) * 0.5;
        browGroup.appendChild(svgEl('path', {
            d: `M ${pt.x.toFixed(2)},${(pt.y + 0.3).toFixed(2)} ` +
               `l ${((nx + tg.x / len * skew) * hair).toFixed(2)},${((ny + tg.y / len * skew) * hair).toFixed(2)}`,
            stroke: inkSoftColor(), 'stroke-width': SW.hairline,
            'stroke-linecap': 'round', fill: 'none'
        }));
    }

    // ---------- ВЕКО КАК ШТОРКА, ЖИВУЩАЯ ВНУТРИ ГЛАЗА ----------
    // Веко — не отдельный "нарост" сверху, а пластина, которая ЕДЕТ
    // (translate по Y) поперёк глаза. Видна только та её часть, что попадает
    // в clipPath по форме глаза.
    const clipId = `worm-eye-clip-${instanceId}-${eyeKey}`;

    const lidHeight = ry * 2 + 6;
    const lidGradId = `worm-eyelid-grad-${instanceId}-${eyeKey}`;
    const lidFill = ensureVolumeGradient(defs, lidGradId, FLESH[300], {
        cx: '50%', cy: '0%', r: '100%',
        highlight: 0.08, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.2, shadowTint: GRIME_SHADOW
    });
    const lidClipGroup = svgEl('g', { 'clip-path': `url(#${clipId})` });
    // lidTrack — единственный узел, который двигаем каждый кадр (translate);
    // сама пластина (lid) и складка (lidCrease) — его неподвижные дети.
    // Стартовое положение шторки задаётся СРАЗУ из модели: раньше оно
    // выставлялось только в tick() и только при opts.blink — на экранах с
    // выключенным морганием персонаж оставался с закрытыми глазами.
    const lidRest = clamp01(eye.eyelid ? eye.eyelid.level : 0);
    const lidTravel = 2 * ry + 5;
    const lidTrack = svgEl('g', {
        'data-part': `eyelid-${eyeKey}`,
        transform: `translate(0,${(-lidTravel * (1 - lidRest)).toFixed(2)})`
    });
    const lid = svgEl('rect', {
        x: (-rx - 3).toFixed(2), y: (-lidHeight / 2).toFixed(2),
        width: (rx * 2 + 6).toFixed(2), height: lidHeight.toFixed(2),
        fill: lidFill
    });
    const lidCrease = svgEl('line', {
        x1: (-rx).toFixed(2), y1: (lidHeight / 2).toFixed(2), x2: rx.toFixed(2), y2: (lidHeight / 2).toFixed(2),
        stroke: withAlpha(FLESH[900], 0.5), 'stroke-width': SW.detail
    });
    lidTrack.appendChild(lid);
    lidTrack.appendChild(lidCrease);
    lidClipGroup.appendChild(lidTrack);

    // ---------- НИЖНЕЕ ВЕКО: УЛЫБАЮЩИЙСЯ ГЛАЗ ----------
    // Вторая шторка, едущая СНИЗУ ВВЕРХ, с выгнутым вверх краем.
    //
    // Зачем отдельная деталь, если верхнее веко уже умеет прищуриваться:
    // прищур сверху и прищур снизу читаются по-разному. Опущенное верхнее
    // веко — это дрёма, усталость, самодовольство. Живую же улыбку поджимает
    // ПОДНЯВШАЯСЯ ЩЕКА, то есть нижний край, и глаз становится дугой,
    // выпуклой вверх. Без этой детали радостный прищур неизбежно выглядел
    // сонным, сколько его ни настраивай, — упирались в это дважды.
    //
    // Живёт в том же клипе по форме глаза, что и верхнее веко, поэтому
    // ничего не торчит за пределы глазного яблока.
    const smileArc = ry * 0.85;          // насколько край выгнут вверх
    const smileTravel = 2 * ry + 6;
    const smileTrack = svgEl('g', {
        'data-part': `eyesmile-${eyeKey}`,
        transform: `translate(0,${smileTravel.toFixed(2)})`   // 0 = убрано вниз
    });
    smileTrack.appendChild(svgEl('path', {
        d: `M ${(-rx - 3).toFixed(2)},0 ` +
           `Q 0,${(-smileArc).toFixed(2)} ${(rx + 3).toFixed(2)},0 ` +
           `L ${(rx + 3).toFixed(2)},${lidHeight.toFixed(2)} ` +
           `L ${(-rx - 3).toFixed(2)},${lidHeight.toFixed(2)} Z`,
        fill: lidFill
    }));
    // Складка по краю: без неё поднятая щека сливается со склерой и глаз
    // выглядит просто наполовину стёртым.
    smileTrack.appendChild(svgEl('path', {
        d: `M ${(-rx - 3).toFixed(2)},0 Q 0,${(-smileArc).toFixed(2)} ${(rx + 3).toFixed(2)},0`,
        fill: 'none', stroke: withAlpha(FLESH[900], 0.45), 'stroke-width': SW.detail
    }));
    lidClipGroup.appendChild(smileTrack);

    // Короткие редкие ресницы по верхнему веку — свиные, не кукольные.
    //
    // Длина считается ОТ РАЗМЕРА ГЛАЗА, а не абсолютным числом, и это не
    // придирка. Стояло 1.8–2.8 единицы, подобранных при глазе scale 0.95;
    // потом глаз уменьшили до 0.68 («мелкие глаза — признак свиньи, а не
    // собаки»), а ресницы остались прежними и стали занимать почти половину
    // его высоты. На морде это читалось не ресницами, а тёмными штрихами
    // поперёк глаза — то самое «полоски какие-то непонятные».
    //
    // Мораль общая: у детали, посаженной на часть тела, размер обязан быть
    // долей от этой части. Иначе первая же правка пропорций её ломает, причём
    // молча.
    const lashes = svgEl('g', { class: 'worm-eye-lashes' });
    for (let i = 0; i < 4; i++) {
        const t = i / 3;
        const lx = (-0.85 + t * 1.7) * rx;
        const ly = -Math.sqrt(Math.max(0, 1 - (lx / rx) * (lx / rx))) * ry;
        const len = ry * (0.3 + 0.1 * (i % 2));
        lashes.appendChild(svgEl('path', {
            d: `M ${lx.toFixed(1)},${ly.toFixed(1)} l ${(lx * 0.12).toFixed(1)},${(-len).toFixed(2)}`,
            stroke: FLESH[900], 'stroke-width': SW.hairline, fill: 'none', opacity: 0.45, 'stroke-linecap': 'round'
        }));
    }

    // Складка верхнего века и морщинки у внешнего уголка — то, что делает
    // глаз посаженным в живую морду, а не приклеенным поверх неё.
    const eyeFolds = svgEl('g', { class: 'worm-eye-folds' });
    eyeFolds.appendChild(svgEl('path', {
        d: `M ${(-rx * 1.15).toFixed(1)},${(-ry * 0.85).toFixed(1)} ` +
           `Q 0,${(-ry * 1.7).toFixed(1)} ${(rx * 1.15).toFixed(1)},${(-ry * 0.85).toFixed(1)}`,
        fill: 'none', stroke: withAlpha(FLESH[700], 0.4), 'stroke-width': SW.detail, 'stroke-linecap': 'round'
    }));
    for (let i = 0; i < 2; i++) {
        const sx = mirror * rx * (1.15 + i * 0.16);
        eyeFolds.appendChild(svgEl('path', {
            d: `M ${sx.toFixed(1)},${(ry * (0.1 + i * 0.28)).toFixed(1)} l ${(mirror * 3.2).toFixed(1)},${(1.6 + i * 1.4).toFixed(1)}`,
            fill: 'none', stroke: withAlpha(FLESH[700], 0.3), 'stroke-width': SW.hairline, 'stroke-linecap': 'round'
        }));
    }

    // Радужка, лимб, зрачок и блик — в одной группе: взгляд двигается
    // переносом ЭТОЙ группы, а не четырёх элементов по отдельности (и не
    // ценой пересборки SVG).
    // Клип по форме глаза заводим ДО первого использования: по нему
    // обрезаются и веко-шторка, и тень от верхнего века.
    const clipPath = svgEl('clipPath', { id: clipId });
    clipPath.appendChild(svgEl('ellipse', { cx: 0, cy: 0, rx: rx.toFixed(2), ry: ry.toFixed(2) }));
    group.appendChild(clipPath);

    const gazeGroup = svgEl('g', { 'data-part': `gaze-${eyeKey}` });
    gazeGroup.appendChild(iris);
    gazeGroup.appendChild(limbus);
    gazeGroup.appendChild(pupil);
    gazeGroup.appendChild(highlight);

    group.appendChild(socket);
    group.appendChild(browShadow);
    group.appendChild(sclera);
    group.appendChild(veins);
    group.appendChild(gazeGroup);
    group.appendChild(svgEl('ellipse', {
        cx: 0, cy: (-ry * 1.05).toFixed(2), rx: (rx * 1.05).toFixed(2), ry: (ry * 0.75).toFixed(2),
        fill: withAlpha(INK, 0.3), 'clip-path': `url(#worm-eye-clip-${instanceId}-${eyeKey})`
    }));
    group.appendChild(lidClipGroup);
    group.appendChild(lashes);
    group.appendChild(eyeFolds);
    group.appendChild(browGroup);

    // phi/offsetY/xLimitBase нужны, чтобы пересчитать посадку глаза при
    // ЖИВОМ повороте головы, не пересобирая его внутренности.
    return { group, sclera, iris, pupil, gazeGroup, lidTrack, smileTrack, smileTravel,
             browGroup, rx, ry, lidHeight,
             yawPhi: phi, offsetY: y, baseRx: rx };
}

// ---------- ПОСТРОЕНИЕ РТА: ЕДИНАЯ ПРОЦЕДУРНАЯ ФОРМА, ЖИВАЯ КАЖДЫЙ КАДР ----------
// Идея формы: круг, где кайма — губы, заливка — тёмная ротовая полость.
// Геометрия пересчитывается КАЖДЫЙ КАДР в tick() из bend/gap — как и
// раздутие живота, это "живой" параметр, управляемый через
// handle.setLivePose({ mouthOpenness }) БЕЗ пересборки всего SVG.
function buildMouthShapes(mouthAnchor, mouth, instanceId) {
    // Половина ширины рта в уголках. Была 8.6 — рот выходил мелким, и на
    // телефоне его кривизна не читалась вовсе: мимика держалась на одних
    // ушах и бровях, а улыбки видно не было. Чем шире рот, тем на большем
    // расстоянии расходятся его уголки при том же изгибе, — то есть ширина
    // и есть главный рычаг «видно эмоцию или нет».
    const W = 15.5;
    const MAX_GAP = 10;  // при полном открытии (gap==W) рот примерно круглый

    // Линия губ чуть толще обычной внутренней границы (structure = 1.7).
    // Это осознанное отступление в пределах иерархии линий: губа — главная
    // внутренняя линия лица, на ней держится всё выражение. Контур силуэта
    // (2.6) она при этом не догоняет — иначе деталь начнёт спорить с
    // силуэтом, а это прямо запрещено (art-direction.md §4).
    const mouthShape = svgEl('path', {
        d: '', fill: VISCERA[700], stroke: mouth.color,
        'stroke-width': (SW.structure * 1.25).toFixed(2),
        'stroke-linejoin': 'round', 'stroke-linecap': 'round'
    });
    mouthAnchor.appendChild(mouthShape);

    const mouthClipId = `worm-mouth-clip-${instanceId}`;
    const mouthClipPath = svgEl('clipPath', { id: mouthClipId });
    const mouthClipShape = svgEl('path', { d: '' });
    mouthClipPath.appendChild(mouthClipShape);
    mouthAnchor.appendChild(mouthClipPath);

    // Кривые, неровные зубы — видны только когда рот заметно приоткрыт.
    const teethGroup = svgEl('g', { class: 'worm-teeth', 'clip-path': `url(#${mouthClipId})`, visibility: 'hidden' });
    const toothRng = mulberry32(hashStringSeed(`${instanceId}-teeth`));
    const teeth = [];
    const toothCount = 3;
    for (let i = 0; i < toothCount; i++) {
        const t = (i + 0.5) / toothCount; // 0..1 слева направо
        const tx = (-W * 0.9) + t * (W * 1.8);
        const jitter = (toothRng() - 0.5) * 2.4;
        const hBase = 4 + toothRng() * 2;
        const tw = 2.2 + toothRng() * 1.2;
        const toothEl = svgEl('path', { d: '', fill: BILE[200] });
        teethGroup.appendChild(toothEl);
        teeth.push({ el: toothEl, tx, jitter, hBase, tw });
    }
    mouthAnchor.appendChild(teethGroup);

    // ---------- ЖИДКОСТЬ ВО РТУ ----------
    // Часть САМОГО РТА, а не наклейка поверх морды. Пока лужица рисовалась
    // мини-игрой в своём слое, её приходилось заново наводить на рот после
    // каждого переезда камеры, она не размывалась вместе с персонажем и при
    // любом промахе висела на щеке.
    //
    // Обрезка — тем же контуром рта, что и зубы: лужица физически не может
    // вылезти за губы, как бы её ни налили. Пустая — прозрачная и не мешает
    // никому; цвет и уровень задаются живым каналом (mouthFill,
    // mouthFillColor), поэтому годится на любую жидкость в любой мини-игре.
    const liquid = svgEl('path', {
        class: 'worm-mouth-liquid', d: '', fill: 'none',
        'clip-path': `url(#${mouthClipId})`, opacity: 0
    });
    mouthAnchor.appendChild(liquid);

    return { mouthShape, mouthClipShape, teethGroup, teeth, liquid, W, MAX_GAP };
}

// Пересчитывает форму рта (и зубов) из bend/gap.
//
// ---------- ПОЧЕМУ НЕ ОВАЛ ----------
// Раньше рот был овалом с разными радиусами сверху и снизу: при улыбке
// верхний радиус обнулялся, и ВЕРХНЯЯ ГУБА ПРЕВРАЩАЛАСЬ В ПРЯМУЮ ЛИНИЮ.
// Гнулась только нижняя кромка, а сверху рот оставался обрубленным по
// горизонтали. Именно поэтому улыбка читалась «чем-то средним»: половина
// рта в ней не участвовала.
//
// Теперь рот строится вокруг ИЗОГНУТОЙ СРЕДНЕЙ ЛИНИИ. Обе губы — это одна и
// та же дуга, разведённая вверх и вниз на величину открытия, поэтому гнутся
// они одинаково и всегда согласованно. Уголки при этом общие для обеих губ:
// рот раскрывается в середине, а его углы остаются сколотыми — как у
// настоящего рта.
//
// Закрытый рот (gap = 0) даёт нулевую площадь, и от него остаётся ровно
// обводка — изогнутая линия губ. Отдельной ветки «нарисовать линию вместо
// фигуры» не нужно.
function mouthBendFromCurve(curve) {
    return 7 * curve;
}

// Сагитта квадратичной кривой равна половине смещения контрольной точки,
// поэтому всюду ниже смещения удваиваются.
// Уровень жидкости во рту. Считается ПО ТОЙ ЖЕ полости, что нарисована:
// заливка идёт снизу вверх от нижней губы, а лишнее срезает обрезка ртом.
function updateMouthLiquid(mouthBuilt, fill, color, top, bottom) {
    const el = mouthBuilt.liquid;
    if (!el) return;
    const k = Math.max(0, Math.min(1, fill || 0));
    if (k <= 0.001 || bottom - top <= 0.5) {
        el.setAttribute('opacity', '0');
        el.setAttribute('d', '');
        return;
    }
    const W = mouthBuilt.W + 4;
    const y = bottom - k * (bottom - top);
    el.setAttribute('fill', color || '#ffffff');
    el.setAttribute('opacity', '1');
    el.setAttribute('d', `M ${-W},${y.toFixed(2)} L ${W},${y.toFixed(2)} ` +
                         `L ${W},${(bottom + 4).toFixed(2)} ` +
                         `L ${-W},${(bottom + 4).toFixed(2)} Z`);
}

function updateMouthGeometry(mouthBuilt, bend, gap, fill, color) {
    const W = mouthBuilt.W;

    // Дуга симметрична относительно точки крепления: уголки уходят вверх,
    // середина вниз. Так улыбка не «съезжает» с лица вниз по мере усиления,
    // а раскрывается вокруг своего места.
    const cornerY = -bend * 0.45;
    const midY = bend * 0.55;
    const ctrlY = 2 * midY - cornerY;      // контрольная точка средней линии

    const gapTop = gap * MOUTH_EGG_TOP;
    const gapBottom = gap * MOUTH_EGG_BOTTOM;

    const d = `M ${(-W).toFixed(2)},${cornerY.toFixed(2)} ` +
        `Q 0,${(ctrlY - 2 * gapTop).toFixed(2)} ${W.toFixed(2)},${cornerY.toFixed(2)} ` +
        `Q 0,${(ctrlY + 2 * gapBottom).toFixed(2)} ${(-W).toFixed(2)},${cornerY.toFixed(2)} Z`;
    mouthBuilt.mouthShape.setAttribute('d', d);
    mouthBuilt.mouthClipShape.setAttribute('d', d);

    // Крайние точки полости: у квадратичной кривой это её середина, то есть
    // ровно midY ∓ зазор. Отсюда и берётся, докуда наливать.
    updateMouthLiquid(mouthBuilt, fill, color, midY - gapTop, midY + gapBottom);

    if (gap > 2) {
        mouthBuilt.teethGroup.setAttribute('visibility', 'visible');
        // Зубы растут от ВЕРХНЕЙ ГУБЫ, а она теперь изогнута — значит и
        // посадка каждого зуба считается по кривой, а не по одной высоте на
        // всех. Иначе крайние зубы висят в воздухе, а средние тонут в губе.
        mouthBuilt.teeth.forEach(t => {
            const u = Math.max(-1, Math.min(1, t.tx / W));
            const s = (u + 1) / 2;                       // 0..1 вдоль рта
            const lipY = (1 - s) * (1 - s) * cornerY +
                         2 * (1 - s) * s * (ctrlY - 2 * gapTop) +
                         s * s * cornerY;
            const toothH = Math.min(gap * 0.85, t.hBase);
            const topY = lipY + 1;
            t.el.setAttribute('d',
                `M ${(t.tx - t.tw / 2).toFixed(1)},${topY.toFixed(1)} ` +
                `L ${(t.tx + t.tw / 2 + t.jitter).toFixed(1)},${topY.toFixed(1)} ` +
                `L ${(t.tx + t.jitter * 0.4).toFixed(1)},${(topY + toothH).toFixed(1)} Z`);
        });
    } else {
        mouthBuilt.teethGroup.setAttribute('visibility', 'hidden');
    }
}

// ---------- ПЕРЕХОД ЧЕРВЬ → СВИНАЯ ГОЛОВА ----------
// Задача: чтобы не читалось как "два разных персонажа, состыкованных
// встык". Переход собран из четырёх согласованных вещей:
//   1) цвет: сегмент-1 и сегмент-2 подмешаны к цвету головы (skin.neckBlend)
//      — кожа плавно "розовеет" к голове, а не меняется скачком;
//   2) низ головы: градиентная юбка цветом шеи — граница черепа и тела
//      растворяется, голова выглядит выросшей из тела;
//   3) свиные признаки убывают вниз по телу: складки и щетина есть на
//      голове и сегменте-1, слабее на сегменте-2, дальше их нет;
//   4) червячные признаки убывают вверх: кольцевые бороздки идут по всему
//      телу, у шеи слабеют, а поясок-клителлум на сегменте-2 работает
//      "воротником" — естественной границей между двумя типами кожи.
// Пятачок при этом читается как передний конец ЧЕРВЯ (радиальные морщинки
// вокруг него — как у ротового конца), а не как приклеенная деталь свиньи.
function buildHeadNeckTransition(ctx, headRx, headRy, neckColor) {
    const anatomy = ctx.anatomy;
    if (!anatomy.enabled) return null;
    // Клип по силуэту черепа. Без него "юбка" перехода выступает ниже
    // головы и увеличивает её bbox — а на bbox головы завязана раскладка
    // Чревоугодия (кастрюля ставится строго над макушкой). Косметика не
    // имеет права менять измеримые габариты частей: это ровно тот класс
    // поломок, которые проявляются не тут, а в чужой мини-игре.
    const clipId = `worm-neck-clip-${ctx.instanceId}`;
    if (!ctx.gradCache[clipId]) {
        const clip = svgEl('clipPath', { id: clipId });
        clip.appendChild(svgEl('ellipse', { cx: 0, cy: 0, rx: headRx.toFixed(2), ry: headRy.toFixed(2) }));
        ctx.defs.appendChild(clip);
        ctx.gradCache[clipId] = true;
    }
    const group = svgEl('g', { class: 'worm-neck-blend', 'clip-path': `url(#${clipId})` });
    const gid = `worm-neck-grad-${ctx.instanceId}`;
    if (!ctx.gradCache[gid]) {
        const grad = svgEl('linearGradient', { id: gid, x1: '0', y1: '0', x2: '0', y2: '1' });
        grad.appendChild(svgEl('stop', { offset: '0%', 'stop-color': neckColor, 'stop-opacity': '0' }));
        grad.appendChild(svgEl('stop', { offset: '55%', 'stop-color': neckColor, 'stop-opacity': '0.35' }));
        grad.appendChild(svgEl('stop', { offset: '100%', 'stop-color': neckColor, 'stop-opacity': '0.8' }));
        ctx.defs.appendChild(grad);
        ctx.gradCache[gid] = true;
    }
    // Габариты юбки заведомо внутри черепа (низ на 0.93*ry): clip-path
    // Chromium'ом в getBoundingClientRect() НЕ учитывается, поэтому одного
    // клипа мало — геометрия тоже должна помещаться внутрь головы, иначе
    // измеренный bbox головы вырастет, даже если визуально всё обрезано.
    group.appendChild(svgEl('ellipse', {
        cx: 0, cy: (headRy * 0.48).toFixed(1),
        rx: (headRx * 0.86).toFixed(1), ry: (headRy * 0.45).toFixed(1),
        fill: `url(#${gid})`
    }));
    return group;
}

// ---------- ДЕТАЛИЗАЦИЯ МОРДЫ ----------
// Складки лба, вибриссы, тень у основания ушей. Всё внутри клипа по черепу:
// ни одна деталь не имеет права выйти за габарит головы, потому что по её
// bbox Чревоугодие ставит кастрюлю над макушкой.
function buildHeadDetailLayer(ctx, rx, ry, skullPathD) {
    const anatomy = ctx.anatomy;
    if (!anatomy.enabled) return null;
    const coat = anatomy.coat || {};
    const folds = coat.folds != null ? coat.folds : 0.5;
    const bristle = coat.bristle != null ? coat.bristle : 0.45;
    const rng = anatRng(anatomy, 'head', 'detail');

    const clipId = `worm-head-detail-clip-${ctx.instanceId}`;
    if (!ctx.gradCache[clipId]) {
        const clip = svgEl('clipPath', { id: clipId });
        // Клип по РЕАЛЬНОМУ силуэту черепа, а не по вписанному эллипсу:
        // иначе складки и щетина обрезались бы по чужой форме.
        clip.appendChild(skullPathD ? svgEl('path', { d: skullPathD })
                                    : svgEl('ellipse', { cx: 0, cy: 0, rx: rx.toFixed(2), ry: ry.toFixed(2) }));
        ctx.defs.appendChild(clip);
        ctx.gradCache[clipId] = true;
    }
    const group = svgEl('g', { class: 'worm-head-detail', 'clip-path': `url(#${clipId})` });

    // Тень у основания ушей — уши растут ИЗ головы, а не приставлены к ней.
    const shadeFill = ensureSoftGradient(ctx, `worm-head-earshade-${ctx.instanceId}`, GRIME_SHADOW, 1);
    [-1, 1].forEach(side => {
        group.appendChild(svgEl('ellipse', {
            cx: (side * rx * 0.58).toFixed(1), cy: (-ry * 0.56).toFixed(1),
            rx: (rx * 0.28).toFixed(1), ry: (ry * 0.18).toFixed(1),
            fill: shadeFill, opacity: 0.35
        }));
    });

    // Складки лба — две несимметричные дуги над бровями.
    // Одна пара дуг вместо двух: лоб небольшой, две пары на нём читаются
    // штриховкой, а не складками.
    if (folds > 0.01) {
        for (let i = 0; i < 1; i++) {
            const y = -ry * (0.52 + i * 0.12);
            const w = rx * (0.4 - i * 0.07);
            const shift = (rng() - 0.5) * rx * 0.12;
            group.appendChild(svgEl('path', {
                d: `M ${(-w + shift).toFixed(1)},${y.toFixed(1)} Q ${shift.toFixed(1)},${(y - ry * 0.09).toFixed(1)} ${(w + shift).toFixed(1)},${y.toFixed(1)}`,
                fill: 'none', stroke: GRIME_SHADOW, 'stroke-width': SW.detail,
                opacity: (0.14 * folds).toFixed(3), 'stroke-linecap': 'round'
            }));
            group.appendChild(svgEl('path', {
                d: `M ${(-w + shift).toFixed(1)},${(y + 1.6).toFixed(1)} Q ${shift.toFixed(1)},${(y - ry * 0.09 + 1.6).toFixed(1)} ${(w + shift).toFixed(1)},${(y + 1.6).toFixed(1)}`,
                fill: 'none', stroke: GRIME_HIGHLIGHT, 'stroke-width': SW.hairline,
                opacity: (0.1 * folds).toFixed(3), 'stroke-linecap': 'round'
            }));
        }
    }

    // ---------- ВИБРИССЫ УБРАНЫ НАМЕРЕННО ----------
    // Были четыре длинных волоска по щекам. Убраны по тому же правилу, что и
    // складки: на лице в размер экрана это не волоски, а четыре диагональные
    // царапины. Отличить одно от другого невозможно — значит рисовать нечего.
    // Переменная bristle осталась: щетина по-прежнему идёт по телу.

    return group;
}

// ---------- ПОСТРОЕНИЕ ГОЛОВЫ (уши, пятачок, рот, глаза) ----------
// ---------- ФОРМА ЧЕРЕПА ----------
// Голова перестала быть кругом. У свиньи череп спереди читается так: широкий
// лоб между ушами → самые широкие точки на скулах → сужение к челюсти →
// выступающая вперёд-вниз морда с плоским пятачком на конце. Форма собрана
// кубическими кривыми и симметрична; все пропорции — параметры модели
// (`head.skull`), а не числа в коде, поэтому череп можно менять под возраст,
// породу или настроение, не трогая рендерер.
function skullPathData(rx, ry, p, yaw) {
    const brow = (p.browWidth != null ? p.browWidth : 0.62) * rx;   // ширина свода у макушки
    const temple = (p.templeWidth != null ? p.templeWidth : 0.97) * rx;
    const cheek = (p.cheekWidth != null ? p.cheekWidth : 1) * rx;   // самое широкое место
    const jaw = (p.jawWidth != null ? p.jawWidth : 0.78) * rx;
    const muzzle = (p.muzzleWidth != null ? p.muzzleWidth : 0.46) * rx;
    const chin = (p.chinDrop != null ? p.chinDrop : 1.04) * ry;

    // ---------- АСИММЕТРИЯ ЧЕРЕПА ПРИ ПОВОРОТЕ ----------
    // Без неё поворот читается наполовину: черты уезжают вбок по СИММЕТРИЧНОЙ
    // маске, и лицо выглядит не повёрнутым, а съехавшим.
    //
    // Что происходит при развороте на реальной голове:
    //   • сторона, КУДА смотрит лицо: свод виден с ребра и оптически уже,
    //     зато на этот край выходит морда — низ становится шире;
    //   • затылочная сторона: наоборот, купол разворачивается к зрителю и
    //     становится полнее, а низ подбирается.
    // Знак yaw соответствует стороне, куда уезжает пятачок (см. yawProject).
    const yw = yaw || 0;
    const faceSide = yw >= 0 ? 1 : -1;
    const t = Math.abs(yw);
    const kTopFace = 1 - 0.13 * t, kLowFace = 1 + 0.17 * t;
    const kTopBack = 1 + 0.11 * t, kLowBack = 1 - 0.12 * t;

    const half = (side) => {
        const k = side;
        const isFace = side === faceSide;
        const up = isFace ? kTopFace : kTopBack;   // свод, виски, скулы
        const lo = isFace ? kLowFace : kLowBack;   // челюсть, морда, подбородок
        return `C ${(k * brow * up).toFixed(1)},${(-ry * 0.99).toFixed(1)} ${(k * temple * up).toFixed(1)},${(-ry * 0.72).toFixed(1)} ${(k * cheek * up).toFixed(1)},${(-ry * 0.08).toFixed(1)} ` +
               `C ${(k * cheek * 0.99 * lo).toFixed(1)},${(ry * 0.3).toFixed(1)} ${(k * jaw * lo).toFixed(1)},${(ry * 0.56).toFixed(1)} ${(k * muzzle * lo).toFixed(1)},${(ry * 0.84).toFixed(1)} ` +
               `C ${(k * muzzle * 0.92 * lo).toFixed(1)},${(chin * 0.97).toFixed(1)} ${(k * muzzle * 0.45 * lo).toFixed(1)},${chin.toFixed(1)} 0,${chin.toFixed(1)}`;
    };
    // Вниз по правой стороне, потом обратно вверх по левой.
    return `M 0,${(-ry).toFixed(1)} ${half(1)} ` +
           `${half(-1).replace('C', 'C').split(' ').reverse().length ? '' : ''}` +
           reverseHalf(half(-1)) + ' Z';
}

// Левая половина строится теми же кривыми, но проходится в обратном
// направлении — иначе контур пришлось бы дублировать вручную и он рисковал
// разъехаться при правке пропорций.
function reverseHalf(dRight) {
    // dRight: "C a,b c,d e,f C g,h i,j k,l" — разворачиваем порядок сегментов
    // и меняем местами контрольные точки внутри каждого.
    const segs = dRight.trim().split('C').filter(Boolean).map(seg => {
        const nums = seg.trim().split(/[ ,]+/).map(Number);
        return { c1: [nums[0], nums[1]], c2: [nums[2], nums[3]], p: [nums[4], nums[5]] };
    });
    let d = '';
    for (let i = segs.length - 1; i >= 0; i--) {
        const target = i === 0 ? null : segs[i - 1].p;
        const seg = segs[i];
        const end = target || [0, segs[0].c1[1]];
        d += ` C ${seg.c2[0].toFixed(1)},${seg.c2[1].toFixed(1)} ${seg.c1[0].toFixed(1)},${seg.c1[1].toFixed(1)} ${end[0].toFixed(1)},${end[1].toFixed(1)}`;
    }
    return d;
}

// ---------- ПОСТРОЕНИЕ ГОЛОВЫ (череп, морда, уши, пятачок, рот, глаза) ----------
function buildHeadNode(model, ctx) {
    const head = model.head;
    const anatomy = ctx.anatomy;
    const skullCfg = head.skull || {};
    // Поворот головы. 0 = анфас (прежнее поведение до пикселя),
    // 1 = YAW_MAX_DEG градусов вправо. См. блок «ПОВОРОТ ГОЛОВЫ» выше.
    const headYaw = Math.max(-1, Math.min(1, head.yaw != null ? head.yaw : 0));
    // Насколько пятачок и морда выступают вперёд относительно черепа —
    // объявлено здесь, потому что морда строится раньше пятачка, а обе
    // черты обязаны ехать по одному и тому же выступу.
    const SNOUT_PROTRUDE = 0.34;
    // Группа наклона: весь набор частей головы висит в ней, чтобы мимический
    // наклон (livePose.headTilt) поворачивал голову целиком вокруг основания
    // шеи, а не каждую деталь по отдельности.
    const group = svgEl('g', { 'data-part': 'head' });
    const tiltGroup = svgEl('g', { 'data-part': 'head-tilt' });
    group.appendChild(tiltGroup);

    const R = 40 * head.scale;
    const rx = R * head.stretchX;
    const ry = R * head.stretchY;
    const skullD = skullPathData(rx, ry, skullCfg, headYaw);

    const headGradId = `worm-head-grad-${ctx.instanceId}`;
    const headFill = ensureVolumeGradient(ctx.defs, headGradId, head.fill, {
        cx: '38%', cy: '26%', r: '88%',
        highlight: 0.2, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.34, shadowTint: GRIME_SHADOW
    });
    const skull = svgEl('path', { d: skullD, fill: headFill, stroke: head.stroke, 'stroke-width': SW.contour, 'stroke-linejoin': 'round' });

    // Клип по РЕАЛЬНОЙ форме черепа: все слои кожи, складки и щетина
    // обрезаются силуэтом головы, а не вписанным эллипсом.
    const skullClipId = `worm-skull-clip-${ctx.instanceId}`;
    // Ссылку на путь клипа держим: при живом повороте череп становится
    // асимметричным, и обрезка обязана ехать вместе с ним — иначе слои кожи
    // и рот будут обрезаться по форме, которой на экране уже нет.
    let skullClipShape = null;
    if (!ctx.gradCache[skullClipId]) {
        const clip = svgEl('clipPath', { id: skullClipId });
        skullClipShape = svgEl('path', { d: skullD });
        clip.appendChild(skullClipShape);
        ctx.defs.appendChild(clip);
        ctx.gradCache[skullClipId] = skullClipShape;
    } else if (ctx.gradCache[skullClipId] instanceof Object) {
        skullClipShape = ctx.gradCache[skullClipId];
    }

    const headShine = svgEl('ellipse', {
        cx: (-rx * 0.28).toFixed(2), cy: (-ry * 0.52).toFixed(2),
        rx: (rx * 0.3).toFixed(2), ry: (ry * 0.16).toFixed(2),
        fill: SPEC, opacity: 0.16
    });

    // ---------- УШИ ----------
    // Крепятся к верхним углам черепа и по умолчанию развёрнуты наружу:
    // у свиньи уши стоят домиком, а не торчат строго вверх. Базовый разворот
    // живёт в рендерере, а `ear.rotation` из модели прибавляется к нему —
    // так прижатые уши (отрицательный угол) остаются рабочим состоянием.
    // Наклон посадки. Было 27° — уши вставали торчком в стороны и вместе с
    // узкой треугольной формой давали кошачий силуэт.
    const EAR_BASE_TILT = 30;
    // Отдельная ручка габарита уха: форму задаёт earPathData, размер — здесь.
    //
    // История значения важна, чтобы его случайно не «починили» обратно.
    // Стояло 0.82 — я уменьшил ухо, посчитав, что клин перелетел в летучую
    // мышь. Но это значение НИКОГДА не доезжало до экрана: tick() каждый
    // кадр пересобирал трансформ уха из earRefs, где лежал только
    // ear.scale*stretchX, и калибровка терялась через кадр после сборки.
    // То есть согласованный размер уха — это размер БЕЗ калибровки.
    // Баг с потерей трансформа исправлен, а множитель приведён к тому, что
    // реально было на экране и было одобрено.
    const EAR_FORM_SCALE = 1;
    const earsGroup = svgEl('g', { 'data-part': 'ears' });
    const earRefs = {};
    ['left', 'right'].forEach(side => {
        const mirror = side === 'left' ? -1 : 1;
        const ear = head.ears[side];
        // Ухо сидит НА ЗАТЫЛОЧНОЙ стороне сферы: азимут считается от его
        // анфасного отступа, но с добавкой, отодвигающей ухо назад. Поэтому
        // при повороте дальнее ухо честно уезжает за череп, а ближнее
        // разворачивается к зрителю.
        // Насколько ухо отнесено назад от плоскости лица. Было 22°, что
        // вместе с собственным отступом ставило ухо на азимут ~73° — почти
        // у края сферы, где производная проекции максимальна: ближнее ухо
        // раздувалось, дальнее превращалось в лезвие. 12° делает реакцию
        // на поворот заметной, но не взрывной.
        const EAR_PHI_BACK = 12;
        const earPhi = yawAzimuth(mirror * rx * 0.78, rx) + mirror * EAR_PHI_BACK;
        const anchorY = -ry * EAR_Y_RATIO;
        // Радиус ГОРИЗОНТАЛЬНОГО СЕЧЕНИЯ черепа на высоте уха — по нему и
        // ездит корень при повороте (почему не по rx — см. skullHalfAtY).
        const earLatR = skullHalfAtY(rx, skullCfg, -EAR_Y_RATIO);
        // Вылет корня наружу от этого сечения подобран так, чтобы АНФАС не
        // сдвинулся ни на единицу: раньше якорь считался по rx, и (rx - latR)
        // — ровно та разница. Меняется только поведение при повороте.
        const earRootOut = (rx - earLatR) * Math.sin(earPhi * Math.PI / 180);
        // Ракурс уха: дальнее сплющивается, ближнее — почти нет.
        // Уху, наоборот, сокращаться можно сильно: у него нет внутренней
        // структуры, которую сплющивание сделало бы нечитаемой, а сильный
        // ракурс дальнего уха — самый дешёвый признак повёрнутой головы.
        const earPlace = earPlacement({ latR: earLatR, yawPhi: earPhi, rootOut: earRootOut, mirror }, headYaw);
        const anchorX = earPlace.x;
        const earYawSquash = earPlace.squash;
        const earBaseTilt = mirror * EAR_BASE_TILT;
        const baseAngle = earBaseTilt * (1 - EAR_EDGE_STRAIGHTEN * earPlace.edge) + ear.rotation;
        // Группа уха масштабируется, а значит масштабируется и её обводка.
        // Без компенсации контур уха уехал бы с лестницы толщин (2.6 * 0.82
        // = 2.13) и силуэт получил бы разную толщину линии на разных
        // участках — ровно тот дефект, который чинили в прошлый заход.
        const earSx = ear.scale * ear.stretchX * EAR_FORM_SCALE * earYawSquash;
        const earSy = ear.scale * ear.stretchY * EAR_FORM_SCALE;
        const earStrokeK = 2 / (Math.abs(earSx) + Math.abs(earSy) || 1);
        const earGroup = svgEl('g', {
            'data-part': `ear-${side}`,
            'data-anchor': `ear-${side}`,
            transform: `translate(${anchorX.toFixed(2)},${anchorY.toFixed(2)}) rotate(${baseAngle.toFixed(1)}) scale(${earSx.toFixed(3)},${earSy.toFixed(3)})`,
            visibility: ear.visible ? 'visible' : 'hidden'
        });
        const earGradId = `worm-ear-grad-${ctx.instanceId}-${side}`;
        const earFill = ensureVolumeGradient(ctx.defs, earGradId, ear.fill, {
            cx: mirror > 0 ? '35%' : '65%', cy: '30%', r: '85%',
            highlight: 0.2, highlightTint: GRIME_HIGHLIGHT,
            shadow: -0.32, shadowTint: GRIME_SHADOW
        });
        const earShape = svgEl('path', { d: earPathData(mirror), fill: earFill, stroke: ear.stroke, 'stroke-width': (SW.contour * earStrokeK).toFixed(2), 'stroke-linejoin': 'round' });
        const earInner = svgEl('path', { d: earInnerPathData(mirror), fill: mixColor(ear.fill, GRIME_SHADOW, 0.32), opacity: 0.6 });
        const earRidge = svgEl('path', {
            d: earInnerPathData(mirror), fill: 'none',
            stroke: mixColor(ear.fill, GRIME_HIGHLIGHT, 0.55), 'stroke-width': (SW.detail * earStrokeK).toFixed(2), opacity: 0.45
        });
        earGroup.appendChild(earShape);
        earGroup.appendChild(earInner);
        earGroup.appendChild(earRidge);
        const vessels = buildEarVessels(ctx, mirror, side);
        if (vessels) earGroup.appendChild(vessels);
        // Щетина по краю раковины — у свиньи ухо опушено по контуру.
        if (anatomy.enabled && (anatomy.coat && (anatomy.coat.bristle || 0) > 0.01) && ear.visible) {
            const brng = anatRng(anatomy, `ear-${side}`, 'fringe');
            const fringe = svgEl('g', { class: 'worm-ear-fringe' });
            // Бахрома растёт ВНУТРЬ контура уха: любая деталь, торчащая
            // наружу, увеличивает измеримый габарит персонажа, а на него
            // завязаны раскладки мини-игр.
            for (let i = 0; i < 5; i++) {
                const t = i / 4;
                // Разброс по длине и завалу: ровный частокол одинаковых
                // штрихов читается хирургическим швом, а не щетиной.
                const bx = mirror * (-7 + t * 18), by = 1 - t * 19;
                const len = 1.6 + brng() * 2;
                fringe.appendChild(svgEl('path', {
                    d: `M ${bx.toFixed(1)},${by.toFixed(1)} l ${(-mirror * len * 0.6).toFixed(1)},${(-len).toFixed(1)}`,
                    stroke: GRIME_SHADOW, 'stroke-width': SW.hairline, fill: 'none',
                    opacity: (0.3 * anatomy.coat.bristle).toFixed(3), 'stroke-linecap': 'round'
                }));
            }
            earGroup.appendChild(fringe);
        }
        earsGroup.appendChild(earGroup);
        // ВАЖНО: в refs кладётся ПОЛНЫЙ масштаб — с калибровкой формы и с
        // ракурсным сжатием. Раньше тут лежал только ear.scale*stretchX, а
        // tick() каждый кадр переписывает этот трансформ целиком, поэтому
        // и калибровка, и сжатие терялись через кадр после сборки: на
        // замерах дальнее и ближнее ухо выходили одинаковой ширины при
        // явно повёрнутой голове.
        earRefs[side] = {
            group: earGroup, shape: earShape, inner: earInner,
            anchorX, anchorY, baseAngle,
            // Всё, что нужно earPlacement, чтобы пересчитать посадку на
            // повороте, лежит здесь: живой пересчёт обязан получить ровно те
            // же числа, из которых собрана исходная поза.
            yawPhi: earPhi, latR: earLatR, rootOut: earRootOut, mirror,
            baseTilt: earBaseTilt, ownRotation: ear.rotation,
            baseScaleX: ear.scale * ear.stretchX * EAR_FORM_SCALE,
            baseScaleY: ear.scale * ear.stretchY * EAR_FORM_SCALE,
            scaleX: earSx,
            scaleY: earSy
        };
    });

    // ---------- СЛОИ КОЖИ ГОЛОВЫ ----------
    const headAnat = buildAnatomyStack(ctx, 'head', {
        rx, ry, axis: 'x',
        organZone: null,
        muscle: false,
        clipPathData: skullD,
        // ---------- НА МОРДЕ НЕ РИСУЮТ ЛИНИЙ ----------
        // Складки и щетина здесь ВЫКЛЮЧЕНЫ, и это не экономия. Правило
        // сформулировано двумя абзацами ниже — «любая нарисованная линия на
        // морде читается царапиной», — но голова при этом заказывала себе
        // именно линии: одиннадцать штрихованных дуг поперёк щёк. Вместе с
        // вибриссами и сосудами они превращали лицо в кашу из царапин.
        //
        // Причина в разнице масштабов. Тело крупное и текстуру держит; лицо
        // на телефоне высотой в шесть десятков пикселей, и любая отдельная
        // отметина на нём становится СЧИТАЕМОЙ — то есть перестаёт быть
        // текстурой и начинает спорить с глазами и ртом за внимание.
        // Рельеф морде даёт затенение мягкими пятнами, а не штрихи.
        coat: { rings: false, folds: false, bristle: false }
    });

    // ---------- РЕЛЬЕФ ЧЕРЕПА ----------
    // Надбровные дуги, височные впадины, скулы и жевательная мышца. Всё
    // мягкими пятнами: любая нарисованная линия на морде читается царапиной.
    let skullShading = null;
    if (anatomy.enabled) {
        const taper = skullCfg.relief != null ? skullCfg.relief : ((anatomy.skeleton && anatomy.skeleton.headTaper != null) ? anatomy.skeleton.headTaper : 0.14);
        if (taper > 0.01) {
            const k = taper / 0.14;
            skullShading = svgEl('g', { class: 'worm-skull-shading', 'clip-path': `url(#${skullClipId})` });
            const shadowFill = ensureSoftGradient(ctx, `worm-head-cheek-${ctx.instanceId}`, GRIME_SHADOW, 1);
            const lightFill = ensureSoftGradient(ctx, `worm-head-light-${ctx.instanceId}`, GRIME_HIGHLIGHT, 1);
            [-1, 1].forEach(side => {
                // височная впадина
                // Височная впадина и скула слиты в ОДНО вытянутое пятно на
                // сторону, а не в два отдельных. Раньше рельеф собирали из
                // девяти самостоятельных эллипсов по 0.14–0.23 прозрачности,
                // и на морде в размер экрана они читались не объёмом, а
                // россыпью пятен — «синяками». Объём даёт ОДИН крупный
                // мягкий переход, а не набор мелких.
                skullShading.appendChild(svgEl('ellipse', {
                    cx: (side * rx * 0.64).toFixed(1), cy: (-ry * 0.2).toFixed(1),
                    rx: (rx * 0.34).toFixed(1), ry: (ry * 0.44).toFixed(1),
                    fill: shadowFill, opacity: (0.11 * k).toFixed(3)
                }));
                // Светлая грань скулы — там, куда падает верхний свет.
                skullShading.appendChild(svgEl('ellipse', {
                    cx: (side * rx * 0.5).toFixed(1), cy: (ry * 0.14).toFixed(1),
                    rx: (rx * 0.34).toFixed(1), ry: (ry * 0.3).toFixed(1),
                    fill: lightFill, opacity: (0.1 * k).toFixed(3)
                }));
            });
        }
    }

    // ---------- МОРДА (ROSTRUM) ----------
    // Отдельный объём, выступающий вперёд и вниз, а не пятачок, наклеенный на
    // плоское лицо. Собственная светлая грань сверху, тени по бокам и
    // контактная тень в месте, где морда выходит из черепа.
    const muzzleW = (skullCfg.muzzleWidth != null ? skullCfg.muzzleWidth : 0.46) * rx;
    const muzzleTop = ry * MUZZLE_TOP;
    const muzzleBottom = ry * MUZZLE_BOTTOM;
    // Доля вдоль морды → координата. Все её детали посажены через неё, а не
    // отдельными числами: иначе при следующем сдвиге черт лица они снова
    // разъедутся поодиночке, как уже было.
    const mz = (t) => muzzleTop + (muzzleBottom - muzzleTop) * t;
    // Морда — тот же выступающий объём, что и пятачок, и уезжает вместе с ним,
    // иначе пятак «отклеится» от своей опоры.
    const muzzleProj = yawProject(rx, 0, headYaw, SNOUT_PROTRUDE * 0.7);
    // ---------- КЛИП И ТРАНСФОРМ — НА РАЗНЫХ ГРУППАХ ----------
    // Это не стилистика, а обязательное разделение. В SVG clip-path
    // разрешается в системе координат элемента ПОСЛЕ его собственного
    // трансформа: повесить и то и другое на один узел — значит двигать клип
    // вместе с содержимым.
    //
    // Здесь это и происходило. Морда выступает вперёд, поэтому при повороте
    // головы уезжает вбок — при штатном ракурсе в три четверти на 17.75
    // единицы, — и клип по черепу уезжал вместе с ней. Морда обрезалась
    // силуэтом, сдвинутым относительно настоящего: справа вылезала за контур
    // головы, слева срезала лицо. На светлой комнате это стало видно как
    // прямоугольная кромка поперёк щеки.
    //
    // Внешняя группа несёт КЛИП и не двигается. Внутренняя несёт трансформ.
    const muzzleGroup = svgEl('g', {
        'data-part': 'muzzle', 'clip-path': `url(#${skullClipId})`
    });
    const muzzleShift = svgEl('g', {
        transform: `translate(${muzzleProj.x.toFixed(2)},0)`
    });
    muzzleGroup.appendChild(muzzleShift);
    const muzzleGradId = `worm-muzzle-grad-${ctx.instanceId}`;
    const muzzleFill = ensureVolumeGradient(ctx.defs, muzzleGradId, mixColor(head.fill, GRIME_HIGHLIGHT, 0.12), {
        cx: '42%', cy: '22%', r: '80%',
        highlight: 0.16, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.24, shadowTint: GRIME_SHADOW
    });
    const muzzleD = `M ${(-muzzleW * 1.22).toFixed(1)},${muzzleTop.toFixed(1)} ` +
        `C ${(-muzzleW * 1.3).toFixed(1)},${mz(0.44).toFixed(1)} ${(-muzzleW * 1.08).toFixed(1)},${mz(0.81).toFixed(1)} ${(-muzzleW * 0.86).toFixed(1)},${muzzleBottom.toFixed(1)} ` +
        `C ${(-muzzleW * 0.5).toFixed(1)},${mz(1.14).toFixed(1)} ${(muzzleW * 0.5).toFixed(1)},${mz(1.14).toFixed(1)} ${(muzzleW * 0.86).toFixed(1)},${muzzleBottom.toFixed(1)} ` +
        `C ${(muzzleW * 1.08).toFixed(1)},${mz(0.81).toFixed(1)} ${(muzzleW * 1.3).toFixed(1)},${mz(0.44).toFixed(1)} ${(muzzleW * 1.22).toFixed(1)},${muzzleTop.toFixed(1)} ` +
        `C ${(muzzleW * 0.7).toFixed(1)},${mz(-0.19).toFixed(1)} ${(-muzzleW * 0.7).toFixed(1)},${mz(-0.19).toFixed(1)} ${(-muzzleW * 1.22).toFixed(1)},${muzzleTop.toFixed(1)} Z`;
    // Морда не должна иметь резкой верхней границы — она не накладка, а
    // продолжение черепа: заливка приглушена, а стык с лицом растворяется
    // мягким пятном (см. следующий слой).
    muzzleShift.appendChild(svgEl('path', { d: muzzleD, fill: muzzleFill, opacity: 0.5 }));
    muzzleShift.appendChild(svgEl('ellipse', {
        cx: 0, cy: mz(0.01).toFixed(1),
        rx: (muzzleW * 1.5).toFixed(1), ry: (ry * 0.26).toFixed(1),
        fill: ensureSoftGradient(ctx, `worm-muzzle-blend-${ctx.instanceId}`, mixColor(head.fill, GRIME_HIGHLIGHT, 0.12), 1),
        opacity: 0.5
    }));
    // Тени по бокам морды — она отделяется от щёк.
    [-1, 1].forEach(side => {
        muzzleShift.appendChild(svgEl('ellipse', {
            cx: (side * muzzleW * 1.24).toFixed(1), cy: mz(0.5).toFixed(1),
            rx: (rx * 0.12).toFixed(1), ry: (ry * 0.34).toFixed(1),
            fill: ensureSoftGradient(ctx, `worm-muzzle-side-${ctx.instanceId}`, GRIME_SHADOW, 1),
            opacity: 0.35
        }));
    });
    // Светлая грань спинки морды.
    muzzleShift.appendChild(svgEl('ellipse', {
        cx: (-muzzleW * 0.18).toFixed(1), cy: mz(0.32).toFixed(1),
        rx: (muzzleW * 0.44).toFixed(1), ry: (ry * 0.3).toFixed(1),
        fill: ensureSoftGradient(ctx, `worm-muzzle-top-${ctx.instanceId}`, GRIME_HIGHLIGHT, 1),
        opacity: 0.22
    }));

    // ---------- ЧЕЛЮСТЬ ----------
    // Нижняя губа и подбородок вынесены в свою группу: при открывании рта она
    // опускается (см. tick), и морда открывается как челюсть, а не как дырка
    // в неподвижной коже.
    // Та же пара, что у морды: клип снаружи, трансформ внутри. Челюсть
    // опускается при открывании рта, и без разделения клип по черепу ехал бы
    // вниз вместе с ней.
    const jawGroup = svgEl('g', { 'data-part': 'jaw', 'clip-path': `url(#${skullClipId})` });
    const jawShift = svgEl('g');
    jawGroup.appendChild(jawShift);
    const jawFill = ensureSoftGradient(ctx, `worm-jaw-shade-${ctx.instanceId}`, GRIME_SHADOW, 1);
    jawShift.appendChild(svgEl('ellipse', {
        cx: 0, cy: mz(1.06).toFixed(1),
        rx: (muzzleW * 0.95).toFixed(1), ry: (ry * 0.16).toFixed(1),
        fill: jawFill, opacity: 0.3
    }));
    const lipColor = mixColor(head.mouth.color, head.fill, 0.35);
    const lowerLip = svgEl('path', {
        d: `M ${(-muzzleW * 0.78).toFixed(1)},${mz(1.08).toFixed(1)} Q 0,${mz(1.17).toFixed(1)} ${(muzzleW * 0.78).toFixed(1)},${mz(1.08).toFixed(1)}`,
        fill: 'none', stroke: lipColor, 'stroke-width': SW.structure, opacity: 0.5, 'stroke-linecap': 'round'
    });
    jawShift.appendChild(lowerLip);

    // ---------- ПЯТАЧОК ----------
    const snout = head.snout;
    // Высота из общей связки черт лица (SNOUT_Y): пятачок поднят, чтобы под
    // ним расчистить место широкому рту. Иначе рот подлезает прямо под него и
    // уголки теряются на фоне ноздрей — ровно то, ради чего рот и расширяли.
    const snoutY = ry * SNOUT_Y;
    const snoutRx = 14.5, snoutRy = 10.5;
    // Пятачок сидит на оси лица (азимут 0), но заметно ВЫСТУПАЕТ вперёд,
    // поэтому при повороте уезжает в сторону сильнее любой другой черты.
    // Именно ушедший с центра нос и сообщает глазу «это ракурс».
    const snoutProj = yawProject(rx, 0, headYaw, SNOUT_PROTRUDE);
    const snoutYawSquash = Math.max(0.55, Math.abs(snoutProj.squash));
    const snoutGroup = svgEl('g', {
        'data-part': 'snout',
        'data-anchor': 'snout',
        transform: `translate(${snoutProj.x.toFixed(2)},${snoutY.toFixed(2)}) scale(${(snout.scale * snout.stretchX * snoutYawSquash).toFixed(3)},${(snout.scale * snout.stretchY).toFixed(3)})`
    });
    const snoutGradId = `worm-snout-grad-${ctx.instanceId}`;
    const snoutFill = ensureVolumeGradient(ctx.defs, snoutGradId, snout.fill, {
        cx: '38%', cy: '28%', r: '82%',
        highlight: 0.22, highlightTint: GRIME_HIGHLIGHT,
        shadow: -0.34, shadowTint: GRIME_SHADOW
    });
    // Диск пятачка + мягкая тень под ним: он выступает вперёд, а не лежит
    // в плоскости морды.
    snoutGroup.appendChild(svgEl('ellipse', {
        cx: 0, cy: (snoutRy * 0.42).toFixed(1), rx: (snoutRx * 1.05).toFixed(1), ry: (snoutRy * 0.8).toFixed(1),
        fill: ensureSoftGradient(ctx, `worm-snout-shadow-${ctx.instanceId}`, GRIME_SHADOW, 1), opacity: 0.4
    }));
    const snoutShape = svgEl('ellipse', { cx: 0, cy: 0, rx: snoutRx, ry: snoutRy, fill: snoutFill, stroke: snout.stroke, 'stroke-width': SW.structure });
    const nostrilL = svgEl('ellipse', { cx: -4.8, cy: 0, rx: 2.3, ry: 3.4, fill: VISCERA[700], transform: 'rotate(-14 -4.8 0)' });
    const nostrilR = svgEl('ellipse', { cx: 4.8, cy: 0, rx: 2.3, ry: 3.4, fill: VISCERA[700], transform: 'rotate(14 4.8 0)' });
    const snoutShine = svgEl('ellipse', { cx: -4, cy: -4.6, rx: 4.6, ry: 2, fill: SPEC, opacity: 0.32 });
    const poreGroup = svgEl('g', { class: 'worm-snout-pores' });
    const poreRng = mulberry32(hashStringSeed(`${ctx.instanceId}-snout-pores`));
    // Пор было четырнадцать на пятачок размером 30×20, и вместе с семью
    // радиальными морщинками это давало девятнадцать отметин на пятачке —
    // не текстура, а сыпь. Восемь штук читаются порами, а не пересчитываются
    // глазом по одной.
    for (let i = 0; i < 8; i++) {
        const a = poreRng() * Math.PI * 2;
        const rr = Math.sqrt(poreRng()) * 0.86;
        const px = Math.cos(a) * snoutRx * rr, py = Math.sin(a) * snoutRy * rr;
        if (Math.abs(px) < 8 && Math.abs(py) < 4.5) continue;
        poreGroup.appendChild(svgEl('circle', {
            cx: px.toFixed(1), cy: py.toFixed(1), r: (0.5 + poreRng() * 0.5).toFixed(2),
            fill: mixColor(snout.fill, GRIME_SHADOW, 0.55), opacity: 0.3
        }));
    }
    const nostrilShade = svgEl('g');
    [[-4.8, -14], [4.8, 14]].forEach(([nx, rot]) => {
        nostrilShade.appendChild(svgEl('ellipse', {
            cx: nx, cy: 1, rx: 1.6, ry: 2.2, fill: INK, opacity: 0.75,
            transform: `rotate(${rot} ${nx} 0)`
        }));
    });
    // Вертикальная бороздка (philtrum) — она есть у каждой свиньи и сразу
    // читается как порода, а не как абстрактный кружок.
    const philtrum = svgEl('path', {
        d: `M 0,${(-snoutRy * 0.25).toFixed(1)} L 0,${(snoutRy * 0.95).toFixed(1)}`,
        stroke: mixColor(snout.fill, GRIME_SHADOW, 0.5), 'stroke-width': SW.detail, opacity: 0.5, fill: 'none'
    });
    snoutGroup.appendChild(snoutShape);
    snoutGroup.appendChild(poreGroup);
    snoutGroup.appendChild(snoutShine);
    snoutGroup.appendChild(nostrilL);
    snoutGroup.appendChild(nostrilR);
    snoutGroup.appendChild(nostrilShade);
    snoutGroup.appendChild(philtrum);
    if (anatomy.enabled && (anatomy.coat && (anatomy.coat.folds || 0) > 0.01)) {
        const rng = anatRng(anatomy, 'snout', 'radial');
        const wrinkles = svgEl('g', { class: 'worm-snout-wrinkles' });
        // Морщинок было шесть-восемь; на пятачке в размер экрана они
        // сливались с порами в общую рябь. Четыре читаются как расходящиеся
        // складки кожи — то, чем они и являются.
        const count = 4 + Math.floor(rng() * 2);
        for (let i = 0; i < count; i++) {
            const a = (i / count) * Math.PI * 2 + rng() * 0.2;
            const r0 = snoutRx * 1.05, r1 = r0 + 2 + rng() * 2.2;
            wrinkles.appendChild(svgEl('path', {
                d: `M ${(Math.cos(a) * r0).toFixed(1)},${(Math.sin(a) * r0 * 0.72).toFixed(1)} ` +
                   `L ${(Math.cos(a) * r1).toFixed(1)},${(Math.sin(a) * r1 * 0.72).toFixed(1)}`,
                stroke: GRIME_SHADOW, 'stroke-width': SW.hairline, fill: 'none',
                opacity: (0.16 * anatomy.coat.folds).toFixed(3), 'stroke-linecap': 'round'
            }));
        }
        snoutGroup.appendChild(wrinkles);
    }

    // ---------- РОТ ----------
    const mouth = head.mouth;
    // Рот едет по той же выступающей морде, но его выступ МЕНЬШЕ, чем у
    // пятачка: пятачок — самая передняя точка, рот сидит под ним и ближе к
    // черепу. Плюс жёсткий ограничитель: на полном выступе линия рта
    // вылезала вбок за контур челюсти и висела в воздухе.
    const MOUTH_PROTRUDE = 0.08;
    const mouthProj = yawProject(rx, 0, headYaw, MOUTH_PROTRUDE);
    const mouthMaxX = rx * (skullCfg.muzzleWidth != null ? skullCfg.muzzleWidth : 0.46) * 0.45;
    const mouthYawX = Math.sign(mouthProj.x) * Math.min(Math.abs(mouthProj.x), mouthMaxX);
    const mouthYawSquash = Math.max(0.62, Math.abs(mouthProj.squash));
    const mouthAnchor = svgEl('g', {
        'data-part': 'mouth',
        'data-anchor': 'mouth',
        // Обрезка по черепу вместо подбора «правильного» ограничителя:
        // при любом повороте дальний конец губы честно уходит за скулу,
        // как и положено в ракурсе, вместо того чтобы висеть в воздухе
        // за контуром челюсти.
        'clip-path': `url(#${skullClipId})`,
        // Рот сидит ПОД ПЯТАКОМ, а не на самой нижней кромке черепа: на ry*1.0 он
        // сливался с контуром подбородка и просто исчезал из морды.
        transform: `translate(${mouthYawX.toFixed(2)},${(ry * MOUTH_Y).toFixed(2)}) scale(${(mouth.scale * mouth.stretchX * mouthYawSquash).toFixed(3)},${(mouth.scale * mouth.stretchY).toFixed(3)})`
    });
    const mouthBuilt = buildMouthShapes(mouthAnchor, mouth, ctx.instanceId);
    updateMouthGeometry(mouthBuilt, mouthBendFromCurve(mouth.curve),
        mouthBuilt.MAX_GAP * clamp01(mouth.openness || 0));

    // ---------- ГЛАЗА ----------
    const eyesGroup = svgEl('g', { 'data-part': 'eyes' });
    // Полуширина черепа на высоте глаз (между виском и скулой) и с поправкой
    // на сужение повёрнутой стороны — она же служит ограничителем.
    const EYE_SURFACE_K = 0.86;
    const eyeSurfaceRx = rx * EYE_SURFACE_K;
    const yawCtx = {
        yaw: headYaw,
        headRx: eyeSurfaceRx,
        maxAbsX: eyeSurfaceRx * (1 - 0.13 * Math.abs(headYaw))
    };
    const eyeLeft = buildEyeNode(model.eyes.left, -1, ctx.instanceId, 'left', ctx.defs, yawCtx);
    const eyeRight = buildEyeNode(model.eyes.right, 1, ctx.instanceId, 'right', ctx.defs, yawCtx);
    eyesGroup.appendChild(eyeLeft.group);
    eyesGroup.appendChild(eyeRight.group);

    const hatAnchor = svgEl('g', { 'data-anchor': 'head-top', transform: `translate(0,${(-ry * 1.1).toFixed(2)})` });

    // Порядок ЯВНЫЙ, снизу вверх: уши → череп → слои кожи → рельеф черепа →
    // переход в шею → морда → челюсть → блик → рот → пятачок → глаза →
    // мелкая детализация кожи → якорь шляпы.
    tiltGroup.appendChild(earsGroup);
    tiltGroup.appendChild(skull);
    if (headAnat) tiltGroup.appendChild(headAnat.group);
    if (skullShading) tiltGroup.appendChild(skullShading);
    if (ctx.neckColor) {
        const neck = buildHeadNeckTransition(ctx, rx, ry, ctx.neckColor);
        if (neck) tiltGroup.appendChild(neck);
    }
    tiltGroup.appendChild(muzzleGroup);
    tiltGroup.appendChild(jawGroup);
    tiltGroup.appendChild(headShine);
    tiltGroup.appendChild(mouthAnchor);
    tiltGroup.appendChild(snoutGroup);
    tiltGroup.appendChild(eyesGroup);
    const headDetail = buildHeadDetailLayer(ctx, rx, ry, skullD);
    if (headDetail) tiltGroup.appendChild(headDetail);
    tiltGroup.appendChild(hatAnchor);

    const scarLayer = svgEl('g', { 'data-anchor': 'head-scars', class: 'worm-scar-layer' });
    tiltGroup.appendChild(scarLayer);

    const headRef = {
        group, tiltGroup, skull, ears: earRefs, snoutGroup,
        muzzleGroup, muzzleShift, jawGroup, jawShift,
        mouth: mouthBuilt, mouthAnchor, skullClipShape, eyes: { left: eyeLeft, right: eyeRight },
        scarLayer, rx, ry, snoutY, anat: headAnat,
        fillColor: ctx.neckColor || head.fill,
        // ---------- ДАННЫЕ ДЛЯ ЖИВОГО ПОВОРОТА ----------
        // Всё, что нужно, чтобы пересчитать ракурс без пересборки головы.
        skullCfg,
        yaw: headYaw,
        eyeSurfaceRx,
        snoutProtrude: SNOUT_PROTRUDE,
        mouthProtrude: MOUTH_PROTRUDE,
        // Базовые (без ракурса) значения, от которых считается пересчёт.
        snoutX: snoutProj.x,
        snoutSquash: snoutYawSquash,
        muzzleX: muzzleProj.x,
        mouthX: mouthYawX,
        mouthSquash: mouthYawSquash,
        mouthBaseScale: { x: mouth.scale * mouth.stretchX, y: mouth.scale * mouth.stretchY }
    };
    return headRef;
}

// ---------- ЖИВОЙ ПЕРЕСЧЁТ ПОВОРОТА ГОЛОВЫ ----------
// Тот же расчёт, что и при сборке, но переставляет атрибуты УЖЕ созданных
// узлов — ни одного нового элемента. Это обязательное условие, чтобы поворот
// можно было анимировать: setOverride пересобирает всю голову заново и для
// покадровой анимации не годится.
//
// Пересчитывать нужно ровно шесть вещей: путь черепа (он асимметричен),
// трансформы двух глаз, двух ушей, пятачка с мордой и рта.
function applyHeadYaw(headRef, yaw) {
    if (!headRef || headRef.yaw === yaw) return;
    headRef.yaw = yaw;
    const rx = headRef.rx, ry = headRef.ry;

    // Череп — единственная строка пути, которую приходится пересобирать.
    // Она короткая (шесть кривых), в отличие от пути кишечного тракта.
    if (headRef.skull) {
        const d = skullPathData(rx, ry, headRef.skullCfg, yaw);
        headRef.skull.setAttribute('d', d);
        if (headRef.skullClipShape) headRef.skullClipShape.setAttribute('d', d);
    }

    // Глаза: посадка по поверхности + ракурсное сжатие через scale группы.
    const maxAbsX = headRef.eyeSurfaceRx * (1 - 0.13 * Math.abs(yaw));
    ['left', 'right'].forEach(side => {
        const e = headRef.eyes[side];
        if (!e) return;
        const proj = yawProject(headRef.eyeSurfaceRx, e.yawPhi, yaw, 0);
        const squash = Math.max(0.58, Math.abs(proj.squash));
        const limit = Math.max(0, maxAbsX - e.baseRx * squash * 1.12);
        const x = Math.sign(proj.x) * Math.min(Math.abs(proj.x), limit);
        e.group.setAttribute('transform',
            `translate(${x.toFixed(2)},${e.offsetY}) scale(${squash.toFixed(3)},1)`);
    });

    // Уши: пересчитываем якорь и сжатие, но САМ трансформ не пишем — его
    // каждый кадр собирает tick() вместе с наклоном уха. Пишем в refs,
    // откуда tick его и берёт.
    ['left', 'right'].forEach(side => {
        const ear = headRef.ears[side];
        if (!ear) return;
        const place = earPlacement(ear, yaw);
        ear.anchorX = place.x;
        ear.scaleX = ear.baseScaleX * place.squash;
        // Разворот наружу тоже зависит от ракурса — ухо, вставшее ребром,
        // подбирается за голову вместо того, чтобы торчать вбок.
        ear.baseAngle = ear.baseTilt * (1 - EAR_EDGE_STRAIGHTEN * place.edge) + ear.ownRotation;
        ear.group.setAttribute('transform',
            `translate(${ear.anchorX.toFixed(2)},${ear.anchorY.toFixed(2)}) ` +
            `rotate(${ear.baseAngle.toFixed(1)}) ` +
            `scale(${ear.scaleX.toFixed(3)},${ear.scaleY.toFixed(3)})`);
    });

    // Пятачок и морда: выступающие черты, уезжают сильнее прочих. Сам
    // трансформ пятачка тоже собирает tick() (принюхивание), поэтому здесь
    // только обновляем базовые значения в refs.
    const snoutProj = yawProject(rx, 0, yaw, headRef.snoutProtrude);
    headRef.snoutX = snoutProj.x;
    headRef.snoutSquash = Math.max(0.55, Math.abs(snoutProj.squash));
    if (headRef.muzzleGroup) {
        const mzp = yawProject(rx, 0, yaw, headRef.snoutProtrude * 0.7);
        headRef.muzzleX = mzp.x;
        applyMuzzleTransform(headRef);
    }

    // Рот: тот же выступ, но с ограничителем по ширине морды.
    if (headRef.mouthAnchor) {
        const mp = yawProject(rx, 0, yaw, headRef.mouthProtrude);
        const maxX = rx * (headRef.skullCfg.muzzleWidth != null ? headRef.skullCfg.muzzleWidth : 0.46) * 0.45;
        headRef.mouthX = Math.sign(mp.x) * Math.min(Math.abs(mp.x), maxX);
        headRef.mouthSquash = Math.max(0.62, Math.abs(mp.squash));
        const mo = headRef.mouthBaseScale || { x: 1, y: 1 };
        headRef.mouthAnchor.setAttribute('transform',
            `translate(${headRef.mouthX.toFixed(2)},${(ry * MOUTH_Y).toFixed(2)}) ` +
            `scale(${(mo.x * headRef.mouthSquash).toFixed(3)},${mo.y.toFixed(3)})`);
    }
}

// Трансформ «морды» пишут ДВА источника: поворот головы (сдвиг вбок, потому
// что морда выступает вперёд) и надувание щёк из мимики. Раньше каждый писал
// атрибут целиком и затирал чужую работу — надутые щёки сбрасывали сдвиг от
// поворота, и морда отклеивалась от пятачка, повисая светлым пятном рядом с
// ним. Поэтому оба слагаемых хранятся в refs, а собирает их одно место.
function applyMuzzleTransform(headRef) {
    if (!headRef.muzzleShift) return;
    const x = headRef.muzzleX || 0;
    const puff = headRef.muzzlePuff || 0;
    const parts = [];
    if (Math.abs(x) > 0.01) parts.push(`translate(${x.toFixed(2)},0)`);
    if (puff > 0.001) parts.push(`scale(${(1 + 0.12 * puff).toFixed(3)},${(1 + 0.05 * puff).toFixed(3)})`);
    headRef.muzzleShift.setAttribute('transform', parts.join(' '));
}

// ---------- ШРАМЫ ----------
// Процедурно генерируемая метка на конкретном сегменте. Размер намеренно
// ограничен долей от радиуса сегмента-хозяина, чтобы не вылезать за его
// пределы.
// ---------- ОТМЕТИНА НА ТЕЛЕ ----------
// Форма выводится из сида (WormMarks.geometry), цвет — сдвиг от тона кожи
// хозяина (WormMarks.color). Ни то, ни другое не хранится: отметина в данных
// это несколько чисел, а не список точек и не hex.
//
// Раньше здесь была ровная горизонтальная эллипса цвета scar.color. Ровный
// эллипс читается как наклейка: у шрама неровный край и он изогнут, потому
// что кожа при заживлении стягивается. Отсюда рваный контур и дуга.
function buildMarkNode(mark, place, hostRadius, skinColor) {
    const geo = WormMarks.geometry(mark.seed, mark.kind);
    const color = WormMarks.color(skinColor || FLESH[500], mark.kind);
    const rng = WormMarks.rng(mark.seed || 0, 'draw');

    const half = Math.max(2.5, geo.length * hostRadius * 0.5);
    const wide = Math.max(0.9, geo.width * hostRadius);
    const bend = geo.curve * half * 0.5;

    // Осевая линия шрама — дуга, а не отрезок.
    const axisAt = (u) => ({          // u: -1..1
        x: u * half,
        y: bend * (1 - u * u)
    });

    // Обходим фигуру по одной стороне и возвращаемся по другой, дёргая
    // ширину на каждом шаге: получается неровный край.
    const steps = 5 + geo.notches * 2;
    const side = (dir) => {
        const pts = [];
        for (let i = 0; i <= steps; i++) {
            const u = dir > 0 ? (-1 + (2 * i) / steps) : (1 - (2 * i) / steps);
            const p = axisAt(u);
            // К концам шрам сходит на нет, в середине шире всего.
            const taper = Math.pow(1 - u * u, 0.6);
            const jitter = 1 - geo.ragged * rng() * 0.55;
            const w = wide * taper * jitter * dir;
            pts.push(`${p.x.toFixed(2)},${(p.y + w).toFixed(2)}`);
        }
        return pts;
    };

    const d = 'M ' + side(1).join(' L ') + ' L ' + side(-1).join(' L ') + ' Z';

    const group = svgEl('g', {
        transform: `translate(${(place.x * hostRadius).toFixed(2)},${(place.y * hostRadius).toFixed(2)}) rotate(${place.rotation.toFixed(1)})`,
        class: `worm-mark worm-mark-${mark.kind || 'scar'}`
    });
    group.appendChild(svgEl('path', { d, fill: color, opacity: 0.9 }));

    // Тонкая светлая жилка вдоль шрама: рубцовая ткань блестит сильнее кожи.
    const shine = [];
    for (let i = 0; i <= steps; i++) {
        const p = axisAt(-1 + (2 * i) / steps);
        shine.push(`${p.x.toFixed(2)},${p.y.toFixed(2)}`);
    }
    group.appendChild(svgEl('polyline', {
        points: shine.join(' '),
        fill: 'none',
        stroke: WormMarks.color(skinColor || FLESH[500], 'shine'),
        'stroke-width': Math.max(0.4, wide * 0.2).toFixed(2),
        'stroke-linecap': 'round',
        opacity: 0.32
    }));
    return group;
}

// ---------- КУЧКА НА ПОЛУ ----------
// Результат пищеварения. Форма детерминированная от сида: две-три спирали
// друг на друге, каждая следующая мельче. Цвет — из палитры (жёлчная линия
// плюс чернота), а не подобранный на глаз коричневый.
function buildPoopNode(obj, depthScale) {
    const scale = depthScale || 1;
    const rng = mulberry32(hashStringSeed(String(obj.seed || obj.id || 'poop')));
    const base = 7 * scale;
    const group = svgEl('g', {
        class: 'worm-poop',
        transform: `translate(${obj.x.toFixed(1)},${obj.y.toFixed(1)})`
    });

    const body = mixColor(BILE[600], P_.ink, 0.42);
    const light = mixColor(body, GRIME_HIGHLIGHT, 0.35);

    // Тень на полу: без неё кучка висит над полом.
    group.appendChild(svgEl('ellipse', {
        cx: 0, cy: (base * 0.15).toFixed(1),
        rx: (base * 1.5).toFixed(1), ry: (base * 0.5).toFixed(1),
        fill: P_.ink, opacity: 0.3
    }));

    const layers = 3;
    for (let i = 0; i < layers; i++) {
        const k = i / (layers - 1);
        const rx = base * (1.25 - k * 0.55) * (0.9 + rng() * 0.2);
        const ry = base * (0.5 - k * 0.14);
        const cy = -i * base * 0.42;
        const cx = (rng() - 0.5) * base * 0.3;
        group.appendChild(svgEl('ellipse', {
            cx: cx.toFixed(1), cy: cy.toFixed(1), rx: rx.toFixed(1), ry: ry.toFixed(1),
            fill: body, stroke: P_.ink, 'stroke-width': SW.detail
        }));
        group.appendChild(svgEl('ellipse', {
            cx: (cx - rx * 0.25).toFixed(1), cy: (cy - ry * 0.3).toFixed(1),
            rx: (rx * 0.35).toFixed(1), ry: (ry * 0.3).toFixed(1),
            fill: light, opacity: 0.4
        }));
    }
    // Кончик сверху — узнаваемый силуэт кучки.
    group.appendChild(svgEl('path', {
        d: `M ${(-base * 0.22).toFixed(1)},${(-layers * base * 0.42 + base * 0.1).toFixed(1)} ` +
           `Q 0,${(-layers * base * 0.42 - base * 0.5).toFixed(1)} ${(base * 0.22).toFixed(1)},${(-layers * base * 0.42 + base * 0.1).toFixed(1)} Z`,
        fill: body, stroke: P_.ink, 'stroke-width': SW.hairline
    }));
    return group;
}

// ---------- СБОРКА ВСЕЙ ЦЕПОЧКИ ТЕЛА ----------
// ============================================================================
//                   ЕДИНЫЙ СИЛУЭТ ТЕЛА (BODY HULL)
// ============================================================================
// Раньше тело читалось как СТОПКА ОТДЕЛЬНЫХ ШАРОВ: у каждого сегмента была
// своя обводка, и на каждом стыке был виден шов. На качественных артах такого
// существа тело — ОДНО непрерывное, а сегментация сделана перетяжками ПОВЕРХ
// него, а не границами между шарами. Это самое крупное отличие, и оно чинится
// не косметикой, а сменой способа сборки силуэта.
//
// Как строится единый силуэт (без вычисления настоящей огибающей, которая на
// поворотах цепи даёт вырожденные дуги):
//   • тело = набор КРУГОВ (по одному на часть) + МОСТЫ между соседями
//     (трапеции по касательным) — вместе они дают ровно ту же фигуру, что и
//     огибающая, но каждая её деталь остаётся простым SVG-примитивом;
//   • контур — не обводка каждой части, а ОДНА тёмная копия всей фигуры,
//     раздутая на толщину контура и лежащая ПОД телом (приём "fake outline").
//     Никаких пересекающихся линий на стыках в принципе не возникает;
//   • та же фигура, собранная третий раз, служит clipPath — по нему
//     обрезаются перетяжки и отражённый свет, чтобы они не выходили за тело.
// Все три копии обновляются в tick() перестановкой атрибутов уже созданных
// узлов — новых элементов за кадр не создаётся.

// Мост между двумя кругами: трапеция по внешним касательным. Именно она
// заполняет промежуток между соседними частями, из-за которого тело раньше
// выглядело набором отдельных шаров.
function bridgeQuadPath(a, b, pad) {
    const dx = b.x - a.x, dy = b.y - a.y;
    const d = Math.hypot(dx, dy);
    if (d < 0.001) return '';
    const nx = -dy / d, ny = dx / d;      // единичная нормаль к оси моста
    const ra = a.r + (pad || 0), rb = b.r + (pad || 0);
    const p1x = a.x + nx * ra, p1y = a.y + ny * ra;
    const p2x = b.x + nx * rb, p2y = b.y + ny * rb;
    const p3x = b.x - nx * rb, p3y = b.y - ny * rb;
    const p4x = a.x - nx * ra, p4y = a.y - ny * ra;
    return `M ${p1x.toFixed(1)},${p1y.toFixed(1)} L ${p2x.toFixed(1)},${p2y.toFixed(1)} ` +
           `L ${p3x.toFixed(1)},${p3y.toFixed(1)} L ${p4x.toFixed(1)},${p4y.toFixed(1)} Z`;
}

// Три синхронных представления одной фигуры: контур (раздутая тёмная копия),
// заполнение мостов и clipPath. Узлы создаются один раз на пересборке,
// дальше только переставляются координаты.
function createHullLayers(ctx, count, outlineColor, outlineWidth) {
    const clipId = `worm-hull-clip-${ctx.instanceId}`;
    const clip = svgEl('clipPath', { id: clipId });
    const outline = svgEl('g', { class: 'worm-hull-outline' });
    // Отражённый свет — ЕЩЁ ОДНА копия силуэта, светлая, чуть меньше
    // раздутая и сдвинутая вниз-вправо. Лежит между тёмным контуром и телом:
    // сверху-слева её перекрывает само тело, а снизу-справа остаётся узкая
    // светлая кайма. Тот же приём, что и с контуром, — никаких масок и
    // фильтров, и, в отличие от дуг по каждому кругу, кайма нигде не
    // проходит по внутренним стыкам.
    const rimFill = mixColor(ctx.rimBaseColor || outlineColor, GRIME_HIGHLIGHT, 0.5);
    const rimGroup = svgEl('g', { class: 'worm-hull-rim', opacity: 0.55, transform: 'translate(1,1.8)' });
    const bridges = svgEl('g', { class: 'worm-hull-bridges' });

    const outlineCircles = [], outlineBridges = [], clipCircles = [], clipBridges = [],
          bridgeShapes = [], rimCircles = [], rimBridges = [];
    for (let i = 0; i < count; i++) {
        const oc = svgEl('circle', { cx: 0, cy: 0, r: 0, fill: outlineColor });
        outline.appendChild(oc); outlineCircles.push(oc);
        const rc = svgEl('circle', { cx: 0, cy: 0, r: 0, fill: rimFill });
        rimGroup.appendChild(rc); rimCircles.push(rc);
        const cc = svgEl('circle', { cx: 0, cy: 0, r: 0 });
        clip.appendChild(cc); clipCircles.push(cc);
        if (i < count - 1) {
            const ob = svgEl('path', { d: '', fill: outlineColor });
            outline.appendChild(ob); outlineBridges.push(ob);
            const rb = svgEl('path', { d: '', fill: rimFill });
            rimGroup.appendChild(rb); rimBridges.push(rb);
            const cb = svgEl('path', { d: '' });
            clip.appendChild(cb); clipBridges.push(cb);
            const bs = svgEl('path', { d: '', fill: 'none' });
            bridges.appendChild(bs); bridgeShapes.push(bs);
        }
    }
    ctx.defs.appendChild(clip);
    return { clipId, clip, outline, rimGroup, bridges, outlineCircles, outlineBridges,
             rimCircles, rimBridges, clipCircles, clipBridges, bridgeShapes, outlineWidth };
}

// Перетяжки между частями ("кольца"). На арте это не линия, а ВАЛИК: тень
// перед ним и подсветка после. Собирается из двух узких эллипсов, повёрнутых
// поперёк оси тела, и обрезается по силуэту.
function createRingLayers(ctx, count) {
    const group = svgEl('g', { class: 'worm-body-rings', 'clip-path': `url(#worm-hull-clip-${ctx.instanceId})` });
    // Валик собран из мягких градиентных пятен, а не из плоских эллипсов:
    // жёсткая тёмная полоса поперёк тела читается как шов/стяжка ремнём, а
    // нужна вмятина — тень, плавно сходящая на нет по обе стороны.
    const shadeFill = ensureSoftGradient(ctx, `worm-ring-shade-${ctx.instanceId}`, GRIME_SHADOW, 1);
    const lightFill = ensureSoftGradient(ctx, `worm-ring-light-${ctx.instanceId}`, GRIME_HIGHLIGHT, 1);
    const rings = [];
    for (let i = 0; i < count; i++) {
        const g = svgEl('g', { class: 'worm-body-ring' });
        const shade = svgEl('ellipse', { cx: 0, cy: 0, rx: 3, ry: 10, fill: shadeFill, opacity: 0.3 });
        const light = svgEl('ellipse', { cx: 3, cy: 0, rx: 2, ry: 10, fill: lightFill, opacity: 0.26 });
        const crease = svgEl('ellipse', { cx: 0, cy: 0, rx: 0.9, ry: 10, fill: shadeFill, opacity: 0.4 });
        g.appendChild(shade); g.appendChild(light); g.appendChild(crease);
        group.appendChild(g);
        rings.push({ g, shade, light, crease });
    }
    return { group, rings };
}

// ============================================================================
//                  ЕДИНЫЙ КИШЕЧНЫЙ ТРАКТ (GUT TRACT)
// ============================================================================
// Кишка не может жить кусками внутри отдельных сегментов: каждый кусок знает
// только свой сегмент, поэтому на каждом стыке неизбежен разрыв, и на
// повороте тела (тело идёт вертикально от головы и разворачивается в животе
// к хвосту) куски смотрят в разные стороны. Поэтому тракт вынесен на уровень
// ВСЕГО ТЕЛА — ровно тем же приёмом, что и единый силуэт:
//
//   • осевая линия тракта строится по центрам тех же самых кругов силуэта,
//     то есть автоматически повторяет текущий изгиб тела, дыхание и
//     раздутие живота — разойтись с телом она не может;
//   • вдоль осевой тракт колеблется по нормали: в шее и хвосте это спокойная
//     волна, а в животе частота и амплитуда резко растут — получается
//     змеевидная петля кишечника, из которой тракт выходит вверх к голове и
//     вниз к хвосту одной неразрывной трубой;
//   • труба рисуется ЛЕНТОЙ (замкнутый контур из двух смещённых кромок), а
//     не линией со stroke: только так толщина может меняться вдоль тракта —
//     толще в животе, сходя на нет к голове и к кончику хвоста;
//   • весь тракт обрезается тем же clipPath, что и силуэт, поэтому нигде не
//     выходит за тело.

// Плотное сэмплирование осевой линии тела: сглаженная кривая Catmull-Rom
// через центры кругов силуэта, с интерполяцией радиуса тела вдоль неё.
function sampleBodyAxis(circles, step) {
    const pts = circles.filter(c => c && c.r > 0.5);
    if (pts.length < 2) return [];
    const out = [];
    const at = i => pts[Math.max(0, Math.min(pts.length - 1, i))];
    for (let i = 0; i < pts.length - 1; i++) {
        const p0 = at(i - 1), p1 = at(i), p2 = at(i + 1), p3 = at(i + 2);
        const segLen = Math.hypot(p2.x - p1.x, p2.y - p1.y);
        const n = Math.max(2, Math.ceil(segLen / step));
        for (let j = 0; j < n; j++) {
            const t = j / n, t2 = t * t, t3 = t2 * t;
            // Catmull-Rom: проходит через опорные точки, гладко стыкуется.
            out.push({
                x: 0.5 * ((2 * p1.x) + (-p0.x + p2.x) * t + (2 * p0.x - 5 * p1.x + 4 * p2.x - p3.x) * t2 + (-p0.x + 3 * p1.x - 3 * p2.x + p3.x) * t3),
                y: 0.5 * ((2 * p1.y) + (-p0.y + p2.y) * t + (2 * p0.y - 5 * p1.y + 4 * p2.y - p3.y) * t2 + (-p0.y + 3 * p1.y - 3 * p2.y + p3.y) * t3),
                r: p1.r + (p2.r - p1.r) * t
            });
        }
    }
    out.push({ x: pts[pts.length - 1].x, y: pts[pts.length - 1].y, r: pts[pts.length - 1].r });

    // Накопленная длина и касательная — от них считаются нормаль и фаза волны.
    let acc = 0;
    for (let i = 0; i < out.length; i++) {
        const prev = out[i - 1], next = out[i + 1];
        if (prev) acc += Math.hypot(out[i].x - prev.x, out[i].y - prev.y);
        out[i].s = acc;
        const a = prev || out[i], b = next || out[i];
        const dx = b.x - a.x, dy = b.y - a.y;
        const len = Math.hypot(dx, dy) || 1;
        out[i].nx = -dy / len;
        out[i].ny = dx / len;
    }
    return out;
}

// Гладкая кривая через набор точек: каждая точка становится контрольной, а
// стыки ставятся в серединах отрезков — классический приём, дающий
// непрерывную касательную без вычисления сплайна.
function smoothPolyline(pts, continueFromCurrent) {
    if (!pts.length) return '';
    // Координаты округляются до целых: на экране разница незаметна, а строка
    // пути (её переставляют каждый второй кадр) становится заметно короче.
    const r = v => Math.round(v);
    let d = (continueFromCurrent ? ' L ' : 'M ') + `${r(pts[0][0])},${r(pts[0][1])}`;
    for (let i = 1; i < pts.length - 1; i++) {
        d += ` Q ${r(pts[i][0])},${r(pts[i][1])} ${r((pts[i][0] + pts[i + 1][0]) / 2)},${r((pts[i][1] + pts[i + 1][1]) / 2)}`;
    }
    const last = pts[pts.length - 1];
    d += ` L ${r(last[0])},${r(last[1])}`;
    return d;
}

// Геометрия тракта: возвращает d ленты и d центральной жилы.
// bellyPoint — центр живота: вокруг него тракт сворачивается в петли.
function buildGutTractGeometry(axis, bellyPoint, cfg) {
    if (!axis.length) return { ribbon: '', core: '' };
    const total = axis[axis.length - 1].s || 1;
    const maxR = axis.reduce((m, p) => Math.max(m, p.r), 1);

    // Где по длине тракта находится живот (в единицах накопленной длины).
    let bellyS = total * 0.5, bellyR = maxR;
    if (bellyPoint) {
        let best = Infinity;
        axis.forEach(p => {
            const d = Math.hypot(p.x - bellyPoint.x, p.y - bellyPoint.y);
            if (d < best) { best = d; bellyS = p.s; bellyR = p.r; }
        });
    }
    const bellyReach = Math.max(24, bellyR * 1.9); // насколько далеко тянется зона петель

    const left = [], right = [], core = [];
    let phase = cfg.phase || 0;
    let prevS = axis[0].s;

    for (let i = 0; i < axis.length; i++) {
        const p = axis[i];
        // 0 в шее/хвосте → 1 в самом центре живота. Плавно, без ступеньки.
        const near = clamp01(1 - Math.abs(p.s - bellyS) / bellyReach);
        const belly = near * near * (3 - 2 * near); // smoothstep

        // Частота: в животе витки заметно чаще — это и читается как
        // "кишечник сложен змейкой", а не как одна волнистая труба.
        const waveLen = lerp(cfg.waveLength, cfg.waveLength / cfg.loopDensity, belly);
        phase += ((p.s - prevS) / Math.max(4, waveLen)) * Math.PI * 2;
        prevS = p.s;

        // Амплитуда ограничена радиусом тела в этой точке — тракт физически
        // не может прижаться к стенке или вылезти наружу.
        let amp = p.r * lerp(cfg.wave, cfg.bellyWave, belly);
        const off0 = Math.sin(phase);
        // Смещение петель вниз внутри живота. Кишечник занимает низ брюшной
        // полости, а верх оставляет желудку и сердцу — иначе петли ложатся
        // прямо на них, и вместо органов видно штриховку.
        const bias = p.r * (cfg.bellyBias || 0) * belly;

        // Толщина: толще в животе, сходит на нет к голове и кончику хвоста,
        // иначе труба выглядит обрубленной.
        const endFade = clamp01(Math.min(p.s, total - p.s) / (total * 0.1));
        const w = Math.max(0.6, p.r * lerp(cfg.width, cfg.bellyWidth, belly) * (0.35 + 0.65 * endFade));
        // Труба вместе со своей толщиной обязана оставаться внутри тела:
        // прижатая к стенке кишка читается как трещина на коже, а не как
        // орган под ней.
        amp = Math.min(amp, Math.max(0, p.r * 0.72 - w));
        const off = off0 * amp;

        const cx = p.x + p.nx * (off + bias), cy = p.y + p.ny * (off + bias);
        left.push([cx + p.nx * w, cy + p.ny * w]);
        right.push([cx - p.nx * w, cy - p.ny * w]);
        core.push([cx, cy]);
    }

    // Кромки собираются КРИВЫМИ, а не отрезками: ломаная на витках кишечника
    // мгновенно читается как зигзаг из палок, а не как мягкая трубка.
    const ribbon = smoothPolyline(left, false) + ' ' + smoothPolyline(right.slice().reverse(), true) + ' Z';
    // corePts — сырые точки осевой линии. Нужны, чтобы ставить куски еды на
    // тракт арифметикой, а не промером SVG-пути: строка пути переписывается
    // каждый кадр, и getTotalLength каждый раз меряет её заново.
    return { ribbon, core: smoothPolyline(core, false), corePts: core };
}

// Узлы тракта: тень под трубой → сама труба с контуром → светлая жила.
// Создаются один раз, в tick() у них меняется только атрибут d.
// thinByIdx — плотность кожи по звеньям цепи (0 = кожа непрозрачная).
//
// Тракт — одна неразрывная труба на всё тело, поэтому «сколько его видно»
// нельзя задать послойно, как у остальных органов. Вместо этого на него
// вешается маска из мягких кругов по звеньям тела: где кожа плотная (голова,
// хвост), круг почти чёрный и кишка не видна вовсе; где тонкая (живот) —
// белый, и труба просвечивает целиком.
//
// Это ровно то же правило, что и у органов, просто выраженное маской:
// органы всегда нарисованы, вопрос только в том, сколько кожи над ними.
function createGutTract(ctx, thinByIdx) {
    const anatomy = ctx.anatomy;
    const palette = (anatomy.organs && anatomy.organs.palette) || {};
    const color = palette.gut || FLESH[700];
    const group = svgEl('g', {
        class: 'worm-gut-tract',
        'clip-path': `url(#worm-hull-clip-${ctx.instanceId})`
    });

    const maskId = `worm-gut-mask-${ctx.instanceId}`;
    const mask = svgEl('mask', { id: maskId, maskUnits: 'userSpaceOnUse' });
    const softWhite = ensureSoftGradient(ctx, `worm-gut-soft-${ctx.instanceId}`, '#ffffff', 1);
    const maskCircles = (thinByIdx || []).map(thin => {
        const c = svgEl('circle', {
            cx: 0, cy: 0, r: 0, fill: softWhite,
            opacity: Math.max(0, Math.min(1, thin)).toFixed(3)
        });
        mask.appendChild(c);
        return c;
    });
    if (maskCircles.length) {
        ctx.defs.appendChild(mask);
        group.setAttribute('mask', `url(#${maskId})`);
    }
    // Отдельного узла-тени нет намеренно: строка пути тракта длинная (~3 КБ),
    // и переставлять её дважды за кадр — самая дорогая операция во всём
    // рендере. Роль тени и контура одновременно играет широкая тёмная
    // обводка самой трубы.
    const tube = svgEl('path', {
        d: '', fill: color, stroke: mixColor(color, GRIME_SHADOW, 0.55),
        'stroke-width': SW.structure, 'stroke-linejoin': 'round', opacity: 0.95
    });
    const coreLine = svgEl('path', {
        d: '', fill: 'none', stroke: mixColor(color, GRIME_HIGHLIGHT, 0.5),
        'stroke-width': SW.detail, 'stroke-linecap': 'round', opacity: 0.3
    });
    group.appendChild(tube);
    group.appendChild(coreLine);

    // Куски еды едут ВНУТРИ группы тракта, значит подчиняются той же маске:
    // у головы и хвоста кожа плотная — и комок там не виден, как и кишка.
    // Ровно то поведение, которое нужно: еда «появляется» из головы, когда
    // доезжает до просвечивающей части, и пропадает у хвоста.
    const foodLayer = svgEl('g', { class: 'worm-food-layer' });
    group.appendChild(foodLayer);

    return { group, tube, coreLine, maskCircles, foodLayer, foodNodes: [] };
}

// Пересчёт всех трёх копий силуэта + перетяжек + отражённого света + тени.
// Вызывается раз за кадр из tick(): создаётся ноль новых узлов, меняются
// только атрибуты уже существующих.
function updateBodyHull(built, circles) {
    const hull = built.hull, rings = built.rings, rim = built.rim;
    if (!hull) return;
    const W = hull.outlineWidth;

    for (let i = 0; i < hull.outlineCircles.length; i++) {
        const c = circles[i];
        const oc = hull.outlineCircles[i], cc = hull.clipCircles[i], rc = hull.rimCircles[i];
        if (!c || !(c.r > 0)) { oc.setAttribute('r', 0); cc.setAttribute('r', 0); rc.setAttribute('r', 0); continue; }
        oc.setAttribute('cx', c.x.toFixed(1)); oc.setAttribute('cy', c.y.toFixed(1)); oc.setAttribute('r', (c.r + W).toFixed(1));
        rc.setAttribute('cx', c.x.toFixed(1)); rc.setAttribute('cy', c.y.toFixed(1)); rc.setAttribute('r', (c.r + W * 0.45).toFixed(1));
        cc.setAttribute('cx', c.x.toFixed(1)); cc.setAttribute('cy', c.y.toFixed(1)); cc.setAttribute('r', c.r.toFixed(1));
    }

    // Маска кишечного тракта ходит вместе с телом: круги стоят на тех же
    // местах, что и звенья силуэта, и обновляются в том же цикле, чтобы
    // «сколько видно кишку» не отставало от движения на кадр.
    const gutMask = built.gutTract && built.gutTract.maskCircles;
    if (gutMask) {
        for (let i = 0; i < gutMask.length; i++) {
            const c = circles[i];
            const mc = gutMask[i];
            if (!mc) continue;
            if (!c || !(c.r > 0)) { mc.setAttribute('r', 0); continue; }
            mc.setAttribute('cx', c.x.toFixed(1));
            mc.setAttribute('cy', c.y.toFixed(1));
            // Чуть шире звена: соседние круги должны перекрываться, иначе на
            // стыках появятся тёмные перехваты — кишка будет «пунктиром».
            mc.setAttribute('r', (c.r * 1.5).toFixed(1));
        }
    }

    for (let i = 0; i < hull.bridgeShapes.length; i++) {
        const a = circles[i], b = circles[i + 1];
        const ob = hull.outlineBridges[i], cb = hull.clipBridges[i], bs = hull.bridgeShapes[i], rb = hull.rimBridges[i];
        if (!a || !b || !(a.r > 0) || !(b.r > 0)) {
            ob.setAttribute('d', ''); cb.setAttribute('d', ''); bs.setAttribute('d', ''); rb.setAttribute('d', '');
            continue;
        }
        // ТАЛИЯ: мост уже соседних кругов. Без неё тело превращается в ровную
        // трубу постоянной ширины — сегменты перестают читаться как отдельные
        // вздутия, и силуэт выглядит надувным матрасом. Отрицательный отступ и
        // есть та самая перетяжка между секциями.
        const waist = -Math.min(a.r, b.r) * WORM_HULL_WAIST_RATIO;
        ob.setAttribute('d', bridgeQuadPath(a, b, waist + W));
        rb.setAttribute('d', bridgeQuadPath(a, b, waist + W * 0.45));
        const plain = bridgeQuadPath(a, b, waist);
        cb.setAttribute('d', plain);
        bs.setAttribute('d', plain);
        // Цвет моста — среднее между соседями, поэтому переход тона по телу
        // остаётся непрерывным и промежуток не выглядит "заплаткой".
        if (a.color && b.color) bs.setAttribute('fill', mixColor(a.color, b.color, 0.5));
    }

    // Перетяжки: ставятся в точку касания соседних кругов и разворачиваются
    // поперёк оси тела. Толщина валика — от размера меньшего из соседей.
    for (let i = 0; i < rings.rings.length; i++) {
        const a = circles[i + 1], b = circles[i + 2];
        const r = rings.rings[i];
        if (!a || !b || !(a.r > 0) || !(b.r > 0)) { r.g.setAttribute('opacity', 0); continue; }
        r.g.setAttribute('opacity', 1);
        const dx = b.x - a.x, dy = b.y - a.y;
        const dist = Math.hypot(dx, dy) || 1;
        const t = (a.r + (dist - a.r - b.r) * 0.5) / dist; // середина перекрытия
        const px = a.x + dx * t, py = a.y + dy * t;
        const deg = Math.atan2(dy, dx) * 180 / Math.PI;
        const half = Math.min(a.r, b.r) * (1 - WORM_HULL_WAIST_RATIO) * 1.06;
        const w = Math.max(2.4, half * 0.26);
        r.shade.setAttribute('ry', half.toFixed(1)); r.shade.setAttribute('rx', w.toFixed(1));
        r.light.setAttribute('ry', (half * 0.96).toFixed(1)); r.light.setAttribute('rx', (w * 0.6).toFixed(1));
        r.light.setAttribute('cx', (w * 1.15).toFixed(1));
        r.crease.setAttribute('ry', (half * 0.99).toFixed(1)); r.crease.setAttribute('rx', Math.max(1.2, w * 0.42).toFixed(1));
        r.g.setAttribute('transform', `translate(${px.toFixed(1)},${py.toFixed(1)}) rotate(${deg.toFixed(1)})`);
    }

    // Тень на полу — по нижнему краю напольной части.
    if (built.floorShadow) {
        let minX = Infinity, maxX = -Infinity, bottom = -Infinity;
        circles.forEach(c => {
            if (!c || !(c.r > 0)) return;
            minX = Math.min(minX, c.x - c.r); maxX = Math.max(maxX, c.x + c.r);
            bottom = Math.max(bottom, c.y + c.r);
        });
        if (minX < maxX) {
            built.floorShadow.setAttribute('cx', ((minX + maxX) / 2).toFixed(1));
            built.floorShadow.setAttribute('cy', (bottom + 4).toFixed(1));
            built.floorShadow.setAttribute('rx', ((maxX - minX) / 2 + 10).toFixed(1));
            built.floorShadow.setAttribute('ry', '11');
        }
    }
}

function buildWormSVGGroup(model, instanceId) {
    const root = svgEl('g', { class: 'worm-root' });

    // Общий <defs> на весь инстанс персонажа — сюда складываются все
    // градиенты и клипы (голова, сегменты, хвост, уши, глаза, анатомия).
    const defs = svgEl('defs');
    root.appendChild(defs);

    const anatomy = getAnatomy(model);
    // Контекст инстанса: всё, что нужно любому строителю слоя. Передаётся
    // одним объектом, чтобы не тащить 5 аргументов через каждую функцию.
    const ctx = { defs, instanceId, anatomy, gradCache: Object.create(null), neckColor: null,
                  // Сколько растущих сегментов у этой особи: от этого зависит
                  // рампа прозрачности кожи вдоль тела.
                  growingCount: (model.growingSegments || []).length,
                  // база для отражённого света: тёплый оттенок самой кожи,
                  // а не производная от тёмного контура (иначе кайма выходит
                  // грязно-бежевой и читается как ореол, а не как свет)
                  rimBaseColor: model.belly.fill };

    // Порядок цепочки от головы к хвосту: 2 фикс. сегмента, живот, N
    // растущих сегментов, хвост.
    const chainParts = [];
    model.fixedSegments.forEach((seg, i) => chainParts.push({ name: `segment-${i + 1}`, data: seg }));
    const bellyIdx = model.fixedSegments.length + 1;
    chainParts.push({ name: 'belly', data: model.belly });
    model.growingSegments.forEach((seg, i) => chainParts.push({ name: `growing-${i + 1}`, data: seg }));

    const totalWithTail = chainParts.length + 1; // +1 за хвост
    const tailIdx = totalWithTail;

    // Реальный отрисованный радиус последнего (предхвостового) growing-
    // сегмента — от него считается основание хвоста.
    const lastGrowingSeg = model.growingSegments.length
        ? model.growingSegments[model.growingSegments.length - 1]
        : null;
    const tailAttachRadius = lastGrowingSeg
        ? lastGrowingSeg.radius * lastGrowingSeg.stretchX * lastGrowingSeg.scale
        : 15;

    // ---------- ПЕРЕХОД ЧЕРВЬ → ГОЛОВА: ПОДМЕШИВАНИЕ ЦВЕТА ШЕИ ----------
    // Цвет сегментов-шеи подмешивается к цвету головы, а сама голова снизу
    // получает "юбку" цветом сегмента-1 — стык перестаёт быть границей двух
    // разных существ. Модель при этом не меняется: подмешивает рендерер.
    const neckBlend = (anatomy.enabled && anatomy.skin && anatomy.skin.neckBlend) || null;
    const blendByPart = Object.create(null);
    if (neckBlend) {
        model.fixedSegments.forEach((seg, i) => {
            const amt = neckBlend[i];
            if (amt == null || amt <= 0) return;
            blendByPart[`segment-${i + 1}`] = {
                fill: mixColor(seg.fill, model.head.fill, amt),
                stroke: mixColor(seg.stroke, model.head.stroke, amt * 0.7)
            };
        });
        const seg1 = blendByPart['segment-1'];
        ctx.neckColor = seg1 ? seg1.fill : model.fixedSegments[0].fill;
    }

    // Zона анатомии по имени части — задаётся ОДИН раз здесь, чтобы правила
    // "что где просвечивает" не были размазаны по коду.
    function partAnatOpts(name, idx) {
        const isVertical = idx <= bellyIdx - 1; // сегменты между головой и животом
        const opts = {
            axis: isVertical ? 'y' : 'x',
            organZone: null,
            coat: { rings: true, vessel: !isVertical },
            surface: {}
        };
        if (name === 'belly') {
            opts.organZone = 'core';
            opts.axis = 'x';       // живот лежит на полу, растёт "вперёд" по X
            opts.coat.vessel = true;
        } else if (name === 'segment-1') {
            opts.organZone = 'neck';
            opts.coat.folds = true;    // свиные складки у "плеча"
            opts.coat.bristle = true;  // и щетина — ближе к голове кожа свиная
            opts.coat.rings = true;
            opts.surface.contactTop = true; // тень от головы, лежащей сверху
        } else if (name === 'segment-2') {
            opts.organZone = 'neck';
            opts.coat.folds = true;
            opts.coat.clitellum = true; // поясок-воротник: граница двух типов кожи
            opts.surface.contactTop = true;
            opts.surface.contactStrength = 0.5;
        } else if (name.indexOf('growing-') === 0) {
            opts.organZone = 'floor';
        }
        return opts;
    }

    // Z-порядок ("слои", как в фотошопе), СНИЗУ ВВЕРХ:
    // 1) напольная часть (growing-сегменты + хвост) — самый нижний слой;
    // 2) вертикальная часть тела (fixedSegments, между головой и животом);
    // 3) живот — поверх ВСЕХ остальных сегментов тела;
    // 4) голова — поверх абсолютно всего, рисуется отдельным шагом ниже.
    // Сторона (напольная / вертикальная / живот) — ПЕРВЫЙ, приоритетный
    // критерий сортировки, "расстояние от живота" — только второй.
    const allParts = chainParts.map((part, i) => ({ ...part, idx: i + 1, isTail: false }));
    allParts.push({ name: 'tail', data: model.tail, idx: tailIdx, isTail: true });
    function bodyLayerGroup(idx) {
        if (idx === bellyIdx) return 2;       // живот
        return idx > bellyIdx ? 0 : 1;        // 0 = напольная часть, 1 = вертикальная часть тела
    }
    allParts.sort((a, b) => {
        const groupA = bodyLayerGroup(a.idx);
        const groupB = bodyLayerGroup(b.idx);
        if (groupA !== groupB) return groupA - groupB;
        const distA = Math.abs(a.idx - bellyIdx);
        const distB = Math.abs(b.idx - bellyIdx);
        if (distA !== distB) return distB - distA;
        return a.idx - b.idx;
    });

    // ---------- ЕДИНЫЙ СИЛУЭТ: СЛОИ ПОД ТЕЛОМ ----------
    // Цепочка кругов силуэта: якорь внутри головы (чтобы шея входила в неё
    // без стыка) → сегменты → живот → растущие → основание хвоста.
    const hullCount = 1 + model.fixedSegments.length + 1 + model.growingSegments.length + 1;
    const outlineColor = mixColor(model.belly.stroke, GRIME_SHADOW, 0.25);
    const hull = createHullLayers(ctx, hullCount, outlineColor, SW.contour);
    const rings = createRingLayers(ctx, Math.max(0, hullCount - 2));

    // Падающая тень на "полу" — тело перестаёт висеть в пустоте.
    const floorShadow = svgEl('ellipse', {
        class: 'worm-floor-shadow', cx: 0, cy: 0, rx: 0, ry: 0,
        fill: ensureSoftGradient(ctx, `worm-floor-shadow-${instanceId}`, INK, 1),
        opacity: 0.34,
        // Тень загораживать пол не должна: тело — да, его тень — нет.
        // Иначе радиус «мёртвой зоны» вокруг червя вдвое больше него самого.
        'pointer-events': 'none'
    });
    root.appendChild(floorShadow);
    root.appendChild(hull.outline);
    root.appendChild(hull.rimGroup);
    root.appendChild(hull.bridges);

    const segmentRefs = [];
    const organRefs = [];   // плоский список всех органов — для дешёвого tick()
    const muscleRefs = [];
    let tailBuilt = null;
    allParts.forEach(part => {
        if (part.isTail) {
            tailBuilt = buildTailNode(part.data, ctx, tailAttachRadius);
            root.appendChild(tailBuilt.group);
            if (tailBuilt.anat) {
                tailBuilt.anat.organs.forEach(o => organRefs.push(o));
                if (tailBuilt.anat.muscleGroup) muscleRefs.push(tailBuilt.anat.muscleGroup);
            }
        } else {
            const anatOpts = partAnatOpts(part.name, part.idx);
            const blend = blendByPart[part.name];
            const built = buildSegmentNode(part.name, part.data, ctx, {
                axis: anatOpts.axis,
                organZone: anatOpts.organZone,
                coat: anatOpts.coat,
                surface: anatOpts.surface,
                blendFill: blend ? blend.fill : null,
                blendStroke: blend ? blend.stroke : null
            });
            root.appendChild(built.group);
            segmentRefs.push({ idx: part.idx, name: part.name, radius: part.data.radius * part.data.scale, ...built });
            if (built.anat) {
                built.anat.organs.forEach(o => organRefs.push(o));
                if (built.anat.muscleGroup) muscleRefs.push(built.anat.muscleGroup);
            }
        }
    });

    // Кишечный тракт — поверх заливки тела (он просвечивает сквозь кожу),
    // но ПОД перетяжками и головой. Живёт на уровне всего тела, а не внутри
    // сегментов: иначе его невозможно сделать неразрывным.
    let gutTract = null;
    if (anatomy.enabled && anatomy.organs && (anatomy.organs.visibility || 0) > 0.01) {
        // Плотность кожи по звеньям цепи: 0 — голова, дальше сегменты по
        // своим индексам, последним хвост. Маска тракта строится по ней.
        const thinByIdx = new Array(tailIdx + 1).fill(0);
        thinByIdx[0] = anatThinness(anatomy, 'head', ctx.growingCount);
        allParts.forEach(part => {
            thinByIdx[part.idx] = anatThinness(anatomy, part.name, ctx.growingCount);
        });
        gutTract = createGutTract(ctx, thinByIdx);
        root.appendChild(gutTract.group);
    }

    // Перетяжки — поверх тела, но ПОД головой: они принадлежат туше, а не
    // морде. (Отражённый свет живёт ниже, в hull.rimGroup — ему нужно быть
    // ПОД телом, чтобы наружу выходила только кайма.)
    root.appendChild(rings.group);

    // Голова — последняя, поверх всего.
    const headBuilt = buildHeadNode(model, ctx);
    root.appendChild(headBuilt.group);

    // Отметины — монтируются как дети scarLayer конкретной части, поэтому
    // автоматически наследуют её текущий transform/scale: тело шевелится,
    // шрамы шевелятся вместе с ним, без единой строчки в анимации.
    //
    // Где именно сидит отметина, решает WormMarks по зоне и позиции вдоль
    // неё — не по имени сегмента. Имена растущих сегментов меняются при
    // взрослении, а «середина хвостовой части» остаётся собой.
    const scarHostByPart = { head: headBuilt.scarLayer, tail: tailBuilt.scarLayer };
    const radiusByPart = { head: headBuilt.rx, tail: tailBuilt.baseRadius };
    const skinByPart = { head: model.head.fill, tail: model.tail.fill };
    segmentRefs.forEach(seg => {
        scarHostByPart[seg.name] = seg.scarLayer;
        radiusByPart[seg.name] = seg.radius;
        skinByPart[seg.name] = seg.fillColor;
    });

    WormMarks.ZONES.forEach(zone => {
        WormMarks.visible(model.scars, zone).forEach(mark => {
            const place = WormMarks.resolve(model, mark);
            const host = scarHostByPart[place.part];
            if (!host) return;
            host.appendChild(buildMarkNode(mark, place, radiusByPart[place.part] || 15, skinByPart[place.part]));
        });
    });

    return {
        root,
        totalWithTail,
        tail: { ...tailBuilt, idx: tailIdx },
        segments: segmentRefs,
        head: headBuilt,
        organs: organRefs,
        muscles: muscleRefs,
        hull, rings, floorShadow, gutTract,
        anatomy
    };
}

// ---------- ПУБЛИЧНЫЙ API РЕНДЕРЕРА ----------
const WormRenderer = {
    mount(container, model, opts) {
        opts = Object.assign({
            context: 'main',
            // Рисовать комнату с полом в перспективе и масштабировать
            // персонажа по глубине. Только для главного экрана: мини-игры
            // ставят свои сцены сами.
            room: false,
            wander: false,
            blink: true,
            anchorX: 0.5,
            anchorY: 0.55,
            // Зеркалит всю модельку по горизонтали — цепочка тела тогда
            // растёт вправо от головы, а не влево.
            flip: false,
            // false — тело неподвижно застыло в базовой позе (нужно для
            // сцен, где персонаж лежит смирно, например кормление).
            idleWave: true,
            // 'center' (по умолчанию) — живот раздувается симметрично.
            // 'bottom' — нижний край живота остаётся на месте, раздувается
            // только вверх. 'top' — наоборот.
            bellyGrowthAnchor: 'center',
            // 'standing' (по умолчанию) / 'lying' (Чревоугодие).
            pose: 'standing'
        }, opts || {});
        const instanceId = ++wormInstanceCounter;

        container.innerHTML = '';
        const svg = svgEl('svg', { class: `worm-stage-svg worm-context-${opts.context}` });
        svg.style.width = '100%';
        svg.style.height = '100%';
        svg.style.display = 'block';
        svg.style.overflow = 'visible';
        container.appendChild(svg);

        // Постоянные слои внутри svg, которые НЕ трогает rebuild():
        //   roomLayer   — интерьер (пол, стены), самый низ;
        //   slimeLayer  — след слизи;
        //   objectLayer — то, что лежит на полу (кучки);
        //   charLayer   — сам персонаж, поверх всего.
        //
        // Предметы лежат ВЫШЕ слизи: след — это то, что червь размазал по
        // полу, он физически не может оказаться поверх кучки.
        //
        // И это отдельный слой, а не часть roomLayer: комната перестраивается
        // при смене размера окна, а buildRoom вычищает свой слой целиком —
        // предметы уезжали вместе с ней и пропадали с экрана, оставаясь в
        // состоянии. Именно так кучка и превращалась в невидимую.
        const roomLayer = svgEl('g', { class: 'worm-room-layer' });
        // След слизи тянется через полкомнаты и тапы ловить не должен:
        // он не тело, а то, что тело за собой оставило.
        const slimeLayer = svgEl('g', { class: 'worm-slime-layer', 'pointer-events': 'none' });
        const objectLayer = svgEl('g', { class: 'worm-room-objects' });
        const charLayer = svgEl('g', { class: 'worm-char-layer' });
        // Все слои мира лежат в общей обёртке, и двигает её КАМЕРА. Комната
        // шире экрана (см. ROOM.widthRatio), экран — окно в неё.
        //
        // Одна обёртка, а не сдвиг координат в каждом слое: комната, слизь,
        // предметы и персонаж обязаны ехать СТРОГО вместе, иначе кучка
        // «отстанет» от пола на полкадра при быстром свайпе. Заодно это
        // единственное место, где вообще существует камера: вся остальная
        // математика живёт в координатах комнаты и про неё не знает.
        // ---------- ФИЛЬТР ИСТОЩЕНИЯ ----------
        // Обесцвечивание сделано РОДНЫМ SVG-фильтром, а не CSS-свойством
        // filter, и это не вкусовщина.
        //
        // Сначала стоял CSS-фильтр на слое персонажа. В Chromium он работал, а
        // на айфоне — нет: WebKit не применяет CSS filter к внутренним
        // элементам SVG (к <g>), только к самому корню или к HTML-элементу.
        // Выглядело это так, что червь при нуле шкал и даже мёртвый оставался
        // розовым, хотя поза менялась правильно — то есть трансформации
        // доезжали, а цвет нет. Родной <filter> в этом месте работает везде.
        //
        // Яркость отдельной ступенью: feColorMatrix умеет только насыщенность,
        // а обескровленный червь должен ещё и темнеть.
        const witherFilterId = `worm-wither-${instanceId}`;
        const witherDefs = svgEl('defs');
        const witherFilter = svgEl('filter', {
            id: witherFilterId,
            // Фильтр не должен обрезать тело: по умолчанию область всего 110%
            // от габарита, а у червя за него выходят и тень, и след слизи.
            x: '-25%', y: '-25%', width: '150%', height: '150%',
            'color-interpolation-filters': 'sRGB'
        });
        const witherSat = svgEl('feColorMatrix', { type: 'saturate', values: '1' });
        const witherBright = svgEl('feComponentTransfer');
        const witherFuncs = ['feFuncR', 'feFuncG', 'feFuncB'].map(tag => {
            const f = svgEl(tag, { type: 'linear', slope: '1', intercept: '0' });
            witherBright.appendChild(f);
            return f;
        });
        witherFilter.appendChild(witherSat);
        witherFilter.appendChild(witherBright);
        witherDefs.appendChild(witherFilter);
        svg.appendChild(witherDefs);

        const worldLayer = svgEl('g', { class: 'worm-world-layer' });
        if (opts.room) worldLayer.appendChild(roomLayer);
        worldLayer.appendChild(slimeLayer);
        worldLayer.appendChild(objectLayer);
        worldLayer.appendChild(charLayer);
        svg.appendChild(worldLayer);

        const state = {
            // Какая локация нарисована. Живёт в state, а не в opts: её меняют
            // на ходу (setLocation), а opts — то, с чем смонтировали.
            location: opts.location || (typeof RoomLocations !== 'undefined'
                ? RoomLocations.DEFAULT : null),
            baseModel: model,
            override: null,
            built: null,
            animTime: 0,
            wormX: 0,
            wormY: 0,
            targetX: 0,
            targetY: 0,
            // Куда червь СМОТРИТ на ходу (радианы). null = стоит. Отдельно от
            // направления на цель: именно расхождение между ними и даёт дугу
            // при смене цели на ходу.
            heading: null,
            // Истощение: 1 = здоров (фильтр снят), меньше — обесцвечен.
            // Показанное значение догоняет цель за кадры, поэтому смерть не
            // обесцвечивает червя рывком.
            witherTarget: 1,
            witherShown: 1,
            // Камера: на сколько единиц комнаты окно сдвинуто вправо.
            camX: 0,
            camManualUntil: 0,   // до этого момента слежение молчит
            drag: null,          // текущий свайп
            // Измеренный габарит тела и допустимый диапазон глубин. null =
            // «пересчитать»: сбрасывается при пересборке тела и смене размера.
            bodyBox: null,
            wanderD: null,
            blinkClock: 0,
            faceClock: 0,
            rafId: null,
            lastFrameTs: null,
            // 0 = стоит на месте, 1 = идёт — рычаг интенсивности ТОЛЬКО
            // виляния.
            moveIntensity: 0,
            // 0..1 — от ФАКТИЧЕСКОЙ мгновенной скорости перемещения.
            speedIntensity: 0,
            nextMoveAt: null,
            // Аккумуляторы фазы: покачивание цепи, "флик" кончика хвоста и
            // пульсация внутренних органов. НЕ путать с animTime: эти поля
            // прирастают ТЕКУЩЕЙ скоростью каждый кадр, а не умножаются на
            // неё постфактум (см. блок про "эффект волчка" у констант).
            chainWigglePhase: 0,
            tailWagPhase: 0,
            organPhase: 0,
            gutPhase: 0,
            gutSkipFrame: false,
            // ---------- ПЛАВНЫЙ ПОВОРОТ ГОЛОВЫ ----------
            // headYawCurrent — то, что реально нарисовано сейчас;
            // headYawTarget — куда едем. Ось непрерывная (механизм), а
            // именованные позы (словарь) просто задают цель. Так остаются
            // открыты обе двери: и щелчок между тремя позами, и плавное
            // слежение головой за чем-нибудь.
            headYawCurrent: null,
            headYawTarget: null,
            // Экранный угол хвостовой части. 180° = хвост влево, как было
            // всегда до появления ориентации; это же значение и стартовое,
            // поэтому неподвижный червь выглядит ровно как раньше.
            tailAngle: 180,
            room: null,
            depthScale: 1,
            floorLocalY: 0,
            // Голова по умолчанию сама следит за направлением ползания.
            // setHeadPose() перехватывает управление, setHeadPose('auto')
            // возвращает автоматику.
            headYawAuto: true,
            activeSlimeTrail: null,
            slimeTrails: [],
            // "Горячий" канал для непрерывных обновлений от мини-игр — не
            // трогает baseModel/override, не вызывает пересборку SVG.
            livePose: {
                tailBendAngle: 0,   // градусы поворота хвоста вокруг точки крепления
                eyelidLevel: null,  // 0..1 — подменяет базовый уровень век обоих глаз
                // 0..1 — нижнее веко, «улыбающийся глаз»: щека поджимает глаз
                // СНИЗУ, край выгнут вверх. Отдельно от eyelidLevel, потому
                // что прищур сверху и снизу читаются совершенно по-разному.
                eyeSmile: null,
                bellyScale: null,   // множитель радиуса живота (1 = обычный)
                mouthOpenness: null, // 0..1 — подменяет head.mouth.openness
                mouthCurve: null,    // подменяет head.mouth.curve
                // Жидкость во рту: 0..1 — насколько полость налита, и каким
                // цветом. Часть рта, а не наклейка поверх морды: едет,
                // размывается и обрезается губами вместе с ним. Пустой рот
                // прозрачен, так что канал ничего не стоит, пока не нужен.
                mouthFill: null,
                mouthFillColor: null,
                // Анатомические "живые" каналы — устроены ровно так же, как
                // всё остальное тело: null = брать из модели/оверрайда.
                // organPulseScale — множитель амплитуды пульсации органов
                // (например, "сытое" бурление после кормления или замирание
                // при испуге); organVisibility — временная подмена степени
                // просвечивания органов (кожа натянулась — видно лучше).
                organPulseScale: null,
                organVisibility: null,

                // ---------- МИМИКА ----------
                // Всё опционально: null = "не вмешиваюсь, работает
                // собственная жизнь персонажа" (см. idle-мимику в tick).
                headTilt: null,      // градусы наклона головы вокруг основания шеи
                // Поворот головы. null = брать из модели. Живой канал, а не
                // setOverride: setOverride пересобирает всю голову заново и
                // для покадровой анимации не годится.
                headYaw: null,
                gazeX: null,         // -1..1 — куда смотрит (доля от размера глаза)
                gazeY: null,
                browRaise: null,     // -1..1 — брови вниз (хмурится) / вверх (удивлён)
                earTilt: null,       // градусы к базовому развороту обоих ушей
                earTiltLeft: null,   // то же по отдельности
                earTiltRight: null,
                snoutTwitch: null,   // 0..1 — принюхивается
                cheekPuff: null,     // 0..1 — щёки надуты (например, полный рот)
                jawDrop: null        // 0..1 — челюсть опущена; по умолчанию следует за ртом
            }
        };

        function mergedModel() {
            return window.WormModelAPI.mergeWormOverride(state.baseModel, state.override);
        }

        function syncViewportSize() {
            // Размер БЕЗ учёта трансформаций (clientWidth, а не
            // getBoundingClientRect): вся игра живёт в холсте постоянного
            // размера, который масштабируется одной CSS-трансформацией
            // (src/core/stage.js). Меряя экранные пиксели, рендерер получал
            // бы разные числа на каждом экране и пересобирал бы комнату при
            // любом изменении масштаба — ради картинки, которая всё равно
            // отличается только увеличением.
            const w = Math.max(1, container.clientWidth || container.getBoundingClientRect().width);
            const h = Math.max(1, container.clientHeight || container.getBoundingClientRect().height);
            svg.setAttribute('viewBox', `0 0 ${w} ${h}`);
            if (opts.room) {
                state.room = roomGeometry(w, h);
                buildRoom(roomLayer, state.room, state.location);
                state.wanderD = null;   // комната изменилась — границы пересчитать
                // Стартовая точка — на полу, а не в произвольной доле высоты:
                // иначе персонаж при запуске стоит в воздухе или в стене.
                if (!state.wormX) state.wormX = state.room.cx;
                if (!state.wormY) state.wormY = roomYAt(state.room, 1.1) - state.floorLocalY;
            }
            state.wormX = state.wormX || w * opts.anchorX;
            state.wormY = state.wormY || h * opts.anchorY;
            state.targetX = state.wormX;
            state.targetY = state.wormY;

            // Камера: держим червя в окне и не даём ей уехать за края комнаты
            // (размер окна изменился — прежний сдвиг мог стать недопустимым).
            if (opts.room && state.room) {
                setCam(state.camX || (state.wormX - state.room.w / 2));
                worldLayer.setAttribute('transform', `translate(${(-state.camX).toFixed(1)},0)`);
            }
        }

        function rootTransform() {
            const flipPart = opts.flip ? ' scale(-1,1)' : '';
            const sc = state.depthScale;
            if (!opts.room || Math.abs(sc - 1) < 0.001) {
                return `translate(${state.wormX.toFixed(1)},${state.wormY.toFixed(1)})${flipPart}`;
            }
            // Масштабировать надо ВОКРУГ ТОЧКИ КАСАНИЯ ПОЛА, а не вокруг
            // начала координат (оно в голове). При масштабировании от головы
            // тело подтягивается к ней, и уменьшенный персонаж повисает над
            // полом вместо того, чтобы уйти вглубь комнаты.
            const F = state.floorLocalY;
            const shift = F * (1 - sc);
            return `translate(${state.wormX.toFixed(1)},${(state.wormY + shift).toFixed(1)}) ` +
                   `scale(${sc.toFixed(4)})${flipPart}`;
        }

        // ---------- ГДЕ ЧЕРВЮ МОЖНО СТОЯТЬ ----------
        // Габарит тела относительно ТОЧКИ КАСАНИЯ ПОЛА, в экранных единицах.
        // Именно он, а не подобранная константа, задаёт границы выгула: червь
        // растёт с возрастом, и любой зашитый отступ рано или поздно
        // перестал бы совпадать с телом.
        //
        // getBBox() заставляет браузер посчитать раскладку SVG, поэтому
        // измерение кешируется: тело меняет габарит только при пересборке.
        // Перемер габарита. Одного замера мало: тело дышит, заваливается и
        // водит хвостом, поэтому мгновенный getBBox() — это снимок одной позы,
        // и по нему червь вылезал за нижнюю кромку примерно на два десятка
        // единиц. Копим ОГИБАЮЩУЮ по максимуму: она сходится к настоящему
        // размаху за несколько секунд и дальше не растёт.
        function measureBody() {
            if (!state.built) return false;
            let B;
            try { B = state.built.root.getBBox(); } catch (err) { return false; }
            if (!B || !B.width) return false;

            const old = state.bodyBox;
            if (!old) { state.bodyBox = { x: B.x, y: B.y, width: B.width, height: B.height }; return true; }

            const x0 = Math.min(old.x, B.x);
            const y0 = Math.min(old.y, B.y);
            const x1 = Math.max(old.x + old.width, B.x + B.width);
            const y1 = Math.max(old.y + old.height, B.y + B.height);
            const grew = (x0 < old.x - 0.5) || (y0 < old.y - 0.5) ||
                         (x1 > old.x + old.width + 0.5) || (y1 > old.y + old.height + 0.5);
            state.bodyBox = { x: x0, y: y0, width: x1 - x0, height: y1 - y0 };
            return grew;
        }

        function bodyFootprint(sc) {
            if (!state.bodyBox) measureBody();
            const B = state.bodyBox;
            const F = state.floorLocalY;
            if (!B || !B.width) return { left: 0, right: 0, up: 0, down: 0 };
            return {
                left: B.x * sc,                        // от точки касания влево (число ≤ 0)
                right: (B.x + B.width) * sc,           // вправо
                up: (F - B.y) * sc,                    // насколько тело выше касания
                down: (B.y + B.height - F) * sc        // и насколько ниже
            };
        }

        // Диапазон глубин, на которых тело помещается в кадр ЦЕЛИКОМ: у
        // ближнего края его нижняя кромка не должна вываливаться за низ
        // экрана, у дальнего — макушка за верх коробки.
        //
        // Считается перебором, а не формулой: масштаб персонажа приглушён
        // (charScaleStrength), поэтому зависимость габарита от глубины
        // нелинейная и в одну строку не выражается. Полсотни шагов раз в
        // пересборку — цена, которой не видно.
        function refreshWanderRange() {
            const g = state.room;
            if (!g || !state.built || !state.floorLocalY) return;
            const M = ROOM.wanderMargin;
            const topLimit = g.backY - g.wallH * g.farScale + M;   // верхняя кромка коробки
            const bottomLimit = g.frontY - M;                      // низ кадра

            let min = null, max = null;
            for (let d = ROOM.wanderNear; d <= ROOM.wanderFar + 1e-6; d += 0.05) {
                const sc = roomCharScaleAt(d);
                const y = roomYAt(g, d);
                const fp = bodyFootprint(sc);
                // Помещается по вертикали в кадр И имеет куда шагнуть вбок.
                const span = 2 * (roomHalfAt(g, d) - M) - (fp.right - fp.left);
                const fits = (y + fp.down <= bottomLimit) &&
                             (y - fp.up >= topLimit) &&
                             (span >= ROOM.wanderMinSpan);
                if (fits) {
                    if (min === null) min = d;
                    max = d;
                }
            }
            // Не поместился нигде (крошечная комната, огромный червь) — не
            // запираем его в точке, а оставляем прежние рамки: пусть лучше
            // немного вылезет, чем застынет на месте.
            state.wanderD = (min === null)
                ? { min: ROOM.wanderNear, max: ROOM.wanderFar }
                : { min, max };
        }

        // Ближайшая точка пола, где червь помещается целиком. Через неё
        // проходят И случайная прогулка, И тап игрока — поэтому уйти за край
        // нельзя ни одним из способов.
        function clampFloorPoint(fx, fy) {
            const g = state.room;
            if (!g) return { x: fx, y: fy };
            if (!state.wanderD) refreshWanderRange();
            const range = state.wanderD || { min: ROOM.wanderNear, max: ROOM.wanderFar };

            const d = Math.min(Math.max(roomDepthAt(g, fy), range.min), range.max);
            const sc = roomCharScaleAt(d);
            const fp = bodyFootprint(sc);

            // Вбок: габарит тела должен уместиться в ширину пола НА ЭТОЙ
            // глубине. Пол сужается вглубь, поэтому проверять надо там, где
            // червь стоит, а не у переднего края.
            const half = roomHalfAt(g, d) - ROOM.wanderMargin;
            const lo = g.cx - half - fp.left;
            const hi = g.cx + half - fp.right;
            const x = (hi < lo) ? g.cx : Math.min(Math.max(fx, lo), hi);

            return { x, y: roomYAt(g, d) };
        }

        // ---------- КАМЕРА ----------
        // Комната шире экрана, экран — окно в неё. Здесь единственное место,
        // где камера вообще существует: вся остальная математика живёт в
        // координатах комнаты и про окно не знает.
        function setCam(x) {
            const g = state.room;
            if (!g) return;
            const next = Math.min(Math.max(x, 0), g.panMax);
            if (Math.abs(next - state.camX) < 0.01) return;
            state.camX = next;
            worldLayer.setAttribute('transform', `translate(${(-next).toFixed(1)},0)`);
        }

        // Слежение за червём с мёртвой зоной. Камера стоит, пока он гуляет по
        // середине окна, и подъезжает, только когда он подходит к краю.
        // Иначе комната мелко трясётся вслед за каждым его шагом.
        function followCam(dtSec, now) {
            const g = state.room;
            if (!g || !g.panMax || now < state.camManualUntil || state.drag) return;

            const dead = g.w * CAM_DEAD_ZONE;
            const rel = state.wormX - state.camX;          // положение червя в окне
            let want = state.camX;
            if (rel < dead) want = state.wormX - dead;
            else if (rel > g.w - dead) want = state.wormX - (g.w - dead);
            want = Math.min(Math.max(want, 0), g.panMax);

            if (Math.abs(want - state.camX) < 0.5) return;
            setCam(state.camX + (want - state.camX) * (1 - Math.pow(CAM_FOLLOW_BASE, dtSec)));
        }

        // Экранные координаты → единицы КОМНАТЫ. Через getBoundingClientRect,
        // а не через clientWidth: вся игра живёт в холсте постоянного размера,
        // который масштабируется CSS-трансформацией, и без этого деления тап
        // уезжал бы тем сильнее, чем крупнее экран. Плюс сдвиг камеры: экран
        // показывает не начало комнаты, а её кусок.
        function toRoom(e) {
            const r = svg.getBoundingClientRect();
            if (!r.width || !r.height || !state.room) return null;
            return {
                x: (e.clientX - r.left) / r.width * state.room.w + state.camX,
                y: (e.clientY - r.top) / r.height * state.room.h
            };
        }

        // ---------- СВАЙП ИЛИ ТАП ----------
        // Одно касание значит одно из двух, и различает их только пройденное
        // расстояние: увёл палец вбок — панорама, отпустил на месте — «иди
        // сюда». Порог обязателен: палец никогда не стоит идеально, и без него
        // каждый тап заодно сдвигал бы камеру и сам себя отменял.
        //
        // Что тапом НЕ является:
        //   • предметы на полу — у них свой обработчик со stopPropagation
        //     (кучку убирают, а не идут к ней);
        //   • сам червь — тап по нему остаётся свободным под будущее «повозиться».
        function onStageDown(e) {
            if (!opts.tapToWalk || !opts.wander || !state.room) return;
            // Панорама начинается ОТКУДА УГОДНО, включая самого червя: палец
            // ложится куда пришёлся, и запрещать свайп с его спины значило бы
            // ловить «камера не двигается» на ровном месте. А вот «иди сюда»
            // с червя или с кучки не считается — у них своя роль.
            const t = e.target;
            const onBusy = !!(t && t.closest &&
                (t.closest('.worm-char-layer') || t.closest('.worm-room-objects')));
            state.drag = {
                id: e.pointerId, startX: e.clientX, camAt: state.camX,
                moved: false, tappable: !onBusy
            };
            try { svg.setPointerCapture(e.pointerId); } catch (err) { /* мышь без захвата */ }
        }

        function onStageMove(e) {
            const d = state.drag;
            if (!d || e.pointerId !== d.id || !state.room) return;
            const r = svg.getBoundingClientRect();
            if (!r.width) return;
            // Экранный сдвиг пальца → сдвиг в единицах комнаты.
            const dx = (e.clientX - d.startX) / r.width * state.room.w;
            if (!d.moved && Math.abs(dx) < CAM_DRAG_THRESHOLD) return;
            d.moved = true;
            // Комната едет ЗА пальцем: тянешь влево — открывается правая часть.
            setCam(d.camAt - dx);
            state.camManualUntil = performance.now() + CAM_MANUAL_HOLD_MS;
        }

        function onStageUp(e) {
            const d = state.drag;
            if (!d || e.pointerId !== d.id) return;
            state.drag = null;
            try { svg.releasePointerCapture(e.pointerId); } catch (err) { /* уже отпущен */ }
            // Панорама либо тап по червю/кучке. ЗДЕСЬ будущий крючок реакций:
            // к этому моменту уже известно, что это именно тап (не свайп) и
            // что он пришёлся по телу, а какую часть задели — скажет
            // e.target.closest('[data-part]'). См. docs/stage-and-room.md.
            if (d.moved || !d.tappable) return;

            const p = toRoom(e);
            if (!p) return;
            // Считается только попадание В ПОЛ. Тап по стене или по темноте
            // вокруг коробки не должен никуда его отправлять: иначе «идёт
            // куда сказали» превращается в «дёргается от любого касания
            // экрана», и промах мимо кнопки сдвигает червя.
            const g = state.room;
            if (p.y < g.backY || p.y > g.frontY) return;
            if (Math.abs(p.x - g.cx) > roomHalfAt(g, roomDepthAt(g, p.y))) return;

            walkTo(p.x, p.y);
        }

        // Идти в точку пола. Точка вписывается в допустимую область, поэтому
        // тапнуть можно куда угодно — хоть в стену, хоть мимо комнаты: червь
        // подойдёт к ближайшему месту, где помещается целиком.
        function walkTo(floorX, floorY) {
            if (!state.room) return;
            const spot = clampFloorPoint(floorX, floorY);
            state.targetX = spot.x;
            state.targetY = spot.y - state.floorLocalY;
            // Курс НЕ трогаем: он доворачивается сам, и именно поэтому смена
            // цели на ходу читается дугой, а не изломом.
            state.nextMoveAt = null;
        }

        svg.addEventListener('pointerdown', onStageDown);
        svg.addEventListener('pointermove', onStageMove);
        svg.addEventListener('pointerup', onStageUp);
        svg.addEventListener('pointercancel', onStageUp);

        // Записать текущее истощение в фильтр. Здоровому фильтр СНИМАЕТСЯ
        // целиком, а не ставится нейтральным: лишний проход фильтра стоит
        // кадров на телефоне, а видимой разницы не даёт.
        function applyWither() {
            const s = Math.max(0, Math.min(1, state.witherShown));
            const off = s >= 0.995;
            witherSat.setAttribute('values', s.toFixed(3));
            // Вместе с цветом уходит и яркость: обескровленный червь темнеет.
            witherFuncs.forEach(f => f.setAttribute('slope', (0.72 + s * 0.28).toFixed(3)));
            [charLayer, slimeLayer].forEach(el => {
                if (off) el.removeAttribute('filter');
                else el.setAttribute('filter', `url(#${witherFilterId})`);
            });
        }

        function rebuild() {
            const m = mergedModel();
            while (charLayer.firstChild) charLayer.removeChild(charLayer.firstChild);
            state.built = buildWormSVGGroup(m, instanceId);
            charLayer.appendChild(state.built.root);
            state.built.root.setAttribute('transform', rootTransform());
            // Тело пересобрано — прежние габариты недействительны, границы
            // выгула пересчитаются по новым.
            state.bodyBox = null;
            state.wanderD = null;
        }

        syncViewportSize();
        rebuild();

        // ---------- СЛИЗИСТЫЙ СЛЕД (pose:'standing' + wander) ----------
        function randomBlobPath(cx, cy, rng, r) {
            const n = 6;
            const pts = [];
            for (let i = 0; i < n; i++) {
                const a = (i / n) * Math.PI * 2;
                const rr = r * (0.6 + rng() * 0.7);
                pts.push([cx + Math.cos(a) * rr, cy + Math.sin(a) * rr * 0.75]);
            }
            let d = `M ${pts[0][0].toFixed(1)},${pts[0][1].toFixed(1)} `;
            for (let i = 1; i <= n; i++) {
                const p = pts[i % n];
                d += `L ${p[0].toFixed(1)},${p[1].toFixed(1)} `;
            }
            return d + 'Z';
        }

        function startSlimeTrail(x, y) {
            const g = svgEl('g', { class: 'worm-slime-trail' });
            // След лежит НА ПОЛУ, значит подчиняется той же перспективе, что
            // и всё остальное: у дальней стены он должен быть уже.
            const trailScale = opts.room ? state.depthScale : 1;
            const rng = mulberry32(hashStringSeed(`slime-${instanceId}-${state.slimeTrails.length}-${Math.round(x)}-${Math.round(y)}`));
            const smearColor = withAlpha(ACID_DEEP, WORM_SLIME_SMEAR_ALPHA);
            const blot = svgEl('path', { d: randomBlobPath(x, y, rng, WORM_SLIME_WIDTH * 0.55 * trailScale), fill: smearColor });
            // Широкая тёмная клякса — само мокрое пятно, оно и есть след.
            const stroke = svgEl('path', {
                d: `M ${x.toFixed(1)},${y.toFixed(1)}`,
                fill: 'none', stroke: smearColor, 'stroke-width': (WORM_SLIME_WIDTH * trailScale).toFixed(2),
                'stroke-linecap': 'round', 'stroke-linejoin': 'round'
            });
            // Слой для ярких капель — они добавляются по мере движения.
            const drops = svgEl('g', { class: 'worm-slime-drops' });
            g.appendChild(blot);
            g.appendChild(stroke);
            g.appendChild(drops);
            slimeLayer.appendChild(g);
            state.slimeTrails.push({ g, stroke, drops, rng, scale: trailScale, points: [{ x, y }], finishedAt: null });
            state.activeSlimeTrail = state.slimeTrails[state.slimeTrails.length - 1];
        }

        function extendSlimeTrail(x, y) {
            const trail = state.activeSlimeTrail;
            if (!trail) return;
            const last = trail.points[trail.points.length - 1];
            if (Math.hypot(x - last.x, y - last.y) < WORM_SLIME_MIN_STEP) return;
            trail.points.push({ x, y });
            const d = trail.points.map((p, i) => `${i === 0 ? 'M' : 'L'} ${p.x.toFixed(1)},${p.y.toFixed(1)}`).join(' ');
            trail.stroke.setAttribute('d', d);
            // Капля свежей слизи — не на каждом шаге и со случайным сносом
            // поперёк следа, иначе капли выстроятся ровной пунктирной линией
            // по центру и получится разметка шоссе, а не слизь.
            if (trail.points.length % WORM_SLIME_DROP_EVERY !== 0) return;
            const ts = trail.scale || 1;
            const jx = (trail.rng() * 2 - 1) * WORM_SLIME_WIDTH * 0.3 * ts;
            const jy = (trail.rng() * 2 - 1) * WORM_SLIME_WIDTH * 0.3 * ts;
            const r = WORM_SLIME_DROP_R * (0.6 + trail.rng() * 0.8) * ts;
            trail.drops.appendChild(svgEl('ellipse', {
                cx: (x + jx).toFixed(1), cy: (y + jy).toFixed(1),
                rx: r.toFixed(2), ry: (r * (0.55 + trail.rng() * 0.4)).toFixed(2),
                fill: withAlpha(P_.acid[400], WORM_SLIME_DROP_ALPHA)
            }));
        }

        function updateSlimeTrail(now, isMoving, anchor) {
            if (isMoving && anchor) {
                // Ширина отрезка следа задаётся один раз, на его старте:
                // это обычный stroke, сузить его по длине нельзя. Поэтому
                // когда червь заметно меняет глубину, текущий отрезок
                // закрывается и начинается новый, уже своей ширины. Отрезки
                // перекрываются, стык не виден, а след честно сужается,
                // уходя вглубь комнаты.
                const act = state.activeSlimeTrail;
                if (act && opts.room && Math.abs(state.depthScale / (act.scale || 1) - 1) > WORM_SLIME_DEPTH_STEP) {
                    act.finishedAt = now;
                    state.activeSlimeTrail = null;
                }
                if (!state.activeSlimeTrail) startSlimeTrail(anchor.x, anchor.y);
                else extendSlimeTrail(anchor.x, anchor.y);
            } else if (state.activeSlimeTrail) {
                state.activeSlimeTrail.finishedAt = now;
                state.activeSlimeTrail = null;
            }

            for (let i = state.slimeTrails.length - 1; i >= 0; i--) {
                const trail = state.slimeTrails[i];
                if (trail.finishedAt == null) continue;
                const elapsed = now - trail.finishedAt;
                if (elapsed >= WORM_SLIME_FADE_MS) {
                    trail.g.remove();
                    state.slimeTrails.splice(i, 1);
                } else {
                    trail.g.setAttribute('opacity', (1 - elapsed / WORM_SLIME_FADE_MS).toFixed(3));
                }
            }
        }

        // ---------- КАДР НЕ СЧИТАЕТСЯ, ПОКА ХОЛСТ НЕ НА ЭКРАНЕ ----------
        // Это не «оптимизация на всякий случай», а лечение конкретной утечки.
        // Мини-игры («Тщеславие», «Чревоугодие») монтируют СВОЙ экземпляр
        // персонажа и намеренно держат его между открытиями, чтобы не платить
        // за пересборку семисот узлов. Но при закрытии никто не останавливал
        // его цикл: невидимый червь продолжал анимироваться вечно, сотнями
        // setAttribute в кадр. Замер: один такой забытый экземпляр — минус
        // около трёх кадров навсегда, и по одному на каждую такую мини-игру.
        //
        // Чинится здесь, а не в мини-играх, нарочно: «не забыть остановить» —
        // ровно то требование, которое уже забыли дважды. Пусть за этим следит
        // тот, кто крутит цикл.
        let stageVisible = true;
        let stageCheckedAt = -1e9;
        function isStageVisible(now) {
            // Проверка стоит запроса раскладки, поэтому пока холст ВИДЕН, она
            // делается дважды в секунду. А пока скрыт — каждый кадр: кадр в
            // этот момент всё равно пустой, зато возврат к жизни происходит
            // мгновенно. Задержка тут недопустима: мини-игра сразу после
            // open() меряет реальный bbox персонажа, и застрявшая на полсекунды
            // пауза дала бы ей замер по непосчитанному кадру.
            if (stageVisible && now - stageCheckedAt < 500) return true;
            stageCheckedAt = now;
            stageVisible = container.isConnected
                && container.getClientRects().length > 0
                && getComputedStyle(container).visibility !== 'hidden';
            return stageVisible;
        }

        function tick(now) {
            if (!isStageVisible(now)) {
                // Метку времени двигаем и на пропущенном кадре: иначе после
                // возврата dt окажется равным всей паузе, и персонаж прыгнет.
                state.lastFrameTs = now;
                state.rafId = requestAnimationFrame(tick);
                return;
            }
            if (!state.lastFrameTs) state.lastFrameTs = now;
            const dt = now - state.lastFrameTs;
            state.lastFrameTs = now;
            const dtSec = Math.min(0.25, Math.max(0, dt / 1000)); // клэмп на случай подвисания вкладки
            state.animTime += dtSec * WORM_ANIM_TIME_PER_SEC;

            // Габарит тела уточняется на ходу (см. measureBody). Раз в секунду
            // — этого хватает, чтобы огибающая сошлась за несколько секунд, и
            // getBBox не дёргает раскладку каждый кадр. Если размах вырос,
            // границы пересчитываются, а текущая цель вписывается заново:
            // иначе червь продолжил бы идти в точку, ставшую запретной.
            if (opts.wander && state.room && now - (state.bodyMeasuredAt || 0) > 1000) {
                state.bodyMeasuredAt = now;
                if (measureBody()) {
                    state.wanderD = null;
                    const spot = clampFloorPoint(state.targetX, state.targetY + state.floorLocalY);
                    state.targetX = spot.x;
                    state.targetY = spot.y - state.floorLocalY;
                }
            }

            // ---------- ДВИЖЕНИЕ К ЦЕЛИ + РАСПИСАНИЕ "ПРОГУЛОК" ----------
            let instSpeed = 0; // px/сек, фактическая мгновенная скорость этого кадра
            if (opts.wander) {
                const dx = state.targetX - state.wormX;
                const dy = state.targetY - state.wormY;
                const gap = Math.hypot(dx, dy);

                if (gap > WORM_MOVE_EPS) {
                    const want = Math.atan2(dy, dx);
                    if (state.heading == null) {
                        // Тронулся с места — сразу лицом куда надо. Дуга нужна
                        // при смене цели НА ХОДУ, а разворот стоящего червя
                        // вокруг себя выглядел бы вознёй на месте.
                        state.heading = want;
                    } else {
                        // Кратчайшая дуга: без приведения к ±π доворот с 179°
                        // на -179° поехал бы через весь круг.
                        const delta = ((want - state.heading + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
                        const maxTurn = WORM_TURN_RATE * dtSec;
                        state.heading += Math.max(-maxTurn, Math.min(maxTurn, delta));
                    }

                    // Скорость — прежняя экспонента (плавный подъезд к цели),
                    // но приваленная на крутом довороте.
                    const err = ((want - state.heading + Math.PI * 3) % (Math.PI * 2)) - Math.PI;
                    const turnDamp = 1 - WORM_TURN_SLOWDOWN * (1 - Math.cos(err)) / 2;
                    const step = gap * (1 - Math.pow(WORM_WANDER_MOVE_BASE, dtSec)) * turnDamp;

                    // Едет туда, куда СМОТРИТ, а не туда, где цель: в этом
                    // расхождении и рождается дуга.
                    const stepX = Math.cos(state.heading) * step;
                    const stepY = Math.sin(state.heading) * step;
                    state.wormX += stepX;
                    state.wormY += stepY;
                    instSpeed = dtSec > 0 ? Math.hypot(stepX, stepY) / dtSec : 0;
                } else {
                    // Дошёл. Курс сбрасывается, чтобы следующая прогулка
                    // началась без разворота на месте.
                    state.heading = null;
                }

                // Вписываем САМУ ПОЗИЦИЮ, а не только цель. Одной цели мало:
                // червь едет туда, куда смотрит, и на довороте его выносит
                // ШИРЕ цели — дуга выпирает наружу. В замерах это выглядело
                // как выезд начала координат за левый край экрана при
                // развороте у стены. Здесь он упирается и скользит вдоль
                // границы, вместо того чтобы её проскочить.
                //
                // Дорого это не стоит: габарит взят из кеша, вся проверка —
                // десяток арифметических действий на кадр.
                if (state.room) {
                    const fix = clampFloorPoint(state.wormX, state.wormY + state.floorLocalY);
                    state.wormX = fix.x;
                    state.wormY = fix.y - state.floorLocalY;
                }
            }
            const dist = opts.wander ? Math.hypot(state.targetX - state.wormX, state.targetY - state.wormY) : 0;
            const isMoving = opts.wander && dist > WORM_MOVE_EPS;
            if (opts.wander) {
                if (isMoving) {
                    state.nextMoveAt = null;
                } else if (state.nextMoveAt == null) {
                    state.nextMoveAt = now + WORM_IDLE_PAUSE_MIN + Math.random() * (WORM_IDLE_PAUSE_MAX - WORM_IDLE_PAUSE_MIN);
                } else if (now >= state.nextMoveAt) {
                    if (state.room) {
                        // Цель выбирается в координатах ПОЛА (глубина + сдвиг
                        // поперёк), а не в долях экрана: только так персонаж
                        // гарантированно остаётся на полу и не заходит в
                        // стену, какой бы ни была форма трапеции.
                        const g = state.room;
                        if (!state.wanderD) refreshWanderRange();
                        const r = state.wanderD || { min: ROOM.wanderNear, max: ROOM.wanderFar };
                        const d = r.min + Math.random() * (r.max - r.min);
                        // Точка выбирается вольно, а вписывает её в пол общий
                        // ограничитель — тот же, через который проходит тап
                        // игрока. Так правило «не залезать на стены» живёт в
                        // одном месте, а не дублируется в каждом источнике
                        // цели.
                        const spot = clampFloorPoint(
                            g.cx + (Math.random() * 2 - 1) * roomHalfAt(g, d),
                            roomYAt(g, d));
                        state.targetX = spot.x;
                        // Минус floorLocalY: на полу должна оказаться точка
                        // касания, а не голова. Без этой поправки червь
                        // «стоял» головой на полу, а всё тело свисало ниже —
                        // и на переднем крае комнаты уезжало за нижнюю кромку
                        // экрана. Именно это и выглядело как «уходит вниз».
                        state.targetY = spot.y - state.floorLocalY;
                    } else {
                        const rw = container.clientWidth || container.getBoundingClientRect().width;
                        const rh = container.clientHeight || container.getBoundingClientRect().height;
                        state.targetX = rw * 0.2 + Math.random() * (rw * 0.6);
                        state.targetY = rh * 0.4 + Math.random() * (rh * 0.3);
                    }
                    state.nextMoveAt = null;
                }
            }
            // Камера подтягивается к червю — после движения, чтобы за кадр не
            // отставать от него на шаг.
            if (opts.room) followCam(dtSec, now);

            // Истощение доводится покадрово. Раньше плавность давал CSS
            // transition, но у SVG-фильтра его нет — значения атрибутов
            // браузер не анимирует. Зато шаг здесь и не нужен часто: пока
            // показанное совпало с целью, не делается ничего.
            if (Math.abs(state.witherShown - state.witherTarget) > 0.002) {
                state.witherShown += (state.witherTarget - state.witherShown) *
                                     (1 - Math.pow(WORM_WITHER_BASE, dtSec));
                applyWither();
            }

            // ---------- ДОВОРОТ ХВОСТА ЗА ДВИЖЕНИЕМ ----------
            // Целевой угол — строго противоположный движению: хвост тянется
            // СЗАДИ. Вертикаль сжата перспективой пола.
            if (opts.wander && isMoving) {
                const mdx = state.targetX - state.wormX;
                const mdy = (state.targetY - state.wormY) * WORM_FLOOR_PERSPECTIVE;
                if (Math.hypot(mdx, mdy) > 0.001) {
                    const want = Math.atan2(-mdy, -mdx) * 180 / Math.PI;
                    // Кратчайшая дуга: без неё доворот с 179° на -179° поехал
                    // бы через весь круг, и хвост картинно обнёс бы червя.
                    let delta = ((want - state.tailAngle + 540) % 360) - 180;
                    state.tailAngle += delta * (1 - Math.pow(WORM_TAIL_TURN_BASE, dtSec));
                    state.tailAngle = ((state.tailAngle % 360) + 360) % 360;
                }
            }

            // ---------- ГЛУБИНА → РАЗМЕР ----------
            // Персонаж на полу: его экранная высота однозначно задаёт, как
            // далеко он от камеры. Ближе — крупнее, вглубь — мельче.
            if (opts.room && state.room) {
                // Глубина берётся по ТОЧКЕ КАСАНИЯ ПОЛА, а не по началу
                // координат персонажа: начало координат — это голова, а стоит
                // он ногами. Разница между ними — почти двести условных
                // единиц, то есть треть комнаты.
                state.depthScale = roomCharScaleAt(
                    roomDepthAt(state.room, state.wormY + state.floorLocalY));
            }

            const intensityFactor = 1 - Math.pow(WORM_MOVE_INTENSITY_SMOOTH_BASE, dtSec);
            state.moveIntensity += ((isMoving ? 1 : 0) - state.moveIntensity) * intensityFactor;

            const speedIntensityTarget = Math.min(1, instSpeed / WORM_SPEED_REF_PX_PER_SEC);
            const speedIntensityFactor = 1 - Math.pow(WORM_SPEED_INTENSITY_SMOOTH_BASE, dtSec);
            state.speedIntensity += (speedIntensityTarget - state.speedIntensity) * speedIntensityFactor;

            if (state.built) {
                state.built.root.setAttribute('transform', rootTransform());

                // Модель читаем один раз за кадр и переиспользуем ниже.
                const mm = mergedModel();

                const bellySeg = state.built.segments.find(s => s.name === 'belly');
                const bellyFactor = state.livePose.bellyScale != null ? state.livePose.bellyScale : 1;
                // Раздувшийся живот растёт "вперёд" (в сторону хвоста) от
                // неподвижной точки стыка с головным соседом, а сегменты
                // дальше по цепочке отодвигаются на ту же величину.
                const bellyGrowX = bellySeg ? Math.max(0, bellySeg.baseRx * (bellyFactor - 1)) : 0;
                const bellyPushGap = bellyGrowX * 2;
                const bellyIdx = bellySeg ? bellySeg.idx : -1;

                let lastGrowLocal = null;
                const lastGrowingName = mm.growingSegments.length ? `growing-${mm.growingSegments.length}` : null;
                let breathWave = 0;

                // Круги единого силуэта, по порядку цепочки: [0] — якорь
                // внутри головы (чтобы шея входила в череп без стыка),
                // дальше сегменты по своим idx, последним — основание
                // хвоста. Заполняется теми же вычислениями, что уже двигают
                // сами части: силуэт не может разойтись с телом, потому что
                // считается из одних и тех же чисел.
                const hullCircles = new Array(state.built.tail.idx + 1).fill(null);
                hullCircles[0] = {
                    x: 0, y: 0,
                    r: state.built.head.ry * 0.42,
                    color: state.built.head.fillColor
                };

                if (opts.pose === 'lying') {
                    // ---------- СТАРАЯ РАСКЛАДКА: ОДНА ПРЯМАЯ ЛИНИЯ ----------
                    // Логика не тронута — нужна Чревоугодию.
                    const wave = opts.idleWave ? Math.sin(state.animTime) * 8 : 0;
                    state.built.head.group.setAttribute('transform', `translate(0,${wave.toFixed(2)})`);

                    state.built.segments.forEach(seg => {
                        const extraGap = seg.idx > bellyIdx ? bellyPushGap : 0;
                        const sx = -(seg.idx * WORM_SEGMENT_SPACING + WORM_CHAIN_HEAD_GAP + extraGap);
                        const sy = opts.idleWave ? (Math.sin(state.animTime + seg.idx * 0.6) * 12 + seg.idx * 4) : 0;
                        seg.group.setAttribute('transform', `translate(${sx.toFixed(1)},${sy.toFixed(1)})`);
                        hullCircles[seg.idx] = { x: sx, y: sy, r: seg.baseRx, color: seg.fillColor };
                    });

                    const tsx = -(state.built.tail.idx * WORM_SEGMENT_SPACING + WORM_CHAIN_HEAD_GAP + bellyPushGap);
                    const tsy = opts.idleWave ? (Math.sin(state.animTime + state.built.tail.idx * 0.6) * 12 + state.built.tail.idx * 4) : 0;
                    state.built.tail.group.setAttribute('transform', `translate(${tsx.toFixed(1)},${tsy.toFixed(1)})`);
                    hullCircles[state.built.tail.idx] = {
                        x: tsx, y: tsy, r: state.built.tail.baseRadius, color: mm.tail.fill
                    };
                    if (state.built.tail.bendGroup) {
                        state.built.tail.bendGroup.setAttribute('transform', `rotate(${state.livePose.tailBendAngle.toFixed(1)})`);
                    }
                } else {
                    // ---------- "СТОЯЩАЯ" ПОЗА ----------
                    state.built.head.group.setAttribute('transform', 'translate(0,0)');

                    const floorY = bellyIdx * WORM_VERTICAL_SPACING + WORM_CHAIN_HEAD_GAP;
                    // Запоминаем для rootTransform: масштаб по глубине берёт
                    // эту точку за неподвижную, иначе персонаж всплывает.
                    state.floorLocalY = floorY;
                    // Сторона завала колонны = сторона, куда лежит хвост.
                    // cos угла хвоста даёт и знак, и естественное затухание
                    // завала, когда червь ползёт строго вглубь комнаты: там
                    // тело уходит от камеры, а не вбок, и заваливаться некуда.
                    const leanDir = Math.cos(state.tailAngle * Math.PI / 180);

                    // Однополярная волна дыхания: стартует с 0 (стандартный
                    // радиус), поднимается до 1 и возвращается к 0.
                    breathWave = opts.idleWave ? (1 - Math.cos(state.animTime * WORM_BREATH_SPEED)) / 2 : 0;

                    state.built.segments.forEach(seg => {
                        if (seg.idx > bellyIdx) return;
                        const vy = seg.idx * WORM_VERTICAL_SPACING + WORM_CHAIN_HEAD_GAP;
                        const vx = spineLeanMag(bellyIdx > 0 ? seg.idx / bellyIdx : 0) * leanDir;
                        seg.group.setAttribute('transform', `translate(${vx.toFixed(1)},${vy.toFixed(1)})`);
                        hullCircles[seg.idx] = { x: vx, y: vy, r: seg.baseRx, color: seg.fillColor };
                        const breathRatio = WORM_BREATH_RATIO[seg.name];
                        if (breathRatio != null) {
                            const breathFactor = 1 + breathWave * WORM_BREATH_AMP * breathRatio;
                            hullCircles[seg.idx].r = seg.baseRx * breathFactor;
                            seg.ellipse.setAttribute('rx', (seg.baseRx * breathFactor).toFixed(2));
                            seg.ellipse.setAttribute('ry', (seg.baseRy * breathFactor).toFixed(2));
                            // Анатомические слои дышат ВМЕСТЕ с сегментом:
                            // одна группа = один setAttribute, вся стопка
                            // слоёв внутри масштабируется автоматически по
                            // SVG-иерархии (тот же принцип, что и у шрамов).
                            if (seg.anat) {
                                seg.anat.group.setAttribute('transform', `scale(${breathFactor.toFixed(4)})`);
                            }
                        }
                    });

                    // Напольная часть (growing-сегменты + хвост) — простая
                    // кинематическая цепь: каждое звено строится СТРОГО от
                    // позиции предыдущего, поэтому разъединиться геометрически
                    // невозможно ни при какой амплитуде покачивания.
                    const moveStretch = WORM_MOVE_SPACING_EXTRA * state.speedIntensity;
                    const wiggleSpeed = lerp(WORM_CHAIN_WIGGLE_IDLE_SPEED, WORM_CHAIN_WIGGLE_MOVE_SPEED, state.moveIntensity);
                    const wiggleAmpDeg = lerp(WORM_CHAIN_WIGGLE_IDLE_DEG, WORM_CHAIN_WIGGLE_MOVE_DEG, state.moveIntensity);
                    const tailExtraWagDeg = lerp(WORM_TAIL_EXTRA_WAG_IDLE_DEG, WORM_TAIL_EXTRA_WAG_MOVE_DEG, state.moveIntensity);
                    const DEG2RAD = Math.PI / 180;

                    state.chainWigglePhase += dtSec * WORM_ANIM_TIME_PER_SEC * wiggleSpeed;
                    state.tailWagPhase += dtSec * WORM_ANIM_TIME_PER_SEC * wiggleSpeed * 1.3;

                    const floorSegments = state.built.segments
                        .filter(seg => seg.idx > bellyIdx)
                        .sort((a, b) => a.idx - b.idx);

                    // Стартуем от РЕАЛЬНОГО положения живота: он уехал вбок
                    // вместе с колонной, и цепь обязана продолжаться от него.
                    // Сдвиг живота на раздутие тоже идёт в сторону хвоста.
                    let chainX = spineLeanMag(1) * leanDir + bellyPushGap * leanDir;
                    let chainY = floorY;
                    let prevRadius = bellySeg ? bellySeg.baseRx : 15;
                    floorSegments.forEach(seg => {
                        const stepsFromBelly = seg.idx - bellyIdx;
                        const wiggleDeg = opts.idleWave ? Math.sin(state.chainWigglePhase + stepsFromBelly * WORM_CHAIN_PHASE_STEP) * wiggleAmpDeg : 0;
                        const angleRad = (state.tailAngle + wiggleDeg) * DEG2RAD;
                        const linkLength = floorLinkBaseLength(prevRadius, seg.baseRx) + moveStretch;
                        chainX += linkLength * Math.cos(angleRad);
                        chainY += linkLength * Math.sin(angleRad);
                        seg.group.setAttribute('transform', `translate(${chainX.toFixed(1)},${chainY.toFixed(1)})`);
                        hullCircles[seg.idx] = { x: chainX, y: chainY, r: seg.baseRx, color: seg.fillColor };
                        prevRadius = seg.baseRx;
                        if (seg.name === lastGrowingName) {
                            lastGrowLocal = { x: chainX, y: chainY };
                        }
                    });

                    // Хвост — последнее звено той же цепи.
                    const tailStepsFromBelly = state.built.tail.idx - bellyIdx;
                    const tailWiggleDeg = opts.idleWave ? Math.sin(state.chainWigglePhase + tailStepsFromBelly * WORM_CHAIN_PHASE_STEP) * wiggleAmpDeg : 0;
                    const tailAngleDeg = state.tailAngle + tailWiggleDeg;
                    const tailAngleRad = tailAngleDeg * DEG2RAD;
                    const tailLinkLength = floorLinkBaseLength(prevRadius, state.built.tail.baseRadius) + moveStretch;
                    chainX += tailLinkLength * Math.cos(tailAngleRad);
                    chainY += tailLinkLength * Math.sin(tailAngleRad);
                    state.built.tail.group.setAttribute('transform', `translate(${chainX.toFixed(1)},${chainY.toFixed(1)})`);
                    hullCircles[state.built.tail.idx] = {
                        x: chainX, y: chainY, r: state.built.tail.baseRadius, color: mm.tail.fill
                    };
                    if (state.built.tail.bendGroup) {
                        const extraWag = opts.idleWave ? Math.sin(state.tailWagPhase + 1.7) * tailExtraWagDeg : 0;
                        const totalRotate = (tailAngleDeg - 180) + extraWag + state.livePose.tailBendAngle;
                        state.built.tail.bendGroup.setAttribute('transform', `rotate(${totalRotate.toFixed(1)})`);
                    }

                    if (opts.wander) {
                        const flip = opts.flip;
                        // Точка выхода следа задана в ЛОКАЛЬНЫХ координатах
                        // персонажа, а он теперь масштабируется по глубине —
                        // значит и смещение надо считать по тем же правилам,
                        // что и корневой трансформ, иначе след будет
                        // отставать от хвоста тем сильнее, чем дальше червь.
                        const sc = state.depthScale;
                        const shiftY = state.floorLocalY * (1 - sc);
                        const anchorWorld = lastGrowLocal ? {
                            x: state.wormX + (flip ? -lastGrowLocal.x : lastGrowLocal.x) * sc,
                            y: state.wormY + shiftY + lastGrowLocal.y * sc
                        } : null;
                        updateSlimeTrail(now, isMoving, anchorWorld);
                    }
                }

                if (bellySeg) {
                    // Дыхание живота умножается на bellyFactor (раздутие из
                    // мини-игр через livePose.bellyScale), а не заменяет его.
                    const bellyBreathFactor = 1 + breathWave * WORM_BREATH_AMP * (WORM_BREATH_RATIO.belly || 0);
                    const effectiveBellyFactor = bellyFactor * bellyBreathFactor;
                    const newRx = bellySeg.baseRx * effectiveBellyFactor;
                    const newRy = bellySeg.baseRy * effectiveBellyFactor;
                    let cy = 0;
                    if (opts.bellyGrowthAnchor === 'bottom') cy = -(newRy - bellySeg.baseRy);
                    else if (opts.bellyGrowthAnchor === 'top') cy = (newRy - bellySeg.baseRy);
                    // По X живот всегда "растёт вперёд": локальный +X — это
                    // сторона стыка с головным соседом, она остаётся на месте.
                    const cx = -bellyGrowX;
                    bellySeg.ellipse.setAttribute('rx', newRx.toFixed(2));
                    bellySeg.ellipse.setAttribute('ry', newRy.toFixed(2));
                    bellySeg.ellipse.setAttribute('cx', cx.toFixed(2));
                    bellySeg.ellipse.setAttribute('cy', cy.toFixed(2));
                    if (bellySeg.shine) {
                        bellySeg.shine.setAttribute('cx', (cx - newRx * 0.25).toFixed(2));
                        bellySeg.shine.setAttribute('cy', (cy - newRy * 0.4).toFixed(2));
                        bellySeg.shine.setAttribute('rx', (newRx * 0.38).toFixed(2));
                        bellySeg.shine.setAttribute('ry', (newRy * 0.22).toFixed(2));
                    }
                    // Анатомия живота повторяет ровно ту же трансформацию,
                    // что и его заливка: смещение центра + масштаб. Один
                    // setAttribute на весь слоёный "пирог" — внутренности,
                    // мышцы, кольца и блики растягиваются вместе с животом
                    // (и, соответственно, честно раздуваются в Чревоугодии).
                    if (bellySeg.anat) {
                        bellySeg.anat.group.setAttribute('transform',
                            `translate(${cx.toFixed(2)},${cy.toFixed(2)}) scale(${effectiveBellyFactor.toFixed(4)})`);
                    }
                    // Живот в силуэте — с уже раздутыми размерами и смещённым
                    // центром: единый контур обязан повторять раздутие, иначе
                    // при кормлении тело вылезет за собственную обводку.
                    const bellyCircle = hullCircles[bellySeg.idx];
                    if (bellyCircle) {
                        bellyCircle.x += cx;
                        bellyCircle.y += cy;
                        bellyCircle.r = Math.max(newRx, newRy);
                    }
                }

                // Единый силуэт, перетяжки, отражённый свет и тень на полу.
                updateBodyHull(state.built, hullCircles);

                // ---------- ЕДИНЫЙ КИШЕЧНЫЙ ТРАКТ ----------
                // Пересчитывается из тех же кругов, что и силуэт, поэтому
                // повторяет любой изгиб тела и раздутие живота без единой
                // отдельной координаты. Фаза перистальтики — отдельный
                // аккумулятор от dt (тот же принцип, что у прочих анимаций).
                state.gutSkipFrame = !state.gutSkipFrame;
                if (state.built.gutTract && !state.gutSkipFrame) {
                    const anat = mm.anatomy && mm.anatomy.enabled ? mm.anatomy : null;
                    const organs = anat && anat.organs ? anat.organs : null;
                    const cfg = organs && organs.tract ? organs.tract : null;
                    if (cfg) {
                        state.gutPhase += dtSec * (cfg.speed != null ? cfg.speed : 0.32);
                        const axis = sampleBodyAxis(hullCircles, 3.4);
                        const geom = buildGutTractGeometry(axis, bellySeg ? hullCircles[bellySeg.idx] : null, {
                            phase: state.gutPhase,
                            width: cfg.width, bellyWidth: cfg.bellyWidth,
                            wave: cfg.wave, bellyWave: cfg.bellyWave,
                            waveLength: cfg.waveLength, loopDensity: cfg.loopDensity
                        });
                        state.built.gutTract.tube.setAttribute('d', geom.ribbon);
                        state.built.gutTract.coreLine.setAttribute('d', geom.core);
                        state.built.gutTract.corePts = geom.corePts;
                        const liveVis = state.livePose.organVisibility;
                        const baseVis = liveVis != null ? liveVis : (organs.visibility != null ? organs.visibility : 0.6);
                        state.built.gutTract.group.setAttribute('opacity',
                            clamp01(baseVis * (cfg.visibility != null ? cfg.visibility : 0.85)).toFixed(3));
                    }
                }

                // ---------- ПУЛЬСАЦИЯ ВНУТРЕННИХ ОРГАНОВ ----------
                // Framerate-independent: фаза — отдельный аккумулятор,
                // прирастающий dtSec * текущая скорость (см. "эффект волчка").
                // Скорость может меняться на лету (livePose/оверрайд), поэтому
                // умножать общее накопленное время на неё нельзя.
                if (state.built.organs && state.built.organs.length) {
                    const anatomy = mm.anatomy && mm.anatomy.enabled ? mm.anatomy : null;
                    const pulse = anatomy && anatomy.organs ? (anatomy.organs.pulse || {}) : null;
                    if (pulse) {
                        const speed = pulse.speed != null ? pulse.speed : 0.85;
                        state.organPhase += dtSec * speed * Math.PI;
                        const ampScale = state.livePose.organPulseScale != null ? state.livePose.organPulseScale : 1;
                        const amp = (pulse.amp != null ? pulse.amp : 0.07) * ampScale;
                        if (amp > 0.0005) {
                            state.built.organs.forEach(o => {
                                const s = Math.sin(state.organPhase * o.speedMul + o.phase);
                                const a = amp * o.ampMul * s;
                                // Кишка "перистальтирует" (толще поперёк —
                                // короче вдоль), мешочек и узелки дышат
                                // равномерно: у каждого органа свой ритм и
                                // своя манера, а не общий мигающий scale.
                                const sx = o.kind === 'gut' ? (1 - a * 0.35) : (1 + a);
                                const sy = 1 + a;
                                o.group.setAttribute('transform',
                                    `translate(${o.x.toFixed(1)},${o.y.toFixed(1)}) rotate(${o.rot.toFixed(1)}) scale(${sx.toFixed(4)},${sy.toFixed(4)})`);
                            });
                        }
                    }
                }

                // Рот — пересчитываем форму каждый кадр из bend/gap.
                const mouthBuiltRef = state.built.head.mouth;
                if (mouthBuiltRef) {
                    const liveOpenness = state.livePose.mouthOpenness;
                    const openness = liveOpenness != null ? liveOpenness : Math.max(0, mm.head.mouth.openness || 0);
                    const liveCurve = state.livePose.mouthCurve;
                    const curve = liveCurve != null ? liveCurve : mm.head.mouth.curve;
                    const bend = mouthBendFromCurve(curve);
                    const gap = mouthBuiltRef.MAX_GAP * clamp01(openness);
                    updateMouthGeometry(mouthBuiltRef, bend, gap,
                        state.livePose.mouthFill, state.livePose.mouthFillColor);
                }

                // ---------- МИМИКА ГОЛОВЫ ----------
                // Персонаж не должен быть застывшей маской: даже когда его
                // никто не трогает, у него подрагивают уши и он принюхивается.
                // Всё это — обычные "живые" параметры: мини-игра может задать
                // их напрямую через setLivePose, и тогда собственная жизнь
                // персонажа по этому каналу уступает управлению.
                const headRef = state.built.head;
                if (headRef && headRef.tiltGroup) {
                    const face = (mm.anatomy && mm.anatomy.face) || {};
                    const idle = face.idle || {};
                    state.faceClock += dt;

                    // Подёргивание уха: короткий импульс раз в несколько секунд,
                    // поочерёдно у разных ушей.
                    const earIdleAmt = idle.earTwitch != null ? idle.earTwitch : 1;
                    const earCycle = 5200;
                    const earPos = state.faceClock % earCycle;
                    const earImpulse = earPos < 260 ? Math.sin((earPos / 260) * Math.PI) : 0;
                    const twitchSide = Math.floor(state.faceClock / earCycle) % 2 === 0 ? 'left' : 'right';

                    // Принюхивание: серия из трёх быстрых движений пятачка.
                    const sniffIdleAmt = idle.sniff != null ? idle.sniff : 1;
                    const sniffCycle = 7400;
                    const sniffPos = state.faceClock % sniffCycle;
                    const sniffImpulse = sniffPos < 560 ? Math.abs(Math.sin((sniffPos / 560) * Math.PI * 3)) : 0;

                    // ---------- ПОВОРОТ ГОЛОВЫ ----------
                    // Цель берётся из живого канала, иначе из модели.
                    // Подъезд к ней — framerate-независимый, по той же
                    // формуле 1 - base^dt, что и остальное сглаживание в
                    // файле. База МАЛЕНЬКАЯ (быстрая сходимость): поворот
                    // должен читаться щелчком, а не медленным морфом, но
                    // при этом не щёлкать буквально — иначе головой нельзя
                    // будет плавно вести за целью.
                    // ---------- КУДА СМОТРИТ ГОЛОВА ----------
                    // Приоритет: явный живой канал → явная поза → автоматика
                    // по направлению ползания → значение из модели.
                    //
                    // Автоматика: голова смотрит ТУДА, КУДА ползёт, то есть в
                    // сторону, противоположную хвосту. Отсюда -cos(угла
                    // хвоста): при хвосте слева (180°) выходит +1, то есть
                    // взгляд вправо; при хвосте справа (0°) — -1, взгляд
                    // влево.
                    //
                    // Разворот через анфас получается САМ и не требует
                    // отдельного кода: пока червь поворачивает, угол хвоста
                    // проходит через «строго вглубь комнаты» (90°/270°), а
                    // там косинус равен нулю — голова в этот момент смотрит
                    // ровно в камеру. Ровно то поведение, которое нужно:
                    // сначала повернулась вперёд, потом в новую сторону.
                    let yawTarget;
                    if (state.livePose.headYaw != null) {
                        yawTarget = state.livePose.headYaw;
                    } else if (!state.headYawAuto && state.headYawTarget != null) {
                        yawTarget = state.headYawTarget;
                    } else if (state.headYawAuto && opts.wander) {
                        yawTarget = WORM_HEAD_YAW_FOLLOW * -Math.cos(state.tailAngle * Math.PI / 180);
                    } else {
                        yawTarget = mm.head.yaw != null ? mm.head.yaw : 0;
                    }
                    if (state.headYawCurrent == null) state.headYawCurrent = yawTarget;
                    const yawK = 1 - Math.pow(WORM_HEAD_YAW_BASE, dtSec);
                    state.headYawCurrent += (yawTarget - state.headYawCurrent) * yawK;
                    // Ниже порога дотягиваем до цели: экспонента математически
                    // никогда не долетает, а «почти повёрнутая» голова —
                    // это просто чуть кривое лицо.
                    if (Math.abs(yawTarget - state.headYawCurrent) < WORM_HEAD_YAW_EPS) {
                        state.headYawCurrent = yawTarget;
                    }
                    applyHeadYaw(headRef, +state.headYawCurrent.toFixed(4));

                    // Наклон головы — вокруг основания шеи, а не центра черепа:
                    // иначе голова "съезжает" с тела.
                    const tilt = state.livePose.headTilt != null ? state.livePose.headTilt : 0;
                    headRef.tiltGroup.setAttribute('transform',
                        tilt ? `rotate(${tilt.toFixed(2)} 0 ${(headRef.ry * 1.15).toFixed(1)})` : '');

                    // Уши.
                    ['left', 'right'].forEach(side => {
                        const ref = headRef.ears[side];
                        if (!ref) return;
                        const live = side === 'left' ? state.livePose.earTiltLeft : state.livePose.earTiltRight;
                        const common = state.livePose.earTilt;
                        let extra = 0;
                        if (live != null) extra = live;
                        else if (common != null) extra = common;
                        else if (side === twitchSide) extra = -14 * earImpulse * earIdleAmt;
                        const mirror = side === 'left' ? -1 : 1;
                        ref.group.setAttribute('transform',
                            `translate(${ref.anchorX.toFixed(2)},${ref.anchorY.toFixed(2)}) ` +
                            `rotate(${(ref.baseAngle + extra * mirror).toFixed(2)}) ` +
                            `scale(${ref.scaleX.toFixed(3)},${ref.scaleY.toFixed(3)})`);
                    });

                    // Пятачок: при принюхивании чуть поднимается и сплющивается.
                    const twitch = state.livePose.snoutTwitch != null
                        ? clamp01(state.livePose.snoutTwitch)
                        : sniffImpulse * sniffIdleAmt;
                    if (headRef.snoutGroup) {
                        const sn = mm.head.snout;
                        const sx = sn.scale * sn.stretchX * (1 + 0.05 * twitch);
                        const sy = sn.scale * sn.stretchY * (1 - 0.07 * twitch);
                        // Ракурс входит сюда множителем: tick переписывает
                        // трансформ целиком, и без него поворот пятачка
                        // терялся бы через кадр после сборки.
                        headRef.snoutGroup.setAttribute('transform',
                            `translate(${(headRef.snoutX || 0).toFixed(2)},${(headRef.snoutY - 1.6 * twitch).toFixed(2)}) ` +
                            `scale(${(sx * (headRef.snoutSquash != null ? headRef.snoutSquash : 1)).toFixed(3)},${sy.toFixed(3)})`);
                    }

                    // Челюсть следует за ртом: рот открывается — низ морды
                    // уходит вниз, а не остаётся неподвижной кожей с дыркой.
                    if (headRef.jawGroup) {
                        const openness = state.livePose.mouthOpenness != null
                            ? clamp01(state.livePose.mouthOpenness)
                            : clamp01(mm.head.mouth.openness || 0);
                        const drop = state.livePose.jawDrop != null ? clamp01(state.livePose.jawDrop) : openness;
                        headRef.jawShift.setAttribute('transform', `translate(0,${(drop * 5).toFixed(2)})`);
                    }

                    // Щёки: надуваются (полный рот) — брыли расходятся в стороны.
                    if (headRef.muzzleGroup) {
                        headRef.muzzlePuff = state.livePose.cheekPuff != null
                            ? clamp01(state.livePose.cheekPuff) : 0;
                        applyMuzzleTransform(headRef);
                    }

                    // Взгляд и брови.
                    const gx = state.livePose.gazeX, gy = state.livePose.gazeY;
                    const browRaise = state.livePose.browRaise;
                    ['left', 'right'].forEach(side => {
                        const eyeRef = headRef.eyes[side];
                        if (!eyeRef) return;
                        if (eyeRef.gazeGroup) {
                            const dx = (gx != null ? gx : 0) * eyeRef.rx * 0.34;
                            const dy = (gy != null ? gy : 0) * eyeRef.ry * 0.34;
                            eyeRef.gazeGroup.setAttribute('transform',
                                (dx || dy) ? `translate(${dx.toFixed(2)},${dy.toFixed(2)})` : '');
                        }
                        if (browRaise != null && eyeRef.browGroup) {
                            const eyeModel = mm.eyes[side];
                            const mirror = side === 'left' ? -1 : 1;
                            const lift = -browRaise * 4;
                            const angle = eyeModel.brow.angle * mirror - browRaise * 6 * mirror;
                            eyeRef.browGroup.setAttribute('transform',
                                `translate(0,${(-eyeRef.ry - 7 + lift).toFixed(2)}) rotate(${angle.toFixed(2)})`);
                        }
                    });
                }

                // Веки обновляются ВСЕГДА, а opts.blink лишь добавляет импульс
                // моргания: иначе на экранах с выключенным морганием
                // livePose.eyelidLevel (прищур, дрёма, зажмуривание) просто
                // не доезжал до персонажа.
                {
                    let blinkLevel = 0;
                    if (opts.blink) {
                        state.blinkClock += dt;
                        const cyclePos = state.blinkClock % WORM_BLINK_CYCLE;
                        if (cyclePos >= WORM_BLINK_START && cyclePos < WORM_BLINK_START + WORM_BLINK_DURATION) {
                            const p = (cyclePos - WORM_BLINK_START) / WORM_BLINK_DURATION;
                            blinkLevel = Math.sin(p * Math.PI);
                        }
                    }
                    ['left', 'right'].forEach(side => {
                        const eyeModel = mm.eyes[side];
                        const eyeRef = state.built.head.eyes[side];
                        const restLevel = state.livePose.eyelidLevel != null ? state.livePose.eyelidLevel : eyeModel.eyelid.level;
                        const level = Math.max(restLevel, blinkLevel);
                        const travel = 2 * eyeRef.ry + 5;
                        const ty = -travel * (1 - level);
                        eyeRef.lidTrack.setAttribute('transform', `translate(0,${ty.toFixed(2)})`);

                        // Нижнее веко. При моргании убирается: щека не может
                        // держать глаз поджатым, пока он закрывается сверху,
                        // и наложение двух шторок дало бы схлопывание в щель.
                        if (eyeRef.smileTrack) {
                            const smile = clamp01(state.livePose.eyeSmile || 0) * (1 - blinkLevel);
                            eyeRef.smileTrack.setAttribute('transform',
                                `translate(0,${(eyeRef.smileTravel * (1 - smile)).toFixed(2)})`);
                        }
                    });
                }
            }

            state.rafId = requestAnimationFrame(tick);
        }
        state.rafId = requestAnimationFrame(tick);

        function onResize() { syncViewportSize(); }
        window.addEventListener('resize', onResize);

        return {
            update(newModel) {
                state.baseModel = newModel;
                rebuild();
            },
            setOverride(patch) {
                state.override = patch;
                rebuild();
            },
            setPose(name) {
                svg.setAttribute('data-pose', name || '');
            },
            // Повернуть голову в именованную позу: 'left' | 'center' | 'right'.
            // Голова доедет туда сама, за кадры — без пересборки SVG.
            // Можно передать и число (-1..1), если нужна произвольная точка
            // оси, например слежение за курсором.
            setHeadPose(pose, opts) {
                // 'auto' — вернуть управление автоматике (голова снова
                // следит за направлением ползания).
                if (pose === 'auto' || pose == null) {
                    state.headYawAuto = true;
                    state.headYawTarget = null;
                    return;
                }
                const v = typeof pose === 'number'
                    ? Math.max(-1, Math.min(1, pose))
                    : (WORM_HEAD_POSES[pose] != null ? WORM_HEAD_POSES[pose] : 0);
                state.headYawAuto = false;
                state.headYawTarget = v;
                state.livePose.headYaw = null; // именованная поза перебивает ручной канал
                // instant: встать в позу без переходной анимации.
                if (opts && opts.instant) state.headYawCurrent = v;
            },
            getHeadPose() {
                return {
                    current: state.headYawCurrent,
                    target: state.headYawTarget,
                    poses: Object.assign({}, WORM_HEAD_POSES)
                };
            },
            setLivePose(patch) {
                Object.assign(state.livePose, patch);
                // Степень просвечивания органов — единственный "живой"
                // параметр, который нельзя поменять одним transform: он
                // задан непрозрачностью слоя. Меняем её точечно, без
                // пересборки SVG (тот же принцип "не трогаем DOM зря").
                if (patch && patch.organVisibility !== undefined && state.built) {
                    const layers = state.built.root.querySelectorAll('.worm-organ-layer');
                    const m = mergedModel();
                    const base = (m.anatomy && m.anatomy.organs && m.anatomy.organs.visibility != null)
                        ? m.anatomy.organs.visibility : 0.55;
                    for (let i = 0; i < layers.length; i++) {
                        const host = layers[i].closest('[data-anat]');
                        const partName = host ? host.getAttribute('data-anat') : null;
                        const thin = partName && m.anatomy
                            ? anatThinness(m.anatomy, partName, (m.growingSegments || []).length) : 1;
                        const vis = patch.organVisibility != null ? patch.organVisibility : base;
                        layers[i].setAttribute('opacity', clamp01(vis * thin).toFixed(3));
                    }
                }
            },
            // Переключение опций монтирования на ходу. Пока нужна ровно одна
            // пара — wander и blink: мёртвый червь не бродит по комнате и не
            // моргает, а перемонтировать его ради этого значило бы собрать
            // весь SVG заново. Опции читаются в tick() каждый кадр, поэтому
            // достаточно их подменить.
            setOptions(patch) {
                Object.assign(opts, patch);
            },
            // Сменить локацию. Перестраивается ТОЛЬКО слой комнаты: персонаж,
            // след слизи и предметы на полу к ней не привязаны, а геометрия
            // коробки у всех локаций общая — значит червь остаётся стоять
            // ровно там же, где стоял, и заново собирать его незачем.
            setLocation(key) {
                if (!opts.room || !state.room) return false;
                if (typeof RoomLocations === 'undefined' || !RoomLocations.has(key)) return false;
                state.location = key;
                buildRoom(roomLayer, state.room, key);
                return true;
            },
            getLocation() {
                return state.location;
            },
            // Отправить червя в точку пола (в единицах холста). Тот же путь,
            // которым идёт тап игрока: точка вписывается в допустимую область.
            walkTo,
            // Истощение: 1 = здоровый цвет, 0 = полностью обесцвечен.
            // Показанное значение догоняет это за кадры — вызывающему не надо
            // сглаживать самому.
            setWither(saturation) {
                state.witherTarget = Math.max(0, Math.min(1, saturation));
            },
            // Точечная перестановка "точки стояния" персонажа уже ПОСЛЕ
            // монтирования — нужна мини-играм, где раскладку нельзя выразить
            // одним фиксированным anchorX/anchorY.
            setPosition(x, y) {
                state.wormX = x;
                state.wormY = y;
                state.targetX = x;
                state.targetY = y;
                if (state.built) state.built.root.setAttribute('transform', rootTransform());
            },
            getPosition() {
                return { x: state.wormX, y: state.wormY };
            },

            // Где сейчас конкретная часть тела — в координатах сцены.
            // Нужно тому, кто кладёт что-то рядом с червём: «под хвостом»
            // нельзя посчитать снаружи, потому что тело поворачивается по
            // ходу движения, а хвост уезжает за ним.
            // Точка части тела в координатах КОМНАТЫ — тех же, в которых
            // работают getPosition/setPosition и всё остальное снаружи.
            //
            // Пересчёт идёт в систему worldLayer, а НЕ svg. Разница появилась
            // вместе с камерой: worldLayer сдвинут на -camX, и пересчёт в
            // систему svg давал бы ЭКРАННЫЕ координаты. По этой точке
            // кладутся кучки на пол, а рисуются они внутри worldLayer — то
            // есть в комнате, — и кучка ложилась бы мимо червя ровно на сдвиг
            // камеры. Там, где комнаты нет (мини-игры), worldLayer без
            // трансформации и обе системы совпадают.
            getPartPoint(partName) {
                const el = svg.querySelector(`[data-part="${partName}"]`);
                if (!el || !el.getScreenCTM || !worldLayer.getScreenCTM) {
                    return { x: state.wormX, y: state.wormY };
                }
                try {
                    const box = el.getBBox();
                    const pt = svg.createSVGPoint();
                    pt.x = box.x + box.width / 2;
                    pt.y = box.y + box.height / 2;
                    // Порядок умножения важен: нужно СНАЧАЛА перевести точку
                    // из части в экран (el), и только потом из экрана в
                    // worldLayer (обратная матрица). Это W⁻¹ × E, а не
                    // E × W⁻¹.
                    //
                    // Ошибка не всплывала годами, потому что обе матрицы были
                    // переносами, а переносы переставимы. Сломалось на первом
                    // же зеркальном персонаже (opts.flip у противника в
                    // гневе): scale(-1,1) с переносом не переставляется, и
                    // точка части уезжала за пределы сцены.
                    const local = pt.matrixTransform(worldLayer.getScreenCTM().inverse().multiply(el.getScreenCTM()));
                    return { x: local.x, y: local.y };
                } catch (err) {
                    return { x: state.wormX, y: state.wormY };
                }
            },

            // ---------- ПИЩЕВАРЕНИЕ ----------
            // Рендерер не считает время и не знает про еду ничего, кроме
            // «нарисуй комки вот в этих точках тракта». Куда они доехали —
            // считает вызывающий по метке времени кормёжки (worm.js).
            //
            //   boluses    — [{ s: 0..1 вдоль тракта, size: доля толщины }]
            //   stomachFill — 0..1, насколько наполнен желудок
            setDigestion(data) {
                const d = data || {};
                const tract = state.built && state.built.gutTract;
                if (tract && tract.foodLayer) {
                    const list = d.boluses || [];
                    const pts = tract.corePts || [];

                    // Узлы переиспользуются: комков три-четыре, создавать их
                    // заново каждый кадр незачем.
                    while (tract.foodNodes.length < list.length) {
                        const node = svgEl('ellipse', { class: 'worm-food', rx: 0, ry: 0, cx: 0, cy: 0 });
                        tract.foodLayer.appendChild(node);
                        tract.foodNodes.push(node);
                    }
                    tract.foodNodes.forEach((node, i) => {
                        const b = list[i];
                        if (!b || pts.length < 2) { node.setAttribute('rx', 0); node.setAttribute('ry', 0); return; }
                        // Позиция считается по точкам осевой линии — сложение
                        // и умножение вместо промера пути.
                        const fs = Math.max(0, Math.min(1, b.s)) * (pts.length - 1);
                        const i0 = Math.min(pts.length - 2, Math.floor(fs));
                        const k = fs - i0;
                        const a = pts[i0], c = pts[i0 + 1];
                        const pt = { x: a[0] + (c[0] - a[0]) * k, y: a[1] + (c[1] - a[1]) * k };
                        // Направление в этой точке — комок вытянут вдоль кишки,
                        // а не поперёк: он её растягивает, а не лежит поперёк.
                        const ang = Math.atan2(c[1] - a[1], c[0] - a[0]) * 180 / Math.PI;
                        const size = (b.size || 1) * (d.scale || 7);
                        node.setAttribute('cx', 0);
                        node.setAttribute('cy', 0);
                        node.setAttribute('rx', (size * 1.35).toFixed(1));
                        node.setAttribute('ry', size.toFixed(1));
                        node.setAttribute('fill', b.color || mixColor(BILE[400], GRIME_SHADOW, 0.35));
                        node.setAttribute('opacity', b.opacity != null ? b.opacity : 0.9);
                        node.setAttribute('transform',
                            `translate(${pt.x.toFixed(1)},${pt.y.toFixed(1)}) rotate(${ang.toFixed(1)})`);
                    });
                }

                // Наполненный желудок слегка раздувается — но остаётся
                // желудком, а не превращается в шар.
                const fill = Math.max(0, Math.min(1, d.stomachFill || 0));
                const content = state.built && state.built.root
                    ? state.built.root.querySelector('.worm-stomach-content') : null;
                if (content) {
                    const fx = parseFloat(content.getAttribute('data-full-rx')) || 0;
                    const fy = parseFloat(content.getAttribute('data-full-ry')) || 0;
                    content.setAttribute('rx', (fx * fill).toFixed(1));
                    content.setAttribute('ry', (fy * fill).toFixed(1));
                }
            },

            // ---------- ЧТО ЛЕЖИТ НА ПОЛУ ----------
            // Комната принадлежит рендереру, поэтому и предметы в ней рисует
            // он: тогда они живут в тех же координатах и получают ту же
            // перспективу, что и персонаж.
            setRoomObjects(list) {
                const layer = objectLayer;
                if (!layer) return;
                while (layer.firstChild) layer.removeChild(layer.firstChild);

                state.roomObjects = (list || []).filter(o => o.x != null && o.y != null);
                state.roomObjects.forEach(obj => {
                    const depthScale = (opts.room && state.room)
                        ? roomCharScaleAt(roomDepthAt(state.room, obj.y)) : 1;
                    const g = buildPoopNode(obj, depthScale);
                    g.setAttribute('data-poop-id', obj.id);
                    g.style.cursor = 'pointer';

                    // Обработчик висит на самом предмете, а не считает
                    // попадание по координатам. Разница видна, когда червь
                    // стоит над кучкой: событие достаётся ему, и убрать
                    // кучку нельзя, пока он не отойдёт. Так и задумано —
                    // тело физически загораживает пол, а тап по самому
                    // червю в будущем станет способом с ним повозиться.
                    g.addEventListener('pointerdown', (e) => {
                        e.stopPropagation();
                        if (typeof opts.onRoomObjectTap === 'function') opts.onRoomObjectTap(obj.id);
                    });
                    layer.appendChild(g);
                });
            },
            // Прямой доступ к SVG для точечных вещей (хит-тест по конкретной
            // части, разовая подстройка стиля мини-игрой). Ищи части по
            // '[data-part="tail"]', '[data-part="belly"]' и т.п.
            svgRoot: svg,
            getMergedModel: mergedModel,

            // ---------- ПАУЗА ----------
            // Остановить кадровый цикл, не разбирая персонажа.
            //
            // Зачем: у рендерера уже есть проверка «сцену не видно» (см.
            // isStageVisible), но она ловит только спрятанное стилями или
            // выкинутое из документа. Персонаж главного экрана под ОТКРЫТОЙ
            // мини-игрой по всем признакам виден — его просто закрыли сверху
            // непрозрачным окном. И он продолжает считать кадры: на медленном
            // телефоне в бою гнева это третий живой червь поверх двух бойцов.
            //
            // Метка времени сбрасывается, иначе после паузы dt окажется равным
            // всей паузе и персонаж прыгнет.
            setPaused(paused) {
                if (paused) {
                    if (state.rafId) {
                        cancelAnimationFrame(state.rafId);
                        state.rafId = null;
                    }
                } else if (!state.rafId) {
                    state.lastFrameTs = 0;
                    state.rafId = requestAnimationFrame(tick);
                }
            },

            destroy() {
                if (state.rafId) cancelAnimationFrame(state.rafId);
                window.removeEventListener('resize', onResize);
                svg.removeEventListener('pointerdown', onStageDown);
                svg.removeEventListener('pointermove', onStageMove);
                svg.removeEventListener('pointerup', onStageUp);
                svg.removeEventListener('pointercancel', onStageUp);
                container.innerHTML = '';
            }
        };
    }
};

window.WormRenderer = WormRenderer;
